// Banco de prompts de diseño para la Galería de diseño. Cada item define un sector, un tipo
// de layout (para elegir la miniatura wireframe), nombre, descripción y el prompt detallado.
// Generado con agentes en paralelo; se puede ampliar libremente.

export type LayoutDiseno =
  | "hero"
  | "dashboard"
  | "mobile"
  | "cards3"
  | "grid"
  | "split"
  | "form"
  | "list"
  | "chat"
  | "scene3d"

export type PlantillaDiseno = {
  sector: string
  layout: LayoutDiseno
  nombre: string
  descripcion: string
  prompt: string
}

export const PLANTILLAS_DISENO: PlantillaDiseno[] = [
  { sector: "3D", layout: "scene3d", nombre: "Órbita de Producto Premium", descripcion: "Zapatilla 3D con órbita interactiva", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN (unpkg r160, importmap con OrbitControls y RGBELoader). Escena de un producto hero (zapatilla o botella de perfume) en modelo glTF, iluminado con HDRI de estudio para PBR fotorrealista. Fondo gradiente radial carbón #0a0a0f a #16161d, piso con reflejo suave (MeshReflectorMaterial simulado con plano y blur). OrbitControls con damping 0.08, autoRotate lento a 0.4, límite polar para no ver debajo. Tipografía Neue Montreal / Space Grotesk en overlay: título gigante 96px peso 300 con tracking negativo, precio y CTA glassmorphism abajo-derecha. Al hacer hover sobre hotspots (esferas emisivas pulsantes) aparecen tooltips con specs animados por GSAP (fade+slide 0.4s ease power2). Acento neón lima #c4ff3d en bordes y hotspots. Bloom sutil vía UnrealBloomPass, tone mapping ACESFilmic. Loader con barra de progreso minimalista." },
  { sector: "3D", layout: "scene3d", nombre: "Globo de Datos Global", descripcion: "Globo terráqueo con puntos y arcos", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Globo terráqueo esférico con textura de tierra oscura estilo dashboard (mapa de puntos dot-matrix generado por shader sobre una esfera), atmósfera con fresnel glow cian #38bdf8 en el borde. Sobre la superficie, ~40 puntos de datos como pilares emisivos y arcos animados (curvas cuádricas bezier) que viajan entre ciudades con partículas corriendo por el trazo. Paleta noche profunda: fondo #05060a, océanos #0e1628, datos cian y magenta #e879f9. Rotación automática suave, OrbitControls con zoom limitado e inercia. Estrellas de fondo con Points y tamaño aleatorio parpadeante. Panel lateral izquierdo tipo terminal con contador de conexiones en vivo (números animados con GSAP), tipografía mono JetBrains Mono. Tooltips al hover sobre cada pilar mostrando ciudad y métrica. Bloom para los arcos, DPR limitado a 2." },
  { sector: "3D", layout: "scene3d", nombre: "Partículas Reactivas al Mouse", descripcion: "Nube de partículas GPU que huye del cursor", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN usando BufferGeometry y ShaderMaterial (GLSL custom). Campo de 100.000 partículas distribuidas en una malla plana ondulante que reacciona al mouse: raycaster proyecta la posición y un vertex shader empuja las partículas cercanas con falloff radial suave, volviendo a su origen con resorte elástico. Color por gradiente HSL según velocidad, de índigo #4f46e5 a rosa #f472b6, additive blending sobre fondo negro puro #000. Partículas como puntos con textura circular soft y atenuación por distancia. Movimiento base con ruido simplex en el shader para respiración orgánica constante. Post-proceso con bloom leve. Overlay tipográfico minimal: kicker en Inter uppercase con letter-spacing amplio arriba-izquierda. FPS estable priorizando el shader sobre CPU. Cursor personalizado como anillo que sigue con lerp." },
  { sector: "3D", layout: "scene3d", nombre: "Shader de Olas Oceánicas", descripcion: "Superficie de agua con gerstner waves", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Plano de alta subdivisión (256x256) deformado en el vertex shader con suma de olas de Gerstner para un océano estilizado realista. Fragment shader con fresnel para reflejo de cielo, espuma en las crestas (smoothstep sobre la altura) y color profundo teal #0f766e mezclando a turquesa claro #5eead4 en picos. Cielo con gradiente atardecer (naranja durazno #fb923c al horizonte, violeta #6d28d9 en cenit) y sol como disco emisivo con halo. Cámara baja rozando el agua, leve cabeceo automático. OrbitControls suaves. Caústicas sugeridas con ruido animado. Reflejo del sol como sendero brillante que se deforma con las olas. UI mínima flotante: título 'FLUX' en tipografía serif display alta contraste, esquina inferior. Tone mapping cinematográfico, niebla exponencial hacia el horizonte." },
  { sector: "3D", layout: "scene3d", nombre: "Texto 3D Extruido Cinético", descripcion: "Tipografía extruida metálica animada", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN (TextGeometry + FontLoader con font typeface, o extrusión de shapes). Palabra hero 'STUDIO' extruida en 3D con material cromado metálico (metalness 1, roughness 0.15) reflejando un HDRI de estudio, bisel en los bordes. Cada letra entra escalonada con GSAP: rota desde -90° en X y sube con overshoot elástico, stagger 0.08s. Fondo degradado plata frío #e5e7eb a #9ca3af con viñeta. Luz rim intensa cian por un lado y magenta por el otro para reflejos dicroicos en el cromo. Al mover el mouse, todo el grupo hace parallax de rotación suave (lerp) siguiendo el cursor. Piso reflectante con desvanecido. Sombras de contacto suaves. Debajo, subtítulo en Helvetica Now / Arial peso medio tracking wide. Bloom sutil en los highlights especulares." },
  { sector: "3D", layout: "scene3d", nombre: "Galería 3D en Carrusel Cilíndrico", descripcion: "Portafolio en carrusel curvo navegable", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Carrusel de 8 paneles de imagen dispuestos en anillo cilíndrico mirando al centro, cada uno como PlaneGeometry con textura y borde redondeado (shader de esquinas). Rotación del anillo con drag horizontal (pointer events) e inercia amortiguada; snap al panel más cercano con GSAP al soltar. El panel frontal se agranda y se ilumina, los laterales se atenúan y desaturan (uniform de opacidad y grayscale en shader). Fondo oscuro editorial #111114 con foco de luz central. Reflejo tenue de los paneles en un piso oscuro. Tipografía Editorial New / serif para el título del proyecto activo, que hace crossfade al cambiar de panel. Indicador de posición con puntos abajo. Parallax leve de la cámara con el mouse. Transiciones con ease power3.inOut." },
  { sector: "3D", layout: "scene3d", nombre: "Planeta Alienígena en el Espacio", descripcion: "Planeta con anillos y nebulosa", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Escena espacial con un planeta gaseoso: esfera con textura procedural de bandas generada por shader (fbm noise), atmósfera fresnel violeta #a78bfa y anillos planetarios como disco con textura de opacidad radial y partículas orbitando. Nebulosa de fondo con sprites de humo additive en tonos magenta #db2777 e índigo #3730a3, y campo de estrellas de tres capas con parallax (Points). Rotación lenta del planeta sobre eje inclinado; los anillos captan una luz rim cálida. Cámara con OrbitControls e inercia, dolly limitado. Pequeña luna orbitando con trail. Overlay HUD sci-fi minimal: coordenadas y nombre del planeta en tipografía mono con líneas finas y esquinas de marco. UnrealBloom fuerte en estrellas y atmósfera, tone mapping ACES. Lens flare del sol lateral." },
  { sector: "3D", layout: "scene3d", nombre: "Terreno Low-Poly Infinito", descripcion: "Montañas low-poly con día-noche", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Terreno low-poly generado por ruido simplex sobre un PlaneGeometry con flatShading para facetas visibles, coloreado por altura mediante vertex colors: valles verde salvia #4d7c4d, laderas terracota #a3603f, picos nevados blanco. Cielo con gradiente que cicla lento entre amanecer, día y crepúsculo; luz direccional (sol) orbitando y cambiando de color cálido a azulado, con sombras low-poly. Niebla que funde el horizonte con el cielo para profundidad. Cámara en vuelo lento hacia adelante con leve bobbing, sensación de dron. Agua low-poly en los valles como plano semitransparente con brillo especular. Árboles como conos simples esparcidos. Estética Firewatch / poligonal. Overlay tipográfico sans geométrica (Poppins) con nombre de bioma esquina superior. Ambiente hemisférico para relleno suave." },
  { sector: "3D", layout: "scene3d", nombre: "Portal Dimensional", descripcion: "Anillo de portal con vórtice de energía", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Portal circular vertical: anillo toroidal con material emisivo y un disco interior con shader de vórtice (coordenadas polares + ruido animado en espiral) que succiona luz hacia el centro, colores de fuego arcano naranja #f97316 a cian eléctrico #22d3ee en el borde. Partículas siendo aspiradas hacia el vórtice desde el entorno con additive blending y trails. Chispas orbitando el aro. Fondo cavernoso oscuro con leve niebla volumétrica sugerida y reflejo del portal en un piso húmedo. Distorsión chromatic aberration creciente cerca del centro (post shader). La cámara respira acercándose y alejándose sutilmente; al hover el vórtice acelera su giro (GSAP a uniform de velocidad). Bloom intenso. Título 'ENTER' con tipografía display condensada que titila con el resplandor. Sonido opcional omitido." },
  { sector: "3D", layout: "scene3d", nombre: "Doble Hélice de ADN", descripcion: "ADN girando con pares de bases", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Doble hélice de ADN construida proceduralmente: dos backbones de esferas siguiendo curvas helicoidales opuestas (seno/coseno sobre el eje Y) unidas por 'peldaños' de cilindros (pares de bases) coloreados en cuatro tonos vivos (adenina cian #06b6d4, timina rosa #ec4899, guanina ámbar #f59e0b, citosina verde #10b981). Material glossy con leve emisión. Rotación continua sobre el eje vertical, y entrada escalonada de cada peldaño de abajo hacia arriba con GSAP (scale+fade). Fondo laboratorio oscuro #0b1220 con gradiente sutil y bokeh de partículas flotando (depth of field falso). Luz rim azul y contraluz para volumen. OrbitControls con inercia para inspeccionar. Al hover sobre un par de bases, tooltip con su nombre. Bloom en las emisiones. Título vertical lateral en tipografía mono science 'GENOME' con tracking amplio." },
  { sector: "3D", layout: "scene3d", nombre: "Configurador de Auto 3D", descripcion: "Coche 3D con cambio de color en vivo", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN (glTF loader, HDRI). Configurador de vehículo: modelo de auto en material car paint (clearcoat alto, metallic flake sugerido) sobre plataforma giratoria en estudio con HDRI y piso reflectante degradado. OrbitControls con autoRotate y límites para mantener la vista heroica. Fila de swatches de color abajo-centro (glassmorphism); al elegir uno, la carrocería transiciona de color con GSAP interpolando el material y un breve destello especular. Luces de estudio de tres puntos con softbox reflejados en la chapa. Toggle día/noche que cambia HDRI y enciende faros emisivos con volumétrico. Tipografía automotriz elegante (Saol / serif alto contraste) para el nombre del modelo, specs en sans mono. Sombra de contacto suave bajo el auto. Bloom en cromos y faros, ACES tone mapping. Loader premium con logo pulsante." },
  { sector: "3D", layout: "scene3d", nombre: "Cristal Refractivo Flotante", descripcion: "Gema con refracción y dispersión", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Cristal geométrico facetado (icosaedro o forma custom) con material de transmisión física (transmission 1, ior 2.4, thickness, dispersión chromatic) refractando un entorno colorido HDRI, flotando y rotando lento. Detrás, formas abstractas de color (gradiente mesh) que se ven distorsionadas a través de la gema para lucir la refracción. Paleta joya: fondo malva #2e1065, luces esmeralda #34d399 y coral #fb7185 que crean caústicas de color en los bordes. Al mover el mouse, el cristal reorienta con parallax suave y la dispersión brilla más en los cantos (fresnel). Post-proceso: bloom y grano fino de película. Piso invisible con sombra de contacto para anclar. Tipografía luxury serif 'PRISM' en overlay con animación de reveal por máscara. DPR y samples de transmisión ajustados para fluidez." },
  { sector: "3D", layout: "scene3d", nombre: "Blob Metaball Orgánico", descripcion: "Metaballs fluidas con material iridiscente", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN usando MarchingCubes para metaballs. Masa orgánica de 6-8 metaballs que se fusionan y separan flotando con movimiento perlin, superficie lisa con material iridiscente (iridescence + clearcoat) que cambia de tono según el ángulo como aceite sobre agua: turquesa, violeta, rosa, dorado. Fondo estudio suave gradiente crema #f5f3ff a lila pálido, iluminación soft box envolvente para reflejos cremosos. Las metaballs orbitan un centro y una sigue al mouse con lerp, deformando la masa al pasar cerca. Rotación general lenta. Sombra de contacto blanda. Estética Apple-like / soft 3D premium. Overlay tipográfico grande sans humanista peso ligero centrado abajo. Sin bloom agresivo, brillo controlado. Resolución de MarchingCubes moderada para mantener 60fps." },
  { sector: "3D", layout: "scene3d", nombre: "Ciudad Wireframe Synthwave", descripcion: "Rejilla retro con sol y montañas neón", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Paisaje synthwave: rejilla infinita de terreno wireframe desplazándose hacia la cámara (desplazamiento de UV/posición Z con loop) con montañas generadas por ruido, líneas neón magenta #ff2d95 sobre negro. Sol retro de bandas horizontales (shader con líneas cortadas en degradé naranja #ff8a00 a rosa #ff0080) en el horizonte, cielo estrellado con gradiente índigo profundo. Niebla que oculta el límite de la rejilla. Reflejo del sol en un 'suelo' brillante. Movimiento constante estilo drive at night. Post: bloom fuerte, chromatic aberration leve, scanlines sutiles y grano CRT. Tipografía retro-futurista (Monument Extended / italic bold) 'NEON DRIVE' con glow. Cámara baja rozando la rejilla con leve vaivén. Sensación Outrun / retrowave inmersiva." },
  { sector: "3D", layout: "scene3d", nombre: "Sistema Solar Interactivo", descripcion: "Planetas orbitando el sol con datos", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Modelo del sistema solar estilizado: sol emisivo central con corona (shader de ruido pulsante y bloom fuerte) y planetas orbitando en elipses a distintas velocidades, cada uno con textura o color propio y luna donde corresponda; líneas de órbita como anillos finos semitransparentes. Cinturón de asteroides como Points instanciados. Fondo starfield con parallax de capas. OrbitControls para navegar; al clickear un planeta la cámara hace tween con GSAP hasta encuadrarlo y aparece un panel de datos (diámetro, período) en glassmorphism con tipografía mono espacial. Escala de tiempo ajustable con un slider. Sombras de planetas proyectadas del sol. Paleta cósmica realista con acentos cian en la UI. Tone mapping ACES, atmósferas fresnel en los planetas gaseosos." },
  { sector: "3D", layout: "scene3d", nombre: "Cubo de Pantallas Multimedia", descripcion: "Cubo con video en cada cara", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Cubo 3D flotante donde cada una de las 6 caras es una pantalla con textura de video (VideoTexture) o canvas animado, bordes biselados con marco metálico oscuro y leve emisión en las juntas. Rotación con drag e inercia (OrbitControls damping), autoRotate suave en reposo. Al detenerse en una cara frontal, esa pantalla sube su brillo y las demás se atenúan; overlay lateral muestra el título del contenido con crossfade (GSAP). Fondo estudio oscuro con gradiente y reflejo del cubo en piso pulido. Luz rim dual cian/naranja para separar del fondo. Partículas de polvo flotando sutiles. Tipografía sans técnica (Suisse / Inter) para captions. Bloom leve en las juntas emisivas. Sombra de contacto blanda. Cursor grab/grabbing personalizado." },
  { sector: "3D", layout: "scene3d", nombre: "Bandera de Tela Ondulante", descripcion: "Textil animado con simulación de viento", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Plano textil de alta subdivisión ondulando como bandera al viento mediante vertex shader (suma de senos con ruido para turbulencia y ráfagas), material de doble cara con textura o degradado de marca y microrelieve por normal map procedural para pliegues. Iluminación direccional cálida que genera sombras propias en los pliegues, y luz de relleno fría. Fondo minimal gradiente neutro #fafaf9 a #e7e5e4 con viñeta suave. El viento reacciona al mouse: acercar el cursor intensifica la amplitud de la onda (uniform con lerp). Cámara ligeramente en escorzo mostrando la caída de la tela. Estética editorial premium. Título en tipografía serif display grande superpuesto detrás, parcialmente cubierto por la tela para profundidad. Sombra de contacto en un plano inferior. Movimiento continuo y orgánico, 60fps." },
  { sector: "3D", layout: "scene3d", nombre: "Túnel de Vuelo Infinito", descripcion: "Vuelo por un túnel de anillos neón", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Cámara volando por el interior de un túnel infinito construido con una TubeGeometry a lo largo de una CatmullRomCurve3 sinuosa; la cámara avanza por la curva en loop mientras el túnel se deforma. Paredes con shader de rejilla luminosa que fluye, anillos emisivos espaciados que pasan como destellos, colores cian #00e5ff y magenta #ff00e5 alternando. Partículas viajando en sentido contrario para dar velocidad. Post: bloom intenso, motion blur sugerido por trails, chromatic aberration en los bordes al acelerar. La velocidad reacciona al scroll o al mantener click. Fondo negro absoluto. Overlay HUD con velocímetro animado en tipografía mono. Sensación hyperspace / wormhole. FOV amplio para inmersión, leve roll de cámara en las curvas." },
  { sector: "3D", layout: "scene3d", nombre: "Corazón Anatómico Latiente", descripcion: "Órgano 3D con pulso y datos vitales", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Corazón anatómico (glTF o esfera esculpida) con material subsurface-like rojo profundo #b91c1c, venas más oscuras y brillo húmedo (clearcoat). Anima un latido: escala pulsante en ritmo cardíaco (dos golpes rápidos y pausa) accionada por GSAP con easing personalizado, y una onda de emisión que recorre la superficie en cada latido. Fondo médico oscuro con gradiente azul acero y bokeh. Luz rim cian y contraluz cálida. Alrededor, una línea de ECG dibujándose en un plano/canvas sincronizada al pulso, y BPM en display grande tipografía mono. OrbitControls para inspeccionar con inercia. Partículas de flujo sanguíneo sugeridas orbitando. Bloom en la emisión del latido. Estética visualización médica premium, sobria y elegante." },
  { sector: "3D", layout: "scene3d", nombre: "Tipografía Líquida Metálica", descripcion: "Letras de mercurio que gotean", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Palabra hero con apariencia de mercurio líquido: geometría de texto extruido con material chrome de transmisión metálica muy reflectante (metalness 1, roughness bajo, HDRI) y un vertex shader que añade ondulación viscosa constante como si la superficie fluyera. Gotas metálicas se desprenden y caen (esferas con physics simple) fusionándose en un charco reflectante debajo. Fondo estudio gradiente grafito con luces de color índigo #6366f1 y ámbar #f59e0b para reflejos dicroicos. Al hover, las letras se derriten un poco más (uniform de viscosidad con GSAP) y recuperan forma al salir. Piso espejo con blur. Post: bloom en highlights, leve grano. Cámara con parallax al mouse. Estética premium tipo campaña de moda / editorial de lujo. Subtítulo sans grotesk minimal debajo." },
  { sector: "3D", layout: "scene3d", nombre: "Enjambre de Boids 3D", descripcion: "Bandada de partículas con comportamiento", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Enjambre de ~800 agentes (conos o InstancedMesh de peces/aves) con algoritmo boids en 3D: separación, alineación y cohesión, más atracción/repulsión al puntero del mouse proyectado en el espacio. Se mueven en formaciones fluidas dentro de un volumen invisible, orientándose según su velocidad. Color por velocidad o profundidad en gradiente cian #2dd4bf a azul #1d4ed8. Fondo abismal degradado azul noche con leve niebla para dar profundidad (los lejanos se desvanecen). Luz direccional suave y ambiente para volumen. Cámara con OrbitControls e inercia orbitando el enjambre. Rastros sutiles opcionales con additive. Overlay minimal con contador de agentes en mono. Estética murmuration / vida artificial. Optimizado con InstancedMesh y grid espacial para el vecindario, apuntando a 60fps." },
  { sector: "3D", layout: "scene3d", nombre: "Reloj Mecánico de Engranajes", descripcion: "Engranajes girando en sincronía", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Mecanismo de relojería: múltiples engranajes de distintos diámetros (geometría procedural de dientes por extrusión) engranados y girando en sincronía a velocidades inversamente proporcionales a su tamaño, en material latón/bronce pulido (metalness alto, roughness medio) con HDRI de taller. Ejes, tornillos y placas de soporte para riqueza de detalle. Iluminación cálida dorada con reflejos especulares y sombras de contacto entre piezas. Fondo oscuro vignette color café #1c1410. OrbitControls con inercia para inspeccionar el ensamble desde cualquier ángulo, autoRotate lento. Partículas de polvo dorado flotando en un haz de luz. Post: bloom sutil en highlights, grano fino. Tipografía serif clásica grabada 'HOROLOGY' en overlay con estilo relojería fina. Movimiento continuo hipnótico, engranajes perfectamente acoplados." },
  { sector: "3D", layout: "scene3d", nombre: "Nube de Puntos Escaneada", descripcion: "Retrato point-cloud reactivo", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN con BufferGeometry y ShaderMaterial. Forma reconocible (rostro, mano o logo) representada como nube de puntos densa; en reposo mantiene la silueta, y al acercar el mouse los puntos cercanos se dispersan con un empuje y ruido, reformándose luego con resorte. Cada punto varía tamaño y brillo con un pulso sutil (seno + offset aleatorio en el shader). Paleta holograma: puntos cian #22d3ee y blanco sobre negro absoluto, additive blending. Rotación lenta automática de la nube. Líneas de escaneo horizontales que barren la forma revelando profundidad (uniform animado). Post: bloom y leve glitch/RGB shift ocasional. Overlay HUD de escáner con esquinas de marco y texto mono 'SCANNING…'. Estética hologram / data-portrait sci-fi. 60fps con decenas de miles de puntos." },
  { sector: "3D", layout: "scene3d", nombre: "Isla Flotante Diorama", descripcion: "Diorama low-poly flotante en burbuja", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Diorama miniatura de una isla flotante low-poly: roca invertida abajo, césped y algún árbol, cascada que cae al vacío (plano con shader de agua descendente) y pequeñas nubes orbitando, todo dentro de una esfera de cristal (material de transmisión) como snow globe. Flota y rota suavemente con bobbing vertical (seno). Paleta pastel encantadora: césped menta #86efac, roca lavanda #c4b5fd, cielo durazno #fed7aa de fondo con gradiente soft. Luz cálida direccional con sombras suaves y luz de relleno fría. Al hover, la escena gira un poco más rápido y la cascada acelera. Partículas de destello flotando alrededor del globo. Sombra de contacto bajo el globo. Post: bloom muy sutil, tono cálido. Tipografía redondeada amistosa (Quicksand) para un título flotante. Estética diorama cozy / Studio Ghibli minimal." },
  { sector: "3D", layout: "scene3d", nombre: "Onda de Audio Reactiva", descripcion: "Malla que pulsa con frecuencias", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN + Web Audio API. Visualizador de audio 3D: una malla (esfera o plano de terreno) cuyos vértices se desplazan en el vertex shader según el espectro de frecuencias (AnalyserNode, FFT) de una pista o del micrófono, deformándose al ritmo. Los graves inflan el centro, los agudos rizan la superficie. Color por amplitud en gradiente vibrante violeta #7c3aed a cian #06b6d4, con emisión que crece en los picos. Anillos de partículas concéntricos expandiéndose en cada golpe de bajo (beat detection simple). Fondo negro con leve gradiente. OrbitControls con inercia y autoRotate. Post: bloom que late con el volumen (uniform), chromatic aberration en los drops. Overlay mono con nombre de pista y barras VU minimalistas. Botón play/mic glassmorphism. Estética club / motion reactive premium." },
  { sector: "3D", layout: "scene3d", nombre: "Fluido de Humo Volumétrico", descripcion: "Humo curling con raymarching", prompt: "Entregable: HTML+CSS+JS con Three.js por CDN. Plano fullscreen con ShaderMaterial que hace raymarching de humo volumétrico procedural: fbm de ruido animado en 3D formando volutas de humo denso que ascienden y se enroscan, con iluminación interna (densidad hacia luz) para volumen creíble. Paleta ahumada elegante: humo de grafito a perla iluminado por una luz cálida ámbar #f59e0b desde un lado y contraluz azul frío, sobre fondo negro. El humo reacciona al mouse: el cursor introduce una fuerza que aparta y remolina la densidad (uniform de posición). Movimiento ascendente continuo con turbulencia. Grano de película y viñeta para acabado cinematográfico. Overlay tipográfico serif alto contraste 'VAPOR' que se insinúa entre el humo con leve blend. Marcha de rayos con pasos optimizados para mantener fluidez, DPR adaptativo. Estética perfume / cine atmosférico." },
  { sector: "Web", layout: "hero", nombre: "Aurora Studio", descripcion: "Hero con gradiente animado y glow neon", prompt: "Landing de estudio creativo premium estilo AWWWARDS. Dark mode profundo (#050505 base) con un hero de pantalla completa dominado por un gradiente animado malla (mesh gradient) que respira lentamente entre magenta neon (#FF2E9A), violeta electrico (#7C3AED) y cyan (#22D3EE), renderizado en WebGL con shaders GLSL sobre canvas. Tipografia editorial gigante: display serif variable (tipo Editorial New) de 12vw para el titular, con kerning ajustado y subtitulo en mono (Space Mono) uppercase con letter-spacing amplio. Glow neon real via drop-shadow multicapa. Cursor custom: circulo con blend-mode difference que invierte lo que toca, con trailing suave via GSAP. Scroll-driven: al bajar, el gradiente se contrae hacia una esfera y el titular se separa en letras con stagger (GSAP ScrollTrigger + SplitText). Grano animado overlay. Entregable: HTML+CSS+JS con GSAP y Three.js por CDN, index autonomo, 60fps, responsive." },
  { sector: "Web", layout: "grid", nombre: "Bento Metrics", descripcion: "Dashboard bento glassmorphism para SaaS", prompt: "Home de producto SaaS con layout bento grid asimetrico (celdas de distinto tamano, gap 20px, radius 28px). Glassmorphism sobre fondo dark (#0A0B10) con blobs de color desenfocados detras (backdrop-filter blur 40px). Cada tarjeta es vidrio esmerilado con borde 1px en gradiente sutil y highlight superior. Paleta: indigo (#6366F1), verde menta (#34D399), ambar (#FBBF24). Tipografia Inter, numeros grandes tabulares con count-up al entrar en viewport. Una celda con grafico de area que se dibuja con stroke-dashoffset. Hover: tilt 3D siguiendo el mouse (perspective + rotateX/Y) y elevacion de sombra. Reveal escalonado de celdas con GSAP al cargar (clip-path + opacity). Cursor custom punto magnetico. Entregable: HTML+CSS+JS con GSAP por CDN, autonomo, grid que colapsa a 1 columna en mobile." },
  { sector: "Web", layout: "split", nombre: "Brutal Type", descripcion: "Portfolio brutalista tipografico split", prompt: "Portfolio de disenador brutalista con layout split 50/50. Izquierda fondo crema papel (#EDE8DE) con tipografia negra gigantesca grotesca (Neue Haas) de 9vw en caja, bordes duros 2px negros. Derecha panel negro (#0D0D0D) con lista de proyectos en mono numerada con ceros (01 — 24), lineas divisorias completas. Sin sombras suaves: box-shadow offset duro (8px 8px 0 #000) neobrutalista. Acento rojo bermellon (#E63915). Hover en proyecto: la palabra gigante izquierda hace swap tipo maquina de escribir (SplitText char flip) y el fondo invierte. Scroll horizontal en galeria con GSAP ScrollTrigger scrub. Cursor custom crosshair de dos lineas que se expande. Transiciones de pagina con panel solido que barre. Entregable: HTML+CSS+JS con GSAP por CDN, un archivo, responsive apilando en mobile." },
  { sector: "Web", layout: "hero", nombre: "Liquid Chrome", descripcion: "Hero 3D con esfera cromada metalica", prompt: "Landing de marca de lujo con hero Three.js: esfera de cromo liquido (MeshStandardMaterial metalness 1, roughness 0.05) con environment map HDRI que refleja un estudio, distorsionandose organicamente con noise en el vertex shader. Fondo negro absoluto (#000) con foco calido unico. Titular en display condensada uppercase (PP Neue Machina) colocado detras y delante de la esfera para profundidad. Paleta plata/negro con acento dorado (#C9A44C). El mouse rota suave la esfera (lerp) y aumenta la distorsion. Scroll: la esfera se funde hacia abajo y revela seccion editorial. Cursor custom punto con estela metalica. Preloader con porcentaje en mono y barra. Entregable: HTML+CSS+JS con Three.js por CDN, autonomo, fallback estatico sin WebGL, responsive." },
  { sector: "Web", layout: "grid", nombre: "Editorial Press", descripcion: "Revista digital editorial tipografia enorme", prompt: "Home de revista digital editorial de moda premium. Grilla tipo periodico moderno: columnas asimetricas, reglas hairline 1px separando bloques, mucho espacio blanco. Fondo blanco roto (#FAFAF7), tinta casi negra (#141414). Masthead en serif alto contraste (Didot/GT Sectra) de 14vw con ligaduras, bajadas en sans humanista. Acento risograph naranja (#FF5C35). Imagenes b&n con duotono al hover. Scroll-driven: titulares con parallax a distinta velocidad que las imagenes (GSAP ScrollTrigger), reglas que se dibujan al entrar. Numero de edicion rotado 90 grados en el margen. Cursor custom que muestra LEER sobre articulos. Transicion de pagina tipo cortina de papel. Entregable: HTML+CSS+JS con GSAP por CDN, index autonomo, tipografia fluida con clamp, responsive a 1 columna." },
  { sector: "Web", layout: "hero", nombre: "Neon Grid City", descripcion: "Hero cyber con grid neon en perspectiva", prompt: "Landing de app de eventos nocturnos, synthwave premium refinado. Hero dark (#07060F) con grid de lineas neon en perspectiva desplazandose al horizonte animado en canvas, cyan (#00E5FF) y magenta (#FF00A0) con bloom. Sol partido por lineas al fondo con gradiente. Titular en geometrica ancha (Monument Extended) con glow neon y glitch RGB-split intermitente. Particulas flotando en canvas. Scroll: la camara del grid acelera y transiciona a line-up en cards oscuras. Barras audio-reactive que laten. Cursor custom con estela de particulas. Transiciones con flash y chromatic aberration. Entregable: HTML+CSS+JS con canvas nativo + GSAP por CDN, autonomo, respeta prefers-reduced-motion, responsive." },
  { sector: "Web", layout: "split", nombre: "Glass Split Fintech", descripcion: "Fintech split glass con mockup flotante", prompt: "Landing de fintech premium split: izquierda copy y CTA, derecha mockup de app flotando en 3D. Fondo dark azulado (#0B1120) con aurora de gradientes suaves detras (radiales azul #3B82F6 y verde #10B981) desenfocados. La tarjeta mockup es glassmorphism (blur 30px, borde luminoso) que flota con idle loop (translateY) y parallax 3D al mover el mouse. Titular en grotesca moderna (General Sans) de 5vw, peso variable animando de 300 a 700 al entrar. Metricas con count-up. Chips de vidrio con iconos. Boton CTA con borde gradiente conico girando y glow al hover. Scroll revela features en bento glass. Cursor custom halo. Entregable: HTML+CSS+JS con GSAP por CDN, un archivo, responsive apilando columnas." },
  { sector: "Web", layout: "grid", nombre: "Museo Digital", descripcion: "Galeria de arte grid con scroll horizontal", prompt: "Sitio de galeria de arte contemporaneo, minimalismo de lujo. Fondo blanco galeria (#FFFFFF) con muchisimo aire, serif fina (GT Sectra Fine) para titulos y mono diminuto para captions. Grid de obras que en la seccion principal se convierte en scroll horizontal suave (GSAP ScrollTrigger pin + scrub) recorriendo las piezas como en sala. Cada obra revela ficha con reveal de mascara (clip-path inset). Neutros con acento cobalto (#1D3FED). Hover: la imagen se agranda sutil y aparece ano y tecnica. Cursor custom DRAG con flechas durante el scroll horizontal. Numeracion de sala en romano. Transicion a detalle tipo zoom compartido (GSAP Flip). Entregable: HTML+CSS+JS con GSAP + Flip por CDN, autonomo, responsive que pasa a scroll vertical en mobile." },
  { sector: "Web", layout: "hero", nombre: "Particle Bloom", descripcion: "Hero de particulas WebGL formando texto", prompt: "Landing de agencia de innovacion con hero de particulas Three.js: 30k puntos GPU que flotan como polvo y al cargar se ensamblan formando la palabra de la marca, luego se dispersan con fuerza de repulsion al mouse. Fondo degradado noche (#0A0A12 a #131320). Particulas en gradiente coral (#FF6B6B) a violeta (#845EC2). Tipografia de apoyo en sans tecnica (Suisse Intl) minima. Bloom postprocessing (UnrealBloomPass). Scroll: las particulas fluyen hacia la siguiente seccion como corriente. Cursor custom que atrae/repele el enjambre. Preloader con particulas convergiendo. Entregable: HTML+CSS+JS con Three.js + EffectComposer por CDN, autonomo, fallback y prefers-reduced-motion, responsive." },
  { sector: "Web", layout: "split", nombre: "Type Duotone", descripcion: "Split editorial duotono con imagen fija", prompt: "Portfolio de fotografo, split donde una mitad es imagen a sangre fija (position sticky) y la otra scrollea. Imagenes con duotono (azul profundo #0F2A4A y crema #F2E9D8) que al entrar en viewport revelan su color real con transicion de filtro. Tipografia editorial contrastada: serif display para nombres de series, mono para metadatos EXIF. Fondo negro carbon (#111). Scroll-driven: al cambiar de proyecto la imagen sticky hace crossfade con mask wipe y el titulo se desliza. Contador de foto (03/18) animado. Cursor custom tipo mira de camara con esquinas. Transiciones de pagina con obturador. Entregable: HTML+CSS+JS con GSAP ScrollTrigger por CDN, un index, responsive apilando imagen arriba y texto abajo." },
  { sector: "Web", layout: "grid", nombre: "Aurora Bento Portfolio", descripcion: "Portfolio bento con auroras y glow", prompt: "Portfolio personal de developer en bento grid moderno. Fondo dark casi negro (#08080C) con auroras boreales de gradiente suaves moviendose lento detras (verde #2DD4BF, azul #60A5FA, purpura #A78BFA) via background-position. Celdas bento glass, una con avatar, otra con stack en pills, otra con reloj/ubicacion en vivo, otra con enlace a proyectos. Tipografia Satoshi variable, titulos con gradiente de texto animado. Cada celda con spotlight radial que sigue el cursor (radial-gradient en ::before via variables CSS actualizadas por JS). Reveal inicial en cascada. Cursor custom punto con blend. Toggle light/dark con view-transition. Entregable: HTML+CSS+JS vanilla (opcional GSAP CDN), autonomo, responsive con bento que se reordena en mobile." },
  { sector: "Web", layout: "hero", nombre: "Fluid Gradient Wave", descripcion: "Hero con oleaje de gradiente fluido shader", prompt: "Landing de skincare premium, calida y organica. Hero con oleaje de gradiente fluido a pantalla completa via shader (simplex noise en fragment shader sobre canvas full-screen) mezclando durazno (#FFB5A7), rosa palo (#FCD5CE) y crema (#FEC89A) que fluye lento y sedoso. Tipografia serif de contraste medio (Reckless) en 8vw con tracking suelto, en chocolate (#3B2A24). Layout centrado muy respirado. El mouse curva el flujo del gradiente hacia el puntero. Scroll: el hero se comprime en una pastilla redondeada y aparece producto. Cursor custom suave tipo gota. Micro-animaciones con easing organico (elastic). Entregable: HTML+CSS+JS con WebGL shader propio + GSAP por CDN, autonomo, fallback CSS gradient, responsive." },
  { sector: "Web", layout: "split", nombre: "Brutal Mono Agency", descripcion: "Agencia brutalista split monocromo", prompt: "Sitio de agencia creativa brutalista-editorial, split horizontal: barra superior fija negra con nav mono, cuerpo en dos columnas de contraste. Blanco puro (#FFFFFF) vs negro (#000000), cero grises, bordes 1.5px partiendo todo en grilla visible tipo cuaderno. Tipografia: grotesca pesada (Druk) enorme para statements de 10vw y mono (JetBrains Mono) para el resto. Marquee horizontal infinito de servicios (GSAP loop). Acento verde acido (#B6FF00) solo en hover. Scroll: secciones con snap y titulares que hacen scramble text al entrar. Cursor custom bloque cuadrado que invierte colores (mix-blend difference). Transicion de pagina con wipe negro y texto de carga. Entregable: HTML+CSS+JS con GSAP por CDN, un archivo, responsive apilando columnas." },
  { sector: "Web", layout: "hero", nombre: "Video Hero Cinema", descripcion: "Hero cinematografico con video y overlay", prompt: "Landing de productora audiovisual, hero cinematografico con video de fondo a sangre completa (loop, muted, cover) con overlay de gradiente oscuro inferior para legibilidad y grano de pelicula. Titular en display condensada uppercase (Anton) de 11vw con entrada por lineas (mask reveal, clip-path). Barras letterbox animadas que se abren al cargar. Paleta negro, blanco y rojo cinta (#D7263D). Timecode en mono corriendo en la esquina. Scroll: el video se encoge a un marco con radius y aparece el reel en grid con hover que reproduce preview. Cursor custom tipo boton PLAY que crece sobre videos. Transiciones con fundido a negro. Entregable: HTML+CSS+JS con GSAP por CDN, autonomo con placeholder de video, responsive." },
  { sector: "Web", layout: "grid", nombre: "Data Noir Dashboard", descripcion: "Grid de dashboard oscuro con glow de datos", prompt: "Home de plataforma de analitica/IA, grid modular tipo command center oscuro. Fondo grafito (#0C0E12) con tenue grid de puntos. Tarjetas con borde luminoso fino que reacciona (glow verde #39FF88 positivo, ambar alerta). Graficos animados: lineas que se dibujan (stroke-dashoffset), barras con stagger, un sparkline en vivo con requestAnimationFrame. Tipografia mono para numeros tabulares y sans tecnica para labels. Acento electrico (#00D1FF). Hover: borde con gradiente conico girando y tooltip glass. Un heatmap de celdas que pulsan. Cursor custom con reticula fina. Entrada de tarjetas con clip-path escalonado. Entregable: HTML+CSS+JS vanilla + Canvas (opcional GSAP CDN), autonomo con datos mock, responsive que colapsa a stack." },
  { sector: "Web", layout: "split", nombre: "Parallax Layers", descripcion: "Split narrativo con capas parallax profundas", prompt: "Landing storytelling de marca de cafe artesanal, split que alterna imagen y texto por secciones con profundidad parallax multicapa. Cada escena con 3-4 capas (fondo, producto, granos flotando, foreground) a velocidades distintas con scroll (GSAP ScrollTrigger scrub). Paleta terrosa: espresso (#3E2723), crema (#EFE6D9), oliva (#6B7A4F), cobre (#B87333). Serif rustica para titulos y sans limpia para cuerpo. Textura de papel kraft sutil de fondo. Textos con line-mask reveal sincronizados al scroll. Indice de capitulo lateral. Cursor custom tipo sello redondo. Transiciones entre escenas con wipe organico. Entregable: HTML+CSS+JS con GSAP ScrollTrigger por CDN, un index, responsive reduciendo capas en mobile." },
  { sector: "Web", layout: "hero", nombre: "Kinetic Type Loop", descripcion: "Hero de tipografia cinetica en bucle", prompt: "Landing de festival de diseno, hero de tipografia cinetica pura sin imagenes. Palabras gigantes en display variable (Clash Display) que rotan, cambian de peso, se estiran (font-stretch) y corren en marquees a distintas velocidades formando capas de texto. Fondo de color plano vibrante que cambia por seccion (naranja #FF4D00, azul klein #002FA7, verde #00A878). Contraste alto, texto blanco/negro segun fondo. Animado con GSAP timeline en loop mas reaccion al scroll (la velocidad de marquees depende del scroll). Statement central que hace scramble/decode al cargar. Cursor custom que arrastra letras (magnetico). Transiciones de seccion con cambio brusco de color y flash. Entregable: HTML+CSS+JS con GSAP + SplitText por CDN, autonomo, responsive con tamanos fluidos." },
  { sector: "Web", layout: "grid", nombre: "Glass Pricing Bento", descripcion: "Grid de pricing glass con plan destacado glow", prompt: "Pagina de pricing premium en grid glassmorphism sobre fondo dark violeta (#0E0B1A) con blobs radiales purpura y rosa desenfocados. Tres/cuatro planes en tarjetas de vidrio esmerilado, la destacada mas grande con borde de gradiente conico animado y glow neon rosa (#FF4FD8) pulsante. Tipografia display para el precio con count-up al cambiar mensual/anual (toggle con slide y morph de numeros), sans para features con checks que se dibujan. Chips de Popular con shimmer. Hover en plan: levantada 3D y aumento de blur del fondo. Toggle de billing con view-transition. Cursor custom halo magnetico sobre botones. Fondo con particulas sutiles. Entregable: HTML+CSS+JS vanilla (opcional GSAP CDN), un archivo, responsive apilando planes." },
  { sector: "Web", layout: "hero", nombre: "Ripple Interactive", descripcion: "Hero interactivo con ondas al mover mouse", prompt: "Landing de bebida minimal, hero interactivo tipo superficie de agua. Canvas WebGL con simulacion de ripples que se generan donde el usuario mueve o hace click, distorsionando (displacement) un gradiente azul aqua (#4CC9F0 a #4361EE) debajo. Fondo claro luminoso (#F0F9FF). Tipografia sans humanista ligera (Neue Montreal) centrada en azul profundo, con entrada por fade + blur. Reflejos y caustics sutiles. Scroll: la superficie se calma y transiciona a producto flotando con reflejo. Gotas que caen periodicamente generando ondas solas. Cursor invisible (el ripple es el feedback). Preloader tipo llenado de liquido. Entregable: HTML+CSS+JS con WebGL/shader propio + GSAP por CDN, autonomo, fallback estatico, responsive y touch." },
  { sector: "Web", layout: "split", nombre: "Awards Studio Split", descripcion: "Split premium studio con lista y preview live", prompt: "Home de estudio de branding nivel AWWWARDS SOTD. Split: izquierda lista de casos tipografica al 55%, derecha panel sticky que muestra preview de imagen/video del proyecto sobre el que estas (hover-driven). Fondo off-black (#0B0B0B), display serif moderna (PP Editorial) para nombres y mono para anos/sectores. Acento lima suave (#D4FF4F). Hover en item: la palabra se desliza y subraya con linea que se dibuja, el preview derecho hace crossfade con parallax interno y scale. Numeracion 01–20 con lineas divisorias animadas. Scroll suave con inercia (Lenis). Cursor custom VIEW con circulo relleno que crece. Transicion a caso con GSAP Flip (el preview se expande a fullscreen). Entregable: HTML+CSS+JS con GSAP + Flip + Lenis por CDN, autonomo, responsive apilando lista sobre preview." },
  { sector: "Web", layout: "grid", nombre: "Iso Bento 3D", descripcion: "Grid bento con tarjetas isometricas 3D CSS", prompt: "Landing de herramienta de productividad, bento grid con ilustraciones isometricas 3D en CSS (transform-style preserve-3d) que rotan sutil con scroll y mouse. Fondo claro pastel (#F4F1FF) con acentos indigo (#5B4BFF) y coral (#FF7A6B). Glassmorphism ligero en algunas celdas, otras solidas con sombra larga suave. Tipografia geometrica amigable (Cabinet Grotesk), titulos con gradiente. Objetos iso (cubo, grafico, calendario) flotan con idle animation y responden al cursor con tilt paralaje. Reveal escalonado tipo pop (scale + overshoot). Micro-interacciones en cada celda (toggle, contador, checkmark animado). Cursor custom punto suave. Entregable: HTML+CSS+JS vanilla (opcional GSAP CDN), un archivo, responsive con bento a 1-2 columnas." },
  { sector: "Web", layout: "hero", nombre: "Glitch Terminal", descripcion: "Hero cyber-brutalist con terminal y glitch", prompt: "Landing de producto para developers, cyber-brutalist. Fondo negro terminal (#0A0A0A) con scanlines CRT sutiles y grid verde tenue. Hero con statement gigante en mono pesado (IBM Plex Mono) que aparece con tipeo + decode scramble y glitch RGB-split ocasional. A un lado, una ventana de terminal falsa que ejecuta comandos animados linea por linea. Paleta negro, verde fosforo (#00FF66) y acento magenta glitch (#FF0080). Bordes duros, badges cuadrados con version. Scroll: bloques que entran con distorsion horizontal y noise. Cursor custom bloque parpadeante tipo caret. Boton CTA con hover que dispara glitch. Transiciones con barrido de estatica. Entregable: HTML+CSS+JS vanilla (canvas para glitch/noise, opcional GSAP CDN), autonomo, prefers-reduced-motion, responsive." },
  { sector: "Web", layout: "split", nombre: "Chromatic Fashion", descripcion: "Split de moda con transiciones cromaticas", prompt: "Landing de marca de moda de alta costura, split editorial con look-book. Izquierda imagen a sangre de modelo (sticky por seccion), derecha tipografia gigante y coleccion. Paleta audaz por drop: negro con un color-bloque saturado que cambia entre secciones (fucsia #E6007E, naranja #FF6A00, azul #1400C8) en fondos y en aberration cromatico sutil sobre las imagenes al scrollear. Tipografia sans condensada moderna (PP Neue Machina) uppercase enorme + serif de detalle. Imagenes con scale y parallax; titulos con mask por linea. Numeracion de look en romano. Cursor custom tipo SHOP circular. Transicion entre looks con cortina de color en diagonal. Scroll con inercia (Lenis). Entregable: HTML+CSS+JS con GSAP + Lenis por CDN, autonomo, responsive apilando imagen y texto." },
  { sector: "Web", layout: "grid", nombre: "Cosmic Grid Space", descripcion: "Grid espacial dark con estrellas y planeta 3D", prompt: "Landing de startup espacial/deep-tech, grid oscuro cosmico. Fondo negro espacio (#020207) con campo de estrellas en canvas (parallax de 3 capas segun scroll y mouse) y un planeta 3D Three.js con atmosfera (fresnel glow azul #3AA0FF) rotando lento en una celda destacada. Grid asimetrico con tarjetas glass finas mostrando metricas de mision, numeros mono que cuentan. Tipografia display tecnica (Space Grotesk) para titulos, mono para datos. Acentos azul electrico y naranja ignicion (#FF6B2C). Lineas de constelacion que conectan puntos al hover. Reveal de tarjetas con fade + rise escalonado. Cursor custom tipo reticula con coordenadas. Scroll suave, secciones que se pinnean. Entregable: HTML+CSS+JS con Three.js + Canvas por CDN, autonomo, fallback, responsive." },
  { sector: "Web", layout: "hero", nombre: "Morph Blob Studio", descripcion: "Hero con blob organico que morfea SVG", prompt: "Landing de agencia digital juguetona-premium, hero centrado con un gran blob organico que morfea continuamente (SVG path morphing con GSAP MorphSVG o flubber) relleno con gradiente vivo naranja-rosa-morado (#FF9E00, #FF3D77, #A64AC9) y leve grano. El blob sigue suave al cursor y se deforma al hover de los botones. Tipografia grotesca redondeada (General Sans) grande, en gris tinta (#1A1A1A) sobre crema (#FFF8F0). Palabras clave del titular con highlight animado tipo marcador. Scroll: el blob se divide en varios que se distribuyen como secciones. Micro-fisica de resorte en interacciones. Cursor custom magnetico. Entregable: HTML+CSS+JS con GSAP por CDN, autonomo, responsive." },
  { sector: "Web", layout: "split", nombre: "Mono Editorial Journal", descripcion: "Split editorial minimal con indice sticky", prompt: "Sitio de journal de estudio de arquitectura, minimalismo editorial refinado. Split: columna izquierda estrecha con indice/nav sticky y numeracion, columna derecha ancha con contenido tipografico y planos/fotos b&n. Fondo blanco hueso (#F7F6F2), tinta grafito (#1C1C1A), una linea de acento azul acero (#2B4C7E). Tipografia serif de lectura (Lyon) + grotesca fina para labels, escala tipografica editorial impecable con interlineado generoso. Reglas hairline que se dibujan al entrar. Fotos que revelan con mask vertical y parallax leve. El indice resalta la seccion activa con scrollspy y una linea que se mueve. Cursor custom fino tipo lapiz. Scroll suave con Lenis. Transiciones sobrias por fundido. Entregable: HTML+CSS+JS con GSAP + Lenis por CDN, un index, responsive colapsando el indice a menu superior." },
  { sector: "Web", layout: "hero", nombre: "Nova AI — Landing con chat demo", descripcion: "Hero IA con demo de chat vivo", prompt: "Landing de producto IA 'Nova' en dark mode profundo (fondo #0A0A0F, superficies #12121A). Hero a pantalla completa con un halo de gradiente cónico animado (violeta #7C5CFF → cian #22D3EE → magenta #F471B5) desenfocado detrás del titular. Tipografía: display Geist o Clash Display 72px con tracking -2%, cuerpo Inter 16px. Titular con reveal por palabras usando GSAP SplitText y stagger 0.06s. A la derecha, un widget de chat demo funcional: mensajes que aparecen con typewriter, burbujas glassmorphism (backdrop-blur 20px, borde 1px rgba(255,255,255,0.08)), indicador de 'escribiendo' con tres puntos animados, y un input real que responde con respuestas mockeadas. Partículas sutiles en canvas siguiendo el cursor. Micro-interacciones en el CTA con glow que pulsa. Navbar sticky que se compacta al hacer scroll. Entregable: HTML+CSS+JS autocontenido (GSAP por CDN)." },
  { sector: "Web", layout: "dashboard", nombre: "Pulse Analytics — Dashboard", descripcion: "Analítica con gráficos animados", prompt: "Dashboard de analítica SaaS 'Pulse' con sidebar colapsable de 72px/240px y layout de grid 12 columnas. Paleta clara y limpia: fondo #F7F8FA, cards blancas con sombra suave (0 1px 3px rgba(16,24,40,0.08)), acento índigo #4F46E5 y verde #10B981 para deltas positivos, rojo #EF4444 para negativos. Tipografía Inter, números tabulares para métricas grandes 32px semibold. KPI cards en la parte superior con sparklines dibujados en canvas y contador animado (count-up) al cargar. Gráfico de área principal con gradiente de relleno y línea que se dibuja con stroke-dashoffset al entrar en viewport. Barras y donut con transiciones en hover que muestran tooltips flotantes. Tabla de datos con filas que aparecen en cascada y filtros con chips. Modo claro/oscuro togglable. Entregable: HTML+CSS+JS puro (Chart.js opcional por CDN, o SVG a mano)." },
  { sector: "Web", layout: "split", nombre: "AgentGrid — Panel de agentes IA", descripcion: "Orquestación de agentes en tiempo real", prompt: "Panel de orquestación de agentes IA 'AgentGrid' en split 40/60. Izquierda: lista de agentes como tarjetas con avatar generado, estado (idle/thinking/running) indicado por un anillo de progreso SVG animado y un punto que pulsa con keyframes. Derecha: vista de conversación entre agentes con líneas de conexión SVG animadas (paths que se dibujan) mostrando el flujo de mensajes entre nodos. Estética terminal-futurista: fondo #08090D, verde neón #39FF14 y ámbar #FFB020 para logs, monospace JetBrains Mono para trazas. Log stream con auto-scroll y líneas que entran con fade+slide. Cada agente con un mini grafo de tareas. Efecto de 'scanline' sutil sobre el panel. Estado 'running' con barra de progreso indeterminada tipo shimmer. Entregable: HTML+CSS+JS autocontenido, animaciones con Web Animations API y SVG." },
  { sector: "Web", layout: "hero", nombre: "Forge — Generador de contenido", descripcion: "Hero de generador con preview", prompt: "Landing de generador de contenido IA 'Forge'. Hero split visual: a la izquierda titular potente 'De un prompt a una campaña completa' en Satoshi Bold 64px, a la derecha un mockup de la app generando texto en vivo con efecto typewriter y un cursor parpadeante. Paleta cálida premium: fondo crema #FBF9F4, tinta #1A1614, acento coral #FF5A3C y dorado #E8B04B. Fondo con textura de ruido sutil (SVG feTurbulence) y formas orgánicas blob animadas con morphing lento vía SMIL o GSAP. Tarjetas de plantillas que flotan con parallax al mover el mouse. Sección de 'antes/después' con slider draggable. Botones con relleno que se llena de izquierda a derecha en hover. Scroll-triggered reveals con GSAP ScrollTrigger. Entregable: HTML+CSS+JS (GSAP + ScrollTrigger por CDN)." },
  { sector: "Web", layout: "dashboard", nombre: "Relay CRM — Pipeline moderno", descripcion: "CRM con tablero kanban drag", prompt: "CRM moderno 'Relay' con vista de pipeline kanban de 5 columnas (Lead, Contacto, Propuesta, Negociación, Cerrado). Tarjetas de deal arrastrables (drag & drop nativo con animación de reordenamiento fluida y placeholder ghost). Paleta sobria: fondo #FAFAFA, columnas #F0F1F3, acento azul eléctrico #2563EB, avatares con gradientes por inicial. Header con métricas de valor total del pipeline en count-up y una barra de progreso segmentada. Al soltar una tarjeta en 'Cerrado', dispara confetti en canvas. Panel lateral deslizante (slide-in desde la derecha) al hacer clic en un deal, con timeline de actividad animado. Tipografía Inter, badges de estado con puntos de color. Búsqueda con filtrado en vivo. Entregable: HTML+CSS+JS puro, drag&drop y animaciones con transitions/FLIP." },
  { sector: "Web", layout: "dashboard", nombre: "Ledger — Panel de facturación", descripcion: "Billing con MRR y facturas", prompt: "Panel de facturación SaaS 'Ledger'. Layout dashboard con card de plan actual destacada (gradiente sutil violeta-índigo), medidor de uso circular animado (arco SVG que se llena) y desglose de MRR/ARR con gráfico de barras apiladas. Paleta financiera confiable: fondo #F5F6F8, verde #059669 para pagos exitosos, ámbar #D97706 para pendientes. Tabla de facturas con estados como pills, hover que eleva la fila, y botón de descarga con micro-animación de check al completar. Sección de método de pago con tarjeta de crédito 3D que rota sutilmente en hover (transform-style preserve-3d). Toggle mensual/anual con badge de ahorro que aparece con bounce. Números con formato de moneda y tabular-nums. Entregable: HTML+CSS+JS autocontenido, gráficos en SVG/canvas." },
  { sector: "Web", layout: "split", nombre: "BlockCanvas — Plataforma no-code", descripcion: "Editor visual de nodos drag", prompt: "Plataforma no-code 'BlockCanvas' en split: izquierda paleta de bloques arrastrables, derecha un lienzo infinito con grid de puntos donde se conectan nodos mediante cables bezier SVG animados (los cables se dibujan al conectar y ondulan sutilmente). Zoom y pan del canvas con rueda y drag. Estética producto moderno: fondo #0F1117 oscuro, nodos con glassmorphism y acento verde-lima #A3E635, cables con gradiente animado que fluye (dash animation) indicando dirección del dato. Nodos con puertos que hacen glow al hacer hover para conexión. Minimapa en esquina. Snap a grid al soltar. Barra superior con controles de zoom y un botón 'Run' que hace pulsar todos los nodos en secuencia. Tipografía Inter + monospace para valores. Entregable: HTML+CSS+JS puro con SVG para los cables." },
  { sector: "Web", layout: "hero", nombre: "Synth — Landing IA con orbe 3D", descripcion: "Hero con orbe WebGL reactivo", prompt: "Landing de plataforma IA 'Synth' con un orbe 3D central hecho en Three.js: esfera con shader de distorsión (noise vertex displacement) que reacciona al scroll y al mouse, iridiscente con fresnel violeta-cian sobre fondo negro #050507. Titular centrado 'Inteligencia que se adapta' en tipografía variable (Inter var) con peso animado de 300 a 700 en hover. Bloom postprocessing sutil sobre el orbe. Al hacer scroll, el orbe se encoge y migra a esquina mientras aparecen secciones de features con cards que hacen reveal 3D (rotateX). Cursor personalizado que deforma el orbe cercano. Gradiente de fondo animado muy tenue. Entregable: HTML+CSS+JS con Three.js por CDN, postprocessing incluido." },
  { sector: "Web", layout: "dashboard", nombre: "Sentinel — Observabilidad IA", descripcion: "Monitoreo de modelos en vivo", prompt: "Dashboard de observabilidad de modelos IA 'Sentinel'. Grid de paneles con métricas de latencia, tokens/seg, tasa de error y costo, cada uno con gráfico de línea en tiempo real que hace streaming (nuevos puntos entran por la derecha con animación). Paleta dark ops: fondo #0B0E14, cian #06B6D4, alertas rojas #F43F5E con glow pulsante. Heatmap de uso por hora con celdas que hacen fade-in escalonado. Log de trazas con niveles color-coded y expand/collapse animado. Indicador de salud global tipo semáforo con anillo animado. Tipografía IBM Plex Mono para datos, Inter para labels. Tooltips que siguen el cursor sobre los gráficos. Entregable: HTML+CSS+JS autocontenido, gráficos en canvas con requestAnimationFrame para el efecto tiempo real." },
  { sector: "Web", layout: "hero", nombre: "Quill — Copiloto de escritura", descripcion: "Hero editorial con demo inline", prompt: "Landing de copiloto de escritura IA 'Quill', estética editorial premium. Hero con tipografía serif de lujo (Fraunces 80px) para el titular y párrafo en Inter. Fondo papel #FCFBF7 con márgenes amplios tipo revista. Demo inline: un párrafo donde palabras sugeridas aparecen en gris fantasma y se 'aceptan' con un shimmer dorado al pasar, simulando autocompletado IA. Subrayados ondulados que aparecen y se corrigen solos. Paleta tinta #201A17, acento verde salvia #6B8E7F. Ilustración de pluma con trazo SVG que se dibuja (stroke draw) al cargar. Scroll suave con secciones que entran con máscaras de texto (clip-path reveal). Micro-interacción: el cursor deja un rastro de tinta que se desvanece. Entregable: HTML+CSS+JS puro, animaciones con Web Animations API." },
  { sector: "Web", layout: "split", nombre: "Prism — Comparador de modelos", descripcion: "Split de respuestas lado a lado", prompt: "Interfaz de comparación de modelos IA 'Prism' en split 50/50 con divisor draggable central. Cada lado muestra la respuesta de un modelo distinto generándose en paralelo con streaming typewriter, header con nombre del modelo, velocidad tokens/seg en vivo y costo acumulado. Paleta neutra tech: fondo #101014, panel izquierdo tinte azul #3B82F6, derecho tinte violeta #8B5CF6 para diferenciar. Barra de votación 'cuál prefieres' con botones que hacen ripple. Métricas comparativas abajo en barras que crecen animadas. Sincronización de scroll opcional. Glassmorphism en los headers, código con syntax highlight y bloques con botón copiar (check animado). Tipografía Inter + JetBrains Mono. Entregable: HTML+CSS+JS autocontenido." },
  { sector: "Web", layout: "dashboard", nombre: "Cohort — Analítica de producto", descripcion: "Retención y embudos animados", prompt: "Dashboard de analítica de producto 'Cohort'. Foco en retención: tabla de cohortes con celdas heatmap (verde #10B981 a rojo, interpolado) que hacen reveal diagonal escalonado. Embudo de conversión con etapas que se estrechan, animadas al entrar en viewport con % que hacen count-up. Gráfico de retención en curvas suaves multi-serie con leyenda interactiva (hover atenúa las otras series). Paleta clara profesional: fondo #FFFFFF, superficies #F8FAFC, acento teal #0D9488. Selector de rango de fechas con dropdown animado. Cards de métricas norte-estrella arriba con tendencia mini. Segmentación con chips toggleables. Tipografía Inter, tabular-nums. Skeleton loaders con shimmer antes de cargar datos. Entregable: HTML+CSS+JS puro, viz en SVG/canvas." },
  { sector: "Web", layout: "hero", nombre: "Atlas — Landing infra IA", descripcion: "Hero con grafo de red animado", prompt: "Landing de infraestructura IA 'Atlas'. Hero con un grafo de red 3D de nodos conectados de fondo (canvas): puntos que flotan con conexiones que aparecen/desaparecen según proximidad, rotación lenta global, color cian #38BDF8 sobre fondo azul-noche #0A1628. Titular 'La columna vertebral de tu IA' en Space Grotesk 68px con gradiente de texto animado. CTA doble con el primario en glow y el secundario ghost. Logos de clientes en marquee infinito. Al scroll, secciones con números de escala (99.99% uptime) que hacen count-up con GSAP. Tarjetas de features con borde gradiente animado (conic-gradient girando). Cursor magnético en los botones. Entregable: HTML+CSS+JS con canvas para el grafo y GSAP por CDN." },
  { sector: "Web", layout: "dashboard", nombre: "Threads — Bandeja de agentes", descripcion: "Inbox de tareas IA multi-hilo", prompt: "Dashboard tipo inbox 'Threads' para gestionar tareas de agentes IA. Layout de tres columnas: lista de hilos, conversación central, panel de contexto derecho. Hilos con preview, estado (en curso con dots animados, completado con check verde, bloqueado ámbar) y timestamp relativo. Panel central con burbujas de mensajes de agente/herramienta, llamadas a tools mostradas como cards colapsables con JSON formateado. Paleta calmada: fondo #FBFCFD, acento índigo #6366F1, superficies con borde 1px #E5E7EB. Panel derecho con artefactos generados (archivos, gráficos) en miniaturas. Transición slide al cambiar de hilo, nuevos mensajes entran con fade+slide-up. Tipografía Inter + mono para tools. Modo compacto togglable. Entregable: HTML+CSS+JS autocontenido." },
  { sector: "Web", layout: "split", nombre: "Vector — Búsqueda semántica", descripcion: "Split de query y resultados vivos", prompt: "Interfaz de búsqueda semántica 'Vector' en split: izquierda barra de búsqueda grande con embeddings visualizados como constelación de puntos en canvas que se reorganizan según la query (partículas que migran con easing). Derecha resultados rankeados con score de similitud en barra animada y snippets con términos resaltados. Estética data-science elegante: fondo #0D1017, acento magenta #E11D8F y cian, tipografía Inter + JetBrains Mono. Al escribir, los puntos relevantes hacen glow y se agrupan. Cada resultado con card que se eleva en hover mostrando metadata. Filtros de fuente como toggles. Indicador de latencia de búsqueda. Empty state ilustrado animado. Entregable: HTML+CSS+JS puro con canvas para la constelación." },
  { sector: "Web", layout: "hero", nombre: "Bloom — App IA de imágenes", descripcion: "Hero galería generativa masonry", prompt: "Landing de app de generación de imágenes IA 'Bloom'. Hero con galería masonry de imágenes generadas (placeholders con gradientes vibrantes) que cargan con efecto de revelado tipo cortina y parallax diferencial al scroll. Titular 'Imagina. Genera. Refina.' en Clash Display 76px sobre fondo #08080C. Barra de prompt central flotante con glassmorphism donde texto de ejemplo se autoescribe en loop. Paleta saturada creativa: gradientes rosa #EC4899 → naranja #F97316 → violeta. Al hover sobre una imagen, se expande suavemente mostrando el prompt usado. Botón CTA con gradiente animado y sombra de color. Secciones de estilos como carrusel horizontal con snap. Cursor con blend-mode difference. Entregable: HTML+CSS+JS con GSAP ScrollTrigger por CDN." },
  { sector: "Web", layout: "dashboard", nombre: "Meter — Uso y costos de API", descripcion: "Consumo de tokens y presupuesto", prompt: "Dashboard de uso y costos de API IA 'Meter'. Hero-card con costo del mes en número grande animado y proyección con línea punteada. Gráfico principal de consumo diario de tokens en área apilada por modelo, con toggle de leyenda. Medidor de presupuesto tipo gauge semicircular SVG que cambia de verde a rojo según % consumido, con aguja animada. Paleta clara fintech: fondo #F9FAFB, acento morado #7C3AED, alertas #DC2626. Tabla de endpoints con requests, latencia media y costo, ordenable con animación de reordenamiento. Alertas de límite con banner que se desliza desde arriba. Tarjetas de desglose por modelo con mini-donuts. Tipografía Inter, tabular-nums, formato de moneda. Entregable: HTML+CSS+JS autocontenido, viz en SVG/canvas." },
  { sector: "Web", layout: "split", nombre: "Studio — Constructor de prompts", descripcion: "Editor de prompts con preview", prompt: "Herramienta 'Studio' para diseñar prompts, split editor/preview. Izquierda: editor con variables destacadas como chips {{variable}} que se pueden editar inline, plantillas y controles de temperatura/tokens con sliders custom animados. Derecha: preview de la respuesta generándose con streaming y un diff highlight cuando cambias el prompt. Estética IDE premium dark: fondo #0E1116, acento verde #22C55E, syntax highlight en el prompt. Sliders con thumb que hace glow al arrastrar y valor en tooltip. Historial de versiones como timeline lateral. Botón 'Ejecutar' con estado loading tipo barra shimmer. Panel de tokens usados con barra que se llena. Tipografía JetBrains Mono + Inter. Entregable: HTML+CSS+JS puro." },
  { sector: "Web", layout: "hero", nombre: "Cortex — Landing plataforma RAG", descripcion: "Hero con pipeline animado", prompt: "Landing de plataforma RAG 'Cortex'. Hero con una animación de pipeline horizontal: documentos → chunking → embeddings → vector store → respuesta, cada etapa como nodo que se ilumina en secuencia con partículas de datos viajando por los conectores (canvas). Fondo #0A0C12, acento azul-eléctrico #3B82F6 y verde #34D399. Titular 'Tus datos, con memoria' en Geist 70px, subtítulo con fade-in escalonado. Diagrama interactivo: al hover sobre una etapa se expande con detalle. CTA con borde gradiente rotatorio. Sección de features en cards con iconos animados (SVG stroke draw). Números de rendimiento con count-up al scroll. Navbar con blur al hacer scroll. Entregable: HTML+CSS+JS con canvas para el pipeline y las partículas." },
  { sector: "Web", layout: "dashboard", nombre: "Roster — Gestión de equipo IA", descripcion: "Panel de flota de agentes", prompt: "Dashboard de gestión de flota de agentes IA 'Roster'. Vista de grid de tarjetas de agentes, cada una con avatar, rol, carga de trabajo (barra animada), tareas activas y un mini-gráfico de actividad sparkline. Estado en tiempo real con puntos pulsantes. Paleta moderna: fondo #F4F5F7, acento azul-cobalto #1D4ED8, superficies blancas con sombra suave. Header con métricas agregadas (agentes activos, tareas/hora, éxito %) en cards con count-up. Al clic en un agente, modal con detalle que hace zoom-in desde la card (shared element transition simulada con FLIP). Filtros por rol como segmented control animado. Toggle vista grid/lista. Vista de asignación con drag de tareas a agentes. Tipografía Inter. Entregable: HTML+CSS+JS autocontenido." },
  { sector: "Web", layout: "hero", nombre: "Echo — Landing IA de voz", descripcion: "Hero con waveform reactivo", prompt: "Landing de plataforma de voz IA 'Echo'. Hero centrado con una waveform de audio animada gigante en canvas que ondula orgánicamente (ondas sinusoidales superpuestas con ruido) y reacciona con un pulso al hacer clic en 'Escuchar demo'. Fondo degradado noche #0C1023 a #1A103A, waveform en gradiente cian-violeta con glow. Titular 'Dale voz a tu producto' en Satoshi 72px. Botón play circular con anillo de progreso al reproducir. Chips de idiomas/voces que al seleccionar cambian el color del waveform. Secciones con reveal y un ecualizador de barras decorativo animado. Micro-interacción: hover en el waveform genera ripples. Tipografía Inter. Entregable: HTML+CSS+JS con canvas y Web Audio API opcional para el waveform." },
  { sector: "Web", layout: "dashboard", nombre: "Flow — Automatizaciones no-code", descripcion: "Panel de workflows con ejecuciones", prompt: "Dashboard de automatizaciones no-code 'Flow'. Lista de workflows como cards con un mini-diagrama de nodos en preview, estado (activo/pausado con toggle animado) y últimas ejecuciones como puntos verdes/rojos en fila. Panel de detalle con historial de runs en timeline vertical, cada run expandible mostrando logs por paso con estado animado. Paleta fresca: fondo #F6F8FB, acento púrpura #8B5CF6, éxito #16A34A. Header con stats de ejecuciones/día en gráfico de barras compacto. Botón 'Nueva automatización' con FAB que expande opciones en abanico. Runs en vivo con fila que aparece en top con highlight y luego se asienta. Tipografía Inter + mono para logs. Entregable: HTML+CSS+JS puro." },
  { sector: "Web", layout: "split", nombre: "Subscribe — Onboarding de billing", descripcion: "Split de planes y checkout", prompt: "Flujo de suscripción SaaS en split: izquierda selector de planes con tres tarjetas (una destacada con badge 'Popular' y borde gradiente animado), toggle mensual/anual con transición de precios que hace roll de dígitos. Derecha resumen de pedido y formulario de checkout con campos que validan en vivo (check verde animado). Paleta premium: fondo #FCFCFD, acento negro #111 con acento eléctrico #6D28D9. Al cambiar de plan, el resumen actualiza con animación de números. Barra de progreso de pasos arriba. Trust badges y garantía con iconos SVG animados. Nota: el botón de pago es solo visual (no procesar pagos reales). Micro-interacciones en inputs (label flotante). Tipografía Inter. Entregable: HTML+CSS+JS autocontenido, sin integración de pago real." },
  { sector: "Web", layout: "hero", nombre: "Mind — Landing asistente personal", descripcion: "Hero conversacional inmersivo", prompt: "Landing de asistente IA personal 'Mind'. Hero inmersivo con un gradiente mesh animado de fondo (blobs de color que se mueven lentamente, tipo aurora, en cian #22D3EE, violeta #A855F7, rosa #F472B6 sobre #08060F) hecho con canvas o CSS animado. Titular 'Tu segundo cerebro, siempre despierto' en Fraunces 74px. Una tarjeta de chat flotante central con conversación de ejemplo que se despliega mensaje a mensaje con easing suave y sonido visual (ripple al llegar mensaje). Scroll parallax con capas. Secciones de casos de uso en cards que hacen tilt 3D siguiendo el mouse (vanilla-tilt effect a mano). CTA con shimmer. Cursor glow que ilumina el mesh cercano. Entregable: HTML+CSS+JS con canvas para el mesh gradient." },
  { sector: "Web", layout: "dashboard", nombre: "Insight — Reportes ejecutivos IA", descripcion: "Dashboard de resúmenes generados", prompt: "Dashboard de reportes ejecutivos generados por IA 'Insight'. Layout editorial-dashboard: columna principal con un resumen narrativo generado (texto que aparece con reveal por líneas) intercalado con gráficos embebidos (barras, líneas, KPIs) que se animan al scroll. Sidebar con índice navegable que resalta la sección activa (scroll spy). Paleta sofisticada: fondo #FFFFFF, tinta #0F172A, acento azul-acero #0369A1, superficies #F1F5F9. Cada insight con un badge de confianza y fuente. Botón 'Regenerar' con spinner elegante. Gráficos con tooltips y animación de entrada. Tipografía: titulares en Fraunces, cuerpo Inter, datos tabular-nums. Modo impresión limpio. Entregable: HTML+CSS+JS puro, viz en SVG/canvas." },
  { sector: "Web", layout: "split", nombre: "Canvas AI — Editor colaborativo", descripcion: "Split documento y copiloto lateral", prompt: "Editor de documentos con copiloto IA 'Canvas AI' en split 65/35. Izquierda: documento editable estilo Notion con bloques, cursores de colaboradores fantasma que se mueven, y texto seleccionado que muestra un menú flotante de acciones IA (reescribir, resumir, expandir) con animación de aparición. Derecha: panel de copiloto con chat contextual y sugerencias que se pueden insertar con un clic (el texto vuela hacia el documento con animación de transferencia). Paleta limpia productividad: fondo #FFFFFF, superficie #F7F7F5, acento negro-tinta con highlight amarillo #FCD34D para sugerencias. Barra de herramientas que aparece en hover. Contador de palabras animado. Transiciones suaves, foco en fluidez. Tipografía Inter + serif para el documento. Entregable: HTML+CSS+JS autocontenido con contenteditable." },
  { sector: "App", layout: "mobile", nombre: "Onboarding Aurora", descripcion: "Onboarding con transiciones fluidas", prompt: "App de onboarding móvil en 3 slides con estética premium tipo iOS. Fondo con malla de gradiente animada (aurora boreal) en violeta #6D5EF6, cian #22D3EE y rosa #F472B6 que se desplaza con CSS conic-gradient y keyframes. Tipografía SF Pro / Inter: titulares 34px 700 tracking -0.02em, cuerpo 16px 400 gris #A1A1AA. Ilustraciones SVG con paths que dibujan (stroke-dashoffset) al entrar cada slide. Paginación con dots que se estiran a pill al activarse. Botón CTA glassmorphism con blur(20px), borde 1px rgba(255,255,255,.15) y ripple al tocar. Transición entre slides con GSAP timeline: parallax de capas, fade+translateY(24px) escalonado. Barra de progreso circular arriba. Entregable: HTML+CSS+JS (GSAP por CDN), 390x844, safe-area, dark mode." },
  { sector: "App", layout: "mobile", nombre: "Crypto Wallet Nebula", descripcion: "Wallet cripto con tarjeta 3D", prompt: "Pantalla de wallet cripto móvil, tema oscuro profundo #0A0A0F. Tarjeta de balance con tilt 3D reactivo al giroscopio/mouse (rotateX/rotateY con transform-style preserve-3d), superficie holográfica que refleja gradiente iridiscente. Balance $12,480.55 en tipografía mono SF Mono 40px con conteo animado (count-up easing cubic-bezier). Sparkline SVG del portfolio con área rellena degradada verde #34D399→transparente y línea que se dibuja. Lista de assets (BTC, ETH, SOL) con logos, cambio 24h en píldoras verde/rojo y micro-barras. Bottom sheet de envío con drag handle, snap points y backdrop blur. Botones Send/Receive/Swap con glow neón y haptic-like scale. Entregable: HTML+CSS+JS vanilla, 390x844, 60fps." },
  { sector: "App", layout: "mobile", nombre: "Fitness Rings Pulse", descripcion: "Anillos de progreso de actividad", prompt: "Pantalla de fitness móvil estilo Apple Fitness. Tres anillos concéntricos SVG (Movimiento #FA114F, Ejercicio #92E82A, De pie #1EE5C9) que se rellenan con stroke-dasharray animado y easing spring al cargar, con glow y punta redondeada. Fondo negro puro #000, tarjetas de métricas (pasos, kcal, BPM) en glass con blur. Gráfico de barras semanal con hover que eleva la barra y muestra tooltip. Contador de BPM con latido (scale pulse loop). Header con avatar y saludo dinámico. Micro-interacción: al completar un anillo, burst de partículas (canvas). Tipografía SF Pro Rounded, números 700. Entregable: HTML+CSS+JS (canvas para partículas), 390x844, dark." },
  { sector: "App", layout: "mobile", nombre: "Meditación Zen Gradient", descripcion: "Meditación con gradiente respirante", prompt: "App de meditación móvil, minimalismo cálido. Fondo gradiente que respira lentamente (radial-gradient animado 8s ease-in-out, durazno #FFB88C→lavanda #C8A2FF→azul noche #3A2E6E). Círculo central de respiración que expande/contrae (scale 1→1.4, 4s inhala / 4s exhala) con blur suave y aro de partículas orbitando (canvas). Texto guía 'Inhala… Exhala…' con fade sincronizado. Temporizador circular fino abajo. Lista de sesiones en cards con imagen difuminada y duración. Tipografía serif elegante (Playfair) para títulos + Inter para cuerpo. Sonido ondulante opcional (Web Audio, botón mute). Transiciones ultra suaves cubic-bezier(.4,0,.2,1). Entregable: HTML+CSS+JS (canvas + Web Audio), 390x844." },
  { sector: "App", layout: "mobile", nombre: "Music Visualizer Waves", descripcion: "Reproductor con visualizador de audio", prompt: "Reproductor de música móvil premium tipo Apple Music. Artwork grande con reflejo y sombra dinámica que tiñe el fondo (color extraído, gradiente ambiente animado). Visualizador de audio reactivo: barras de frecuencia + onda circular alrededor del artwork usando Web Audio API (AnalyserNode, requestAnimationFrame). Controles con scrub bar de progreso que se engrosa al arrastrar y thumb magnético. Botón play/pause con morph de icono (SVG path tween). Letras que hacen scroll y resaltan la línea activa. Cola de reproducción en bottom sheet arrastrable. Tipografía SF Pro, título 28px 700. Paleta adaptativa oscura. Entregable: HTML+CSS+JS (Web Audio API + canvas), 390x844, 60fps." },
  { sector: "App", layout: "mobile", nombre: "E-commerce Bottom Sheet", descripcion: "Ficha de producto con bottom sheet", prompt: "Ficha de producto e-commerce móvil, estética editorial premium (sneakers/fashion). Imagen de producto full-bleed con parallax al scroll y color swatches que cambian la imagen con crossfade. Bottom sheet expandible (drag con snap points: peek 40% / full 90%) con detalles, tallas en chips seleccionables (scale+borde al elegir) y reseñas. Botón 'Añadir al carrito' que se transforma en spinner y luego check, con badge del carrito que hace bounce y vuela un thumbnail (fly-to-cart, GSAP). Precio grande 32px, tipografía Neue/Inter. Sombras suaves, esquinas 24px, fondo #FAFAFA / dark #111. Micro-haptics simuladas con scale. Entregable: HTML+CSS+JS (GSAP por CDN), 390x844, light+dark." },
  { sector: "App", layout: "mobile", nombre: "Delivery Live Map", descripcion: "Seguimiento de pedido en mapa", prompt: "Pantalla de seguimiento de delivery móvil. Mapa oscuro estilizado (tiles custom o SVG vectorial) con ruta que se dibuja (stroke-dashoffset) del restaurante al usuario, marcador del repartidor que se mueve suavemente a lo largo del path (getPointAtLength, requestAnimationFrame) con pulso de ubicación. Bottom sheet con foto del rider, ETA con conteo regresivo, barra de estado (Preparando → En camino → Cerca) con pasos que se iluminan y check animado. Botones llamar/chat en glass. Tarjeta de resumen del pedido colapsable. Colores: mapa #12151C, acento naranja #FF6B35, verde éxito. Tipografía Inter. Entregable: HTML+CSS+JS (SVG path + canvas opcional), 390x844." },
  { sector: "App", layout: "mobile", nombre: "Neo Banking Dashboard", descripcion: "Banca móvil con tarjeta y gastos", prompt: "Dashboard de banca móvil neobank (estilo Revolut/N26) premium. Tarjeta de débito metálica con gradiente frío #1B1F3B→#3D5AFE, chip y número en mono, brillo que se desliza al inclinar (parallax). Balance con toggle ocultar/mostrar (blur→reveal). Fila de acciones rápidas (Enviar, Cobrar, Recargar, Dividir) con iconos y ripple. Gráfico de gastos donut por categoría (SVG, segmentos que crecen escalonados) + lista de transacciones con logos de comercios, agrupadas por día, swipe para categorizar. Header con avatar y notificación con dot pulsante. Tipografía Inter/SF Pro, números tabulares. Light+dark. Entregable: HTML+CSS+JS, 390x844." },
  { sector: "App", layout: "list", nombre: "Transacciones Timeline", descripcion: "Lista de movimientos bancarios", prompt: "Vista de lista de transacciones bancarias móvil, densidad premium. Items agrupados por fecha con headers sticky translúcidos (backdrop-blur). Cada fila: logo del comercio en avatar redondeado, nombre, categoría en subtítulo, monto a la derecha (verde entradas / neutro salidas) con números tabulares. Entrada escalonada al cargar (stagger fade+translateY, IntersectionObserver). Swipe izquierda revela acciones (categorizar, ocultar) con spring. Barra de búsqueda que se contrae al scroll y filtros en chips horizontales scrollables con estado activo. Pull-to-refresh con spinner custom. Skeleton shimmer en carga. Fondo #0B0B0F, acentos suaves. Tipografía Inter. Entregable: HTML+CSS+JS, 390x844, dark." },
  { sector: "App", layout: "chat", nombre: "AI Assistant Glass", descripcion: "Chat con asistente IA premium", prompt: "Interfaz de chat con asistente de IA móvil, estética premium glassmorphism. Burbujas del usuario con gradiente violeta→índigo alineadas derecha, burbujas de la IA en glass claro izquierda. Indicador 'escribiendo' con tres puntos que rebotan (keyframes stagger). Respuestas que aparecen con efecto typewriter carácter a carácter. Barra de entrada flotante con blur, botón de micrófono con waveform reactiva al mantener presionado, botón enviar que hace morph a spinner. Chips de sugerencias sobre el input con scroll horizontal. Scroll suave con auto-anclaje al final. Header con avatar animado de la IA (aura pulsante). Fondo gradiente oscuro sutil. Tipografía Inter 16px. Entregable: HTML+CSS+JS, 390x844." },
  { sector: "App", layout: "mobile", nombre: "Habit Tracker Bloom", descripcion: "Hábitos con jardín que florece", prompt: "App de hábitos móvil con metáfora de jardín. Cada hábito es una planta SVG que crece/florece al completarse (morph de path + escala con spring). Grid de días tipo GitHub-contributions con celdas que se tiñen y hacen pop al marcar. Racha (streak) con llama animada que crece con los días. Al completar todos los del día, lluvia de pétalos (canvas). Progreso circular por hábito con checkmark dibujado. Paleta natural: verde salvia #7FB77E, crema #FFF7E6, terracota. Cards suaves radius 20px, sombras cálidas. Tipografía Nunito/Inter redondeada. Haptics simuladas. Micro-confetti al 100%. Entregable: HTML+CSS+JS (canvas), 390x844, light." },
  { sector: "App", layout: "mobile", nombre: "Weather Atmosphere", descripcion: "Clima con cielo dinámico animado", prompt: "App del clima móvil cinematográfica. Fondo que cambia según condición y hora (gradiente cielo animado, canvas): sol con rayos, nubes que derivan, lluvia con gotas y ripples, estrellas de noche parpadeando. Temperatura gigante 96px thin, condición y máx/mín. Tarjeta horaria scroll horizontal con iconos animados. Gráfico de temperatura curva suave (SVG path smoothing) con punto que sigue. Detalles (viento, humedad, UV) en grid glass con micro-gauges. Transición de escena al cambiar ciudad con crossfade de todo el cielo. Tipografía SF Pro thin/regular. Blur atmosférico en capas. Entregable: HTML+CSS+JS (canvas), 390x844." },
  { sector: "App", layout: "list", nombre: "Inbox Priority Fluid", descripcion: "Bandeja de correo con swipe", prompt: "Bandeja de entrada de email móvil premium tipo Superhuman. Lista de correos con remitente, avatar/monograma con color por dominio, asunto 600, preview 400 gris, hora. No leídos con punto de acento y peso. Swipe derecha archiva (verde con icono que escala), swipe izquierda pospone (ámbar) con resistencia elástica y snap. Selección múltiple con checkboxes que aparecen deslizando. Header con búsqueda y segmented control (Importante/Otros) con indicador que se desliza. Entrada escalonada, skeleton shimmer. FAB de redactar con morph a pantalla completa (shared element). Tipografía Inter. Fondo #FFFFFF / dark #0E0E10. Entregable: HTML+CSS+JS, 390x844." },
  { sector: "App", layout: "chat", nombre: "Messenger Bubbles Live", descripcion: "Mensajería con reacciones animadas", prompt: "App de mensajería móvil premium estilo iMessage/Telegram. Burbujas con cola, colas agrupadas por remitente, gradiente en las propias (azul #0A84FF→#5E5CE6). Reacciones emoji con long-press que abre un popover con spring y las emojis rebotan al elegir; la reacción se acopla a la burbuja. Doble-tap para like con corazón que estalla. Indicador de leído/entregado con check que se dibuja. 'Escribiendo' con puntos animados. Envío de mensaje: la burbuja sale del input y viaja al hilo (GSAP). Adjuntos en grid, audio con waveform. Barra de entrada con blur y botones que rotan. Tipografía SF Pro. Entregable: HTML+CSS+JS (GSAP por CDN), 390x844, light+dark." },
  { sector: "App", layout: "mobile", nombre: "Travel Boarding Pass", descripcion: "Pase de abordar con animaciones", prompt: "App de viajes móvil, pantalla de boarding pass premium. Tarjeta de pase con perforado (notch), código de barras/QR animado (líneas que se dibujan), ruta origen→destino con avión que se traslada a lo largo de un arco SVG punteado (getPointAtLength) y estela. Countdown a embarque, gate y asiento en mono tabular. Al deslizar hacia arriba, el pase gira (flip 3D) mostrando detalles del vuelo. Fondo gradiente cielo atardecer #FF8C69→#6B5B95. Timeline de estado (Check-in→Boarding→Departed) con pasos iluminados. Tipografía SF Pro / mono para datos. Micro-parallax de nubes. Entregable: HTML+CSS+JS (SVG), 390x844." },
  { sector: "App", layout: "mobile", nombre: "Focus Timer Liquid", descripcion: "Pomodoro con líquido animado", prompt: "App de enfoque/Pomodoro móvil. Reloj central como recipiente que se vacía de líquido animado (onda SVG con dos ondas desfasadas que bajan según el tiempo restante, gradiente turquesa #06B6D4→azul #3B82F6). Números 64px thin en el centro. Play/pause/reset con morph de iconos. Al terminar, splash de gotas (canvas) y card de sesión completada con contador de ciclos (tomates que se llenan). Selector de duración con dial circular arrastrable (arco + thumb). Modo descanso cambia paleta a verdes cálidos con crossfade. Ambient blur de fondo reactivo. Tipografía Inter. Entregable: HTML+CSS+JS (SVG waves + canvas), 390x844, dark." },
  { sector: "App", layout: "list", nombre: "Recipe Feed Editorial", descripcion: "Feed de recetas con scroll rico", prompt: "Feed de recetas móvil, revista gastronómica premium. Tarjetas grandes con foto full-bleed, overlay gradiente, título serif 24px (Fraunces), tiempo y dificultad en píldoras glass. Parallax de la imagen dentro de la card al scroll. Botón guardar (bookmark) con morph y bounce, contador de likes con corazón burst. Chips de categoría horizontales sticky con indicador deslizante. Al tocar una card, expansión shared-element a detalle (hero image que crece). Skeleton shimmer y stagger de entrada (IntersectionObserver). Paleta cálida crema #FFF8F0, acento tomate #E63946, tinta #2B2B2B. Entregable: HTML+CSS+JS, 390x844, light." },
  { sector: "App", layout: "chat", nombre: "Support Chat Concierge", descripcion: "Chat de soporte con tarjetas ricas", prompt: "Chat de soporte al cliente móvil premium tipo Intercom. Burbujas de agente con avatar y nombre, burbujas del usuario en acento marca. Mensajes ricos: tarjetas de producto con imagen y CTA, carruseles de opciones en botones que se seleccionan con check, quick-replies en chips. Barra de progreso de resolución arriba. Indicador de escritura con avatar pulsante. Adjuntar imagen con preview y barra de subida animada. Banner de 'Agente conectado' que baja con spring. Transiciones suaves, timestamps que aparecen al scroll. Paleta limpia blanco/azul índigo #4F46E5, radios 18px. Tipografía Inter. Entregable: HTML+CSS+JS, 390x844, light+dark." },
  { sector: "App", layout: "mobile", nombre: "Investing Stocks Pulse", descripcion: "Trading con gráfico interactivo", prompt: "App de inversión/acciones móvil premium tipo Robinhood. Gráfico de línea grande interactivo: al arrastrar el dedo, un crosshair sigue el precio con tooltip y el header actualiza valor/porcentaje en vivo; línea verde/roja según tendencia con área degradada y punto que late. Selector de rango (1D 1S 1M 1A Todo) en segmented con transición morph de la curva (path tween). Watchlist en lista con mini-sparklines. Bottom sheet de compra con teclado numérico custom y botón que se llena al mantener presionado (hold-to-confirm). Fondo negro #000, verde #00C805. Tipografía tabular. Entregable: HTML+CSS+JS (canvas o SVG), 390x844, dark." },
  { sector: "App", layout: "mobile", nombre: "Sleep Cycle Cosmos", descripcion: "Sueño con cielo nocturno de datos", prompt: "App de sueño móvil onírica. Fondo cielo nocturno con estrellas parpadeantes y luna con fases (canvas). Anillo de sueño que muestra horas dormidas y calidad, con arco degradado índigo #4338CA→violeta. Gráfico de fases (Profundo/Ligero/REM/Despierto) como bandas de área apiladas suaves a lo largo de la noche (SVG), con scrub. Alarma inteligente con dial de hora arrastrable y curva de despertar. Puntaje de sueño con conteo animado y emoji de estado. Micro-partículas de estrellas fugaces esporádicas. Tipografía SF Pro thin. Todo en dark profundo #060818, glow suave. Entregable: HTML+CSS+JS (canvas + SVG), 390x844." },
  { sector: "App", layout: "list", nombre: "Music Library Vinyl", descripcion: "Biblioteca musical con disco girando", prompt: "Biblioteca de música móvil premium. Now-playing mini-bar inferior con disco de vinilo que rota (animation infinite, pausa al pausar) y barra de progreso fina. Lista de canciones con número, título, artista, duración; la que suena resalta con ecualizador de 3 barras animadas. Header con portada del álbum grande que se colapsa a sticky al scroll (collapsing header, parallax). Swipe en fila para añadir a cola (chip vuela al mini-bar). Búsqueda con expand desde icono. Paleta oscura con acento extraído del arte, radios 16px. Tipografía SF Pro. Skeleton shimmer y stagger. Entregable: HTML+CSS+JS, 390x844, dark." },
  { sector: "App", layout: "mobile", nombre: "Loyalty Rewards Arcade", descripcion: "Recompensas con tarjeta y ruleta", prompt: "App de fidelización/recompensas móvil, estética lúdica premium. Tarjeta de miembro con nivel (Bronce/Oro/Platino) y brillo holográfico que se mueve. Barra de progreso de puntos hacia el próximo nivel con relleno animado y hito que estalla en confetti (canvas) al alcanzarlo. Ruleta de premios girable con arrastre e inercia (rotate con desaceleración física) y puntero que vibra al pasar segmentos. Cupones en cards con borde perforado y sello 'Canjear' que hace stamp. Contador de puntos con count-up. Paleta dorada #F5C518 + morado #6D28D9, oscuro. Tipografía Poppins. Entregable: HTML+CSS+JS (canvas), 390x844." },
  { sector: "App", layout: "chat", nombre: "Language Tutor Chat", descripcion: "Chat para aprender idiomas", prompt: "App de aprendizaje de idiomas móvil, chat con tutor IA premium tipo Duolingo max. Burbujas del tutor con audio (botón play + waveform que se anima al reproducir) y traducción que se revela con tap (blur→reveal). Mensajes del usuario con corrección inline: palabras erróneas tachadas y sugerencia en verde con animación. Ejercicios embebidos: opción múltiple con botones que se ponen verde/rojo con shake al fallar y check al acertar. Barra de racha con llama y XP que sube con count-up y ding visual. Mascota animada que reacciona (idle, celebra). Paleta verde #58CC02, blanco, radios 16px. Tipografía Nunito/Inter. Entregable: HTML+CSS+JS, 390x844." },
  { sector: "App", layout: "mobile", nombre: "Smart Home Ambient", descripcion: "Control de hogar con escenas", prompt: "App de smart home móvil premium tipo Apple Home. Grid de dispositivos en cards glass con iconos animados (luz que enciende con glow gradual, termostato con dial arrastrable que colorea de azul a naranja según temperatura). Escena activa cambia el fondo ambiente (gradiente animado según 'Mañana/Noche/Cine'). Slider de brillo con relleno luminoso y arrastre suave. Toggle de dispositivos con transición fluida y micro-bounce. Cámara con feed placeholder y borde live pulsante. Barra de habitaciones scrollable con indicador. Fondo oscuro adaptativo, blur en capas. Tipografía SF Pro. Haptics simuladas. Entregable: HTML+CSS+JS, 390x844, dark." },
  { sector: "Componentes", layout: "cards3", nombre: "Pricing con toggle mensual/anual", descripcion: "Tres planes con switch de facturacion animado", prompt: "Diseña una seccion de pricing premium en HTML+CSS+JS (vanilla) con tres tarjetas (Starter, Pro destacada, Enterprise) sobre fondo #0B0F1A con gradiente radial sutil azul-violeta (#6366F1 a #A855F7). Tipografia Inter para texto y Clash Display para los precios. Un toggle central mensual/anual con pill deslizante (transicion cubic-bezier(0.34,1.56,0.64,1) de 0.4s); al cambiar a anual los digitos del precio hacen un roll-up animado (contador que interpola el numero y un pequeno blur vertical) y aparece un badge 'Ahorra 20%' con scale+fade. La tarjeta Pro flota 8px mas arriba, tiene borde gradiente animado (conic-gradient girando con @property --angle) y glow suave. Hover en cada tarjeta: elevacion, sombra difusa y las features hacen stagger de opacidad. Boton CTA con relleno que barre de izquierda a derecha. Entrega un unico archivo HTML+CSS+JS autocontenido, responsive y con prefers-reduced-motion respetado." },
  { sector: "Componentes", layout: "split", nombre: "Testimonios carrusel infinito", descripcion: "Marquee doble fila con pausa al hover", prompt: "Crea un carrusel de testimonios de scroll infinito en HTML+CSS+JS puro, dos filas moviendose en direcciones opuestas (marquee con translateX en requestAnimationFrame, loop perfecto duplicando nodos). Fondo #FAFAF7 crema, tarjetas glassmorphism con blur, avatar circular, nombre, cargo, estrellas y quote. Tipografia General Sans. Al hacer hover sobre cualquier tarjeta toda su fila desacelera suavemente (lerp de la velocidad) y esa tarjeta se eleva con scale 1.04 y sombra; las demas bajan opacidad a 0.5. Mascara de degradado (mask-image linear-gradient) que desvanece los bordes izquierdo y derecho. Cada tarjeta tiene un acento de color distinto en la comilla inicial gigante. Entrega un archivo HTML+CSS+JS autocontenido, responsive, con velocidad configurable por CSS variable y prefers-reduced-motion." },
  { sector: "Componentes", layout: "grid", nombre: "FAQ acordeon animado", descripcion: "Preguntas con expansion suave y linea guia", prompt: "Disena un acordeon de FAQ elegante en HTML+CSS+JS vanilla sobre fondo #111318 con items separados por hairline #262A35. Tipografia Satoshi. Cada pregunta a la izquierda con un icono + que rota a x al abrir (transition 0.35s ease); la respuesta se expande animando grid-template-rows de 0fr a 1fr (tecnica moderna sin medir alturas) con fade y ligero translateY del texto. Solo un item abierto a la vez con cierre animado del anterior. Una barra vertical de acento (#22D3EE) crece de arriba a abajo (scaleY) en el item activo. Numero de indice monospace a la izquierda que cambia de color al abrir. Micro-hover: el titulo se desplaza 4px a la derecha. Entrega HTML+CSS+JS en un solo archivo, accesible (aria-expanded, teclado), responsive y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "split", nombre: "Hero con typing effect", descripcion: "Titular que se escribe con cursor y rotacion de palabras", prompt: "Crea un hero de landing en HTML+CSS+JS puro con efecto typing por JS (sin librerias): un titular fijo 'Construimos ' seguido de palabras rotativas ('productos.', 'marcas.', 'futuros.') que se escriben letra a letra, borran y cambian, con cursor bloque parpadeante (animation blink 1s step-end). Fondo #05060A con un gradiente mesh animado suave (multiple radial-gradients desplazandose con keyframes) y grano sutil via SVG feTurbulence. Tipografia display Space Grotesk 72px, con la palabra rotativa en gradiente de texto (background-clip:text). Subtitulo con fade-in stagger palabra por palabra al cargar. Dos botones: primario con glow y secundario ghost con borde animado. Un blob luminoso sigue el cursor con lerp. Entrega un archivo HTML+CSS+JS autocontenido, responsive, con prefers-reduced-motion que muestra texto estatico." },
  { sector: "Componentes", layout: "cards3", nombre: "Tarjeta 3D con tilt al hover", descripcion: "Tres cartas con parallax y brillo que sigue el cursor", prompt: "Disena tres tarjetas premium con efecto tilt 3D en HTML+CSS+JS vanilla. Al mover el mouse sobre una tarjeta, rota en perspectiva (rotateX/rotateY calculado desde la posicion normalizada del cursor, perspective 1000px, transition suave al salir) y una capa de brillo especular (radial-gradient blanco semitransparente) sigue el puntero. Contenido con parallax por capas (transform: translateZ) para que el titulo, un icono y un badge floten a distintas profundidades. Fondo escena #0A0A0F, tarjetas con gradiente oscuro y borde highlight superior. Sombra dinamica que se inclina en sentido contrario al tilt. Tipografia Inter. Micro-detalle: un patron de holograma (conic-gradient) que cambia de tono con el angulo. Entrega HTML+CSS+JS en un solo archivo, responsive (desactiva tilt en touch) y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "grid", nombre: "Navbar con blur al scroll", descripcion: "Barra que condensa y difumina segun el scroll", prompt: "Crea una navbar sticky avanzada en HTML+CSS+JS puro que reacciona al scroll: al superar 40px pasa de transparente y alta a compacta con backdrop-filter blur(16px), fondo rgba oscuro y hairline inferior; el logo reduce escala y el padding se contrae (transiciones 0.3s ease). Un indicador de progreso de lectura (barra de gradiente #F472B6 a #818CF8) se llena en el borde inferior segun scroll. Links con underline animado que crece desde el centro al hover y un pill de fondo que se desliza al link activo (FLIP/animacion de la posicion). Menu mobile hamburguesa que morfa a X y despliega overlay full-screen con stagger de links. Fondo de pagina de ejemplo con secciones para probar scroll. Entrega HTML+CSS+JS autocontenido, responsive, accesible y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "grid", nombre: "Modal con backdrop", descripcion: "Dialogo con entrada elastica y desenfoque de fondo", prompt: "Disena un sistema de modal accesible en HTML+CSS+JS vanilla usando el elemento dialog nativo. Al abrir, el backdrop hace fade con backdrop-filter blur creciente y el modal entra con scale de 0.9 a 1 mas translateY y un leve overshoot (cubic-bezier elastico); al cerrar, animacion inversa antes de close (transitionend). Card sobre fondo #16181D con borde highlight, header con titulo y boton cerrar que rota al hover, cuerpo con contenido y footer con acciones. Focus trap por JS, cierre con Escape y click fuera, restauracion del foco al disparador. El boton que abre el modal tiene ripple. Contenido de ejemplo tipo confirmacion. Tipografia Inter. Entrega un archivo HTML+CSS+JS autocontenido, responsive, con roles aria correctos y prefers-reduced-motion." },
  { sector: "Componentes", layout: "grid", nombre: "Skeleton loaders", descripcion: "Placeholders con shimmer y transicion a contenido", prompt: "Crea un set de skeleton loaders en HTML+CSS+JS puro: tarjeta de perfil, lista de articulos y grid de imagenes, todos con placeholders de bloques redondeados. Efecto shimmer con un gradiente que barre (linear-gradient 100deg, background-position animado por keyframes, sin JS para el brillo). Fondo #0E1015, bloques #1B1E27 y highlight #2A2E3A. Un boton 'Cargar' que tras 2s (setTimeout simulando fetch) reemplaza cada skeleton por el contenido real con cross-fade y un pequeno translateY, en stagger por item. El shimmer respeta prefers-reduced-motion mostrando pulse de opacidad suave en su lugar. Radios y espaciados calcados a contenido final para evitar layout shift. Tipografia Inter. Entrega un unico archivo HTML+CSS+JS autocontenido y responsive." },
  { sector: "Componentes", layout: "grid", nombre: "Toast notifications", descripcion: "Sistema de avisos apilados con progreso y swipe", prompt: "Disena un sistema de toast notifications en HTML+CSS+JS vanilla con cuatro variantes (success, error, warning, info), cada una con icono, color de acento y barra de progreso que se agota (animation width) antes del auto-dismiss. Se apilan en la esquina inferior derecha; al entrar deslizan desde la derecha con overshoot y al salir hacen fade+slide; el reordenamiento del stack usa animacion de posicion suave (FLIP). Hover pausa el temporizador (animation-play-state) y en touch se pueden descartar con swipe (pointer events + translateX y umbral). Boton cerrar por toast. Fondo demo #0B0C10 con botones para lanzar cada tipo. Tipografia Inter, esquinas 12px, sombra difusa y borde highlight. Entrega HTML+CSS+JS en un solo archivo, accesible (role=status/alert, aria-live), responsive y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "form", nombre: "Stepper multipaso", descripcion: "Formulario por pasos con barra de avance animada", prompt: "Crea un stepper de formulario multipaso en HTML+CSS+JS puro con cuatro pasos (Cuenta, Perfil, Plan, Confirmar). Header con circulos numerados conectados por una linea; la linea de progreso se rellena (scaleX del segmento activo) y el circulo completado morfa el numero a un check dibujado con stroke-dashoffset animado. Al avanzar, el panel actual sale con slide+fade a la izquierda y el nuevo entra desde la derecha (direccion invertida al retroceder). Validacion inline por paso: inputs con label flotante, borde que pasa a rojo con shake sutil si falla. Boton siguiente deshabilitado hasta validar, con spinner al 'enviar' del ultimo paso. Fondo #101217, acento #34D399. Tipografia Inter. Entrega un archivo HTML+CSS+JS autocontenido, accesible por teclado, responsive y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "grid", nombre: "Command palette", descripcion: "Buscador estilo Cmd+K con filtrado difuso", prompt: "Disena un command palette tipo Cmd+K en HTML+CSS+JS vanilla. Atajo Ctrl/Cmd+K abre un overlay con backdrop blur y un panel centrado que entra con scale+fade; input de busqueda con placeholder animado. Filtrado fuzzy en JS de una lista de comandos agrupados (Navegacion, Acciones, Ajustes) con resaltado de los caracteres coincidentes (mark). Navegacion por flechas con el item activo resaltado por un pill que se desliza (transform) y scroll-into-view. Iconos por comando, atajos a la derecha en teclas monospace. Recientes al abrir vacio. Cierra con Escape o click fuera. Fondo #0C0D12, panel #15171E con borde highlight. Tipografia Inter + JetBrains Mono para las teclas. Entrega un unico archivo HTML+CSS+JS, accesible (aria-activedescendant), responsive y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "split", nombre: "Toggle de tema dia/noche", descripcion: "Switch sol-luna con transicion de escena", prompt: "Crea un toggle de tema claro/oscuro premium en HTML+CSS+JS puro. El switch es una capsula donde un sol morfa a luna: el circulo se desliza y aparecen crateres (mascara con box-shadow interior) mientras el fondo del switch pasa de celeste con nubes a indigo con estrellas que titilan (opacidad en keyframes). Al alternar, toda la pagina de demo transiciona colores via CSS variables con View Transitions API si esta disponible (circular reveal desde el boton) y fallback a transicion de background 0.5s. Persiste la eleccion en localStorage y respeta prefers-color-scheme al cargar. Escena demo con una tarjeta y texto que cambian de paleta. Tipografia Inter. Entrega un archivo HTML+CSS+JS autocontenido, accesible (role=switch, aria-checked), responsive y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "cards3", nombre: "Bento grid interactivo", descripcion: "Mosaico asimetrico con celdas que reaccionan", prompt: "Disena un bento grid moderno en HTML+CSS+JS vanilla con celdas de distinto tamano (grid-template-areas) sobre fondo #08090D. Cada celda tiene contenido propio: una con contador animado, otra con un mini sparkline SVG que se dibuja (stroke-dashoffset), otra con un mapa de puntos, otra con un gradiente animado. Al hover de una celda, esta se ilumina con un spotlight radial que sigue el cursor (variables --x --y actualizadas por JS) y un borde highlight aparece; las vecinas bajan levemente la opacidad. Entrada inicial con stagger (IntersectionObserver, translateY+fade). Bordes 16px, hairline #1E212B. Tipografia Clash Display para numeros e Inter para texto. Entrega un unico archivo HTML+CSS+JS autocontenido, responsive (colapsa a columna) y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "form", nombre: "Inputs con label flotante", descripcion: "Campos con animacion de etiqueta y validacion viva", prompt: "Crea un formulario de contacto con floating labels en HTML+CSS+JS puro. Cada campo: el label vive dentro y sube a mini-tamano al enfocar o tener valor (transition de translateY, scale y color, usando :placeholder-shown y :focus). Underline que crece desde el centro (scaleX) al enfocar con color de acento #60A5FA. Validacion en vivo por JS: check verde que se dibuja (stroke-dashoffset) cuando el campo es valido y mensaje de error que baja con fade si no. Un textarea que autoexpande su alto. Boton enviar con estados: idle, loading (spinner), success (morfea a check). Fondo #0F1116, card con borde highlight. Tipografia Inter. Entrega HTML+CSS+JS en un solo archivo, accesible (labels asociados, aria-invalid), responsive y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "split", nombre: "Comparador before/after", descripcion: "Slider de imagenes con divisor arrastrable", prompt: "Disena un comparador de imagenes before/after en HTML+CSS+JS vanilla. Dos imagenes superpuestas; la superior se recorta con clip-path segun la posicion de un divisor vertical arrastrable (pointer events, funciona con mouse y touch). El handle central es un circulo con dos flechas y glow al arrastrar, la linea divisoria fina y luminosa. Etiquetas 'Antes' y 'Despues' que se desvanecen segun se acerca el divisor. Al cargar, animacion de introduccion donde el divisor barre de un lado a otro una vez para invitar a interactuar. Soporta arrastre por teclado (flechas) con el handle enfocado. Fondo #0A0B0F con marco redondeado y sombra. Tipografia Inter. Usa imagenes placeholder por gradiente/SVG. Entrega un archivo HTML+CSS+JS autocontenido, responsive y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "grid", nombre: "Dropdown menu animado", descripcion: "Menu con submenus y transicion de altura fluida", prompt: "Crea un dropdown menu avanzado en HTML+CSS+JS puro. Boton trigger que al abrir despliega un panel con los items en stagger (cada uno translateY+fade con delay incremental) y una flechita que rota. Los items con submenu expanden inline animando grid-template-rows 0fr a 1fr, con un chevron que gira. Un fondo highlight (pill) sigue al item bajo el cursor deslizandose suavemente entre opciones (transform, no cambio de posicion instantaneo). Iconos a la izquierda, atajos a la derecha. Cierra al click fuera o Escape, con animacion de salida. Fondo demo #0D0E13, panel #191B22 con borde highlight y sombra difusa. Navegacion por teclado completa. Tipografia Inter. Entrega un unico archivo HTML+CSS+JS, accesible (role=menu, aria-expanded), responsive y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "grid", nombre: "Tabs con indicador deslizante", descripcion: "Pestanas con subrayado animado y paneles cross-fade", prompt: "Disena un componente de tabs premium en HTML+CSS+JS vanilla. Una fila de pestanas con un indicador (barra o pill) que se desliza y ajusta su ancho a la pestana activa midiendo su posicion por JS (transform translateX + scaleX, transition cubic-bezier). Al cambiar de pestana, el panel saliente hace fade+slide segun la direccion del cambio y el entrante aparece; la altura del contenedor se anima al nuevo alto. Hover en pestanas inactivas sube su opacidad. Variante scrollable en mobile con fade en los bordes. Fondo #101319, acento #F59E0B, hairline inferior. Tipografia Inter. Contenido de ejemplo distinto por tab. Entrega HTML+CSS+JS en un solo archivo, accesible (role=tablist, aria-selected, flechas del teclado), responsive y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "cards3", nombre: "Contadores y barras de estadisticas", descripcion: "KPIs que cuentan y barras que se llenan al ver", prompt: "Crea una seccion de estadisticas animada en HTML+CSS+JS puro con tres tarjetas KPI. Cuando entran en viewport (IntersectionObserver), los numeros cuentan desde 0 al valor con easing (interpolacion en requestAnimationFrame, formato con separador de miles y sufijos como k/%/+) y una barra o anillo de progreso (SVG circle con stroke-dashoffset) se llena en sincronia. Cada tarjeta con icono, etiqueta y una micro-tendencia (flecha up/down). Fondo #0B0D12, tarjetas con gradiente sutil y borde highlight, acento por tarjeta. Hover: leve elevacion y glow. Tipografia Clash Display para las cifras, Inter para el resto. La animacion corre una sola vez. Respeta prefers-reduced-motion mostrando el valor final directo. Entrega un unico archivo HTML+CSS+JS autocontenido y responsive." },
  { sector: "Componentes", layout: "split", nombre: "Boton magnetico con ripple", descripcion: "CTA que atrae el cursor y emite onda al click", prompt: "Disena una coleccion de botones microinteractivos en HTML+CSS+JS vanilla. El principal es magnetico: dentro de un area de proximidad, el boton y su label se desplazan hacia el cursor con lerp y vuelven al centro con elasticidad al salir. Al click, un ripple circular se expande desde el punto exacto (span dinamico con scale+fade). Otros botones: uno con relleno que barre en diagonal al hover, uno con borde gradiente animado (@property --angle), uno ghost con flecha que se desliza y aparece, y uno con estado loading que morfea a spinner y luego a check. Fondo #07080C, acento #A78BFA. Tipografia General Sans. Entrega un archivo HTML+CSS+JS autocontenido, accesible (foco visible), responsive (magnetismo off en touch) y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "grid", nombre: "Tooltip y popover inteligente", descripcion: "Etiquetas flotantes con posicionamiento y flecha", prompt: "Crea un sistema de tooltips y popovers en HTML+CSS+JS puro. Los tooltips aparecen al hover/focus con fade+scale desde el origen y una flechita apuntando al trigger; el JS calcula el mejor lado (top/bottom/left/right) segun el espacio disponible en viewport para que nunca se corten (flip). Delay de aparicion y cierre suave. Un popover mas rico (con titulo, texto y boton) que abre al click, se mantiene, cierra al click fuera o Escape y atrapa el foco. Variantes de color. Fondo demo #0E1015 con varios triggers en distintas posiciones para probar el flip. Bordes 8px, sombra difusa, hairline. Tipografia Inter. Entrega un unico archivo HTML+CSS+JS, accesible (aria-describedby, role=tooltip), responsive y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "cards3", nombre: "Cartas flip con reverso", descripcion: "Tarjetas que giran 3D revelando su dorso", prompt: "Disena tres flip cards en HTML+CSS+JS vanilla que giran en 3D (transform-style preserve-3d, rotateY 180deg, backface-visibility hidden) al hover en desktop y al tap en touch. La cara frontal con imagen/gradiente, icono y titulo; el reverso con descripcion y un CTA. La transicion usa cubic-bezier con leve overshoot y una sombra que se intensifica a mitad del giro para dar peso. Perspective en el contenedor y un brillo especular que barre durante la rotacion. Entrada inicial en stagger al scroll. Fondo escena #0A0A10, cartas con borde highlight y esquinas 16px. Tipografia Clash Display para titulos, Inter para cuerpo. Estado accesible: el flip tambien se dispara con foco por teclado. Entrega un archivo HTML+CSS+JS autocontenido, responsive y con prefers-reduced-motion (crossfade en vez de giro)." },
  { sector: "Componentes", layout: "grid", nombre: "Timeline vertical animada", descripcion: "Linea de hitos que se dibuja al hacer scroll", prompt: "Crea una timeline vertical en HTML+CSS+JS puro donde una linea central se dibuja segun el progreso de scroll (altura o stroke de un SVG ligado a la posicion, actualizado en scroll con rAF). Cada hito, en lados alternados, entra al viewport con translateX+fade (IntersectionObserver) y su punto en la linea hace pop con un pulso (ripple de box-shadow). Tarjeta de hito con fecha, titulo y texto, conectada a la linea por un pequeno brazo. El punto activo (mas cercano al centro del viewport) se agranda y cambia de color. Fondo #0C0E13, linea con gradiente #22D3EE a #818CF8. Tipografia Inter, fechas en monospace. Entrega un unico archivo HTML+CSS+JS autocontenido, responsive (una sola columna en mobile) y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "grid", nombre: "Galeria masonry con lightbox", descripcion: "Mosaico que revela imagenes y zoom modal", prompt: "Disena una galeria masonry en HTML+CSS+JS vanilla (columns o grid con span variable) sobre fondo #08090C. Las imagenes entran con stagger al scroll (blur-up: de un placeholder borroso a nitido con filter blur animado y scale). Hover: leve zoom del contenido dentro de su marco (overflow hidden), overlay con titulo que sube desde abajo y un icono de expandir. Al click abre un lightbox: backdrop blur, la imagen crece desde su posicion original hacia el centro (animacion tipo shared-element calculando el rect de origen) con fade; navegacion prev/next con slide y cierre con Escape o click fuera. Contador y captions. Usa placeholders por gradiente/SVG. Tipografia Inter. Entrega un archivo HTML+CSS+JS autocontenido, accesible (foco atrapado en lightbox), responsive y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "form", nombre: "Slider de rango dual", descripcion: "Control de precio con dos manijas y tooltip", prompt: "Crea un range slider dual (min-max) en HTML+CSS+JS puro para filtrar por precio. Dos manijas arrastrables sobre una pista; el tramo entre ambas se resalta con gradiente y se actualiza en vivo (pointer events, mouse y touch, evitando que se crucen). Cada manija muestra un tooltip con su valor que aparece al arrastrar (fade+scale) y la manija activa crece con un halo. Inputs numericos sincronizados debajo. Snap opcional a pasos con un tick sutil. Al soltar, un pequeno rebote elastico. Fondo #0F1117, pista #232733, acento #10B981. Tipografia Inter, valores en monospace. Soporta teclado (flechas, Home/End) con la manija enfocada. Entrega un unico archivo HTML+CSS+JS autocontenido, accesible (role=slider, aria-valuenow), responsive y con prefers-reduced-motion." },
  { sector: "Componentes", layout: "grid", nombre: "Progreso circular y anillos", descripcion: "Indicadores radiales con conteo y gradiente", prompt: "Disena un set de indicadores de progreso circular en HTML+CSS+JS vanilla usando SVG. Anillos con stroke-dashoffset animado al entrar en viewport, con gradiente en el trazo (linearGradient), extremos redondeados y un track de fondo tenue. El porcentaje en el centro cuenta hasta el valor sincronizado con el llenado (rAF). Incluye una variante multi-segmento (varios arcos de distinto color como grafico de anillo) con leyenda, y una variante con glow pulsante al completar. Hover: el anillo se engrosa levemente y muestra detalle. Fondo #0B0D12, tarjetas con borde highlight. Tipografia Clash Display para el numero central. La animacion respeta prefers-reduced-motion mostrando el estado final. Entrega un unico archivo HTML+CSS+JS autocontenido y responsive." },
  { sector: "Componentes", layout: "grid", nombre: "Sidebar colapsable animada", descripcion: "Nav lateral que se contrae mostrando solo iconos", prompt: "Crea una sidebar de dashboard colapsable en HTML+CSS+JS puro. Un boton contrae el ancho (transition de width) dejando solo iconos; las etiquetas de texto se desvanecen y colapsan (opacity+width) y al pasar el cursor por un icono en modo compacto aparece un tooltip lateral. Un pill de fondo indica el item activo y se desliza suavemente al cambiar de seccion (transform). Grupos con headers y secciones expandibles animando grid-template-rows. Persistencia del estado colapsado en localStorage. En mobile se convierte en drawer con overlay y slide-in. Fondo #0C0E13, panel #14161D, acento #6366F1, hairlines sutiles. Tipografia Inter, iconos SVG inline. Entrega un archivo HTML+CSS+JS autocontenido, accesible (aria-current, navegacion por teclado), responsive y con prefers-reduced-motion." },
  { sector: "Creativo", layout: "scene3d", nombre: "Flow Field Aurora", descripcion: "Arte generativo con campo de flujo", prompt: "Lienzo de arte generativo full-screen con 12.000 partículas navegando un flow field basado en ruido Perlin (usa simplex-noise por CDN sobre canvas 2D). Paleta aurora boreal sobre negro absoluto #05060a: cian #22d3ee, magenta #d946ef, verde ácido #a3e635, con trails de baja opacidad (globalAlpha 0.04) que dejan estelas sedosas. Las partículas cambian de vector cada frame; cada 8s el campo rota su seed con una transición GSAP ease power2.inOut. Tipografía Space Grotesk para un título flotante 'FLUX' en 120px con mix-blend-mode difference. Cursor atrae partículas en radio de 180px. Entregable: HTML+CSS+JS en un solo archivo, canvas responsive con devicePixelRatio, requestAnimationFrame." },
  { sector: "Creativo", layout: "scene3d", nombre: "Voronoi Shatter", descripcion: "Mosaico Voronoi generativo animado", prompt: "Composicion generativa de teselado Voronoi que respira: 90 semillas relajadas con Lloyd sobre canvas. Paleta editorial calida: crema #f4 ede0, terracota #c2410c, oliva #4d7c0f, indigo #312e81, con bordes hairline de 1px en negro suave. Cada celda late con una escala sutil desfasada por seno; al pasar el mouse la celda cercana se expande y revela un numero de dato. Grid magazine con margenes amplios, tipografia Fraunces para titulares serif de alto contraste y JetBrains Mono para captions. Transiciones con GSAP timeline en loop. Entregable: HTML+CSS+JS unico, canvas 2D con d3-delaunay por CDN." },
  { sector: "Creativo", layout: "scene3d", nombre: "Particle Text Morph", descripcion: "Texto que se forma con particulas", prompt: "Sistema de 8.000 particulas que se ensamblan para dibujar palabras sucesivas ('CREA', 'ITERA', 'ENVIA') muestreando el texto de un canvas oculto. Fondo gradiente radial noche #0a0a12 a #14142b. Particulas en degradado violeta #8b5cf6 a rosa #ec4899 con glow via shadowBlur. Al cambiar de palabra las particulas estallan y reconvergen con easing elastico controlado por GSAP. Micro-parallax siguiendo el mouse. Tipografia Clash Display para un subtitulo fijo abajo. Entregable: HTML+CSS+JS en un archivo, canvas 2D, sampling de pixeles con getImageData, requestAnimationFrame a 60fps." },
  { sector: "Creativo", layout: "scene3d", nombre: "WebGL Fluid Ink", descripcion: "Tinta liquida interactiva WebGL", prompt: "Simulacion de tinta fluida estilo Stable Fluids en WebGL (shaders GLSL de adveccion y presion) que reacciona al arrastre del cursor dejando volutas de color. Paleta jewel sobre negro: cobalto #1d4ed8, fucsia #db2777, ambar #f59e0b mezclandose en gradientes imposibles. Disipacion lenta y vorticidad alta para remolinos organicos. Overlay de UI minimalista con tipografia Neue Montreal, un contador de FPS y un boton 'splat' que inyecta color aleatorio. Entregable: Three.js por CDN con render target de doble buffer, HTML+CSS+JS unico, responsive." },
  { sector: "Creativo", layout: "scene3d", nombre: "Audio Reactive Orb", descripcion: "Esfera 3D reactiva al audio", prompt: "Visualizador de audio con una icosfera 3D cuyos vertices se desplazan por ruido y por la amplitud de la musica (Web Audio API + AnalyserNode, FFT 256). Three.js por CDN, material MeshStandardMaterial con emissive pulsante y bloom via UnrealBloomPass. Paleta synthwave: fondo #0d0221, esfera degradada magenta #ff2d95 a cian #05d9e8, wireframe superpuesto. Los graves inflan la esfera, los agudos erizan picos. Anillo de barras radiales alrededor. Drag para orbitar (OrbitControls). Input: archivo de audio o microfono con boton. Entregable: HTML+CSS+JS unico con Three.js CDN." },
  { sector: "Creativo", layout: "grid", nombre: "Spectrum Bars Pro", descripcion: "Barras de espectro de audio elegantes", prompt: "Visualizador de espectro de audio de 64 barras dibujadas a mano en canvas 2D con esquinas redondeadas y reflejo especular en el suelo. Web Audio API con AnalyserNode y suavizado 0.8. Paleta studio dark: fondo #101014, barras con gradiente vertical de verde #10b981 a amarillo #eab308 a rojo #ef4444 segun altura, glow sutil. Pico persistente que cae con gravedad. Tipografia Inter para etiquetas de frecuencia (Hz) en el eje. Controles play/pause y carga de MP3. Entregable: HTML+CSS+JS en un solo archivo, canvas responsive, requestAnimationFrame, sin librerias de terceros." },
  { sector: "Creativo", layout: "scene3d", nombre: "Waveform Ribbon", descripcion: "Onda de audio como cinta 3D", prompt: "Onda de audio renderizada como una cinta sinuosa en 3D que fluye en perspectiva, con la forma de onda del tiempo mapeada a la altura de un tubo. Three.js por CDN con TubeGeometry actualizada por frame desde el time-domain data del AnalyserNode. Paleta oceanica: fondo degradado #020617 a #0f172a, cinta con gradiente turquesa #06b6d4 a violeta #7c3aed, niebla sutil. Camara con leve dolly automatico. Tipografia Space Grotesk para el titulo del track. Entregable: HTML+CSS+JS unico, Three.js CDN, Web Audio API, responsive con manejo de resize." },
  { sector: "Datos", layout: "dashboard", nombre: "Bar Race Animated", descripcion: "Carrera de barras horizontales animada", prompt: "Grafico de barras horizontales tipo 'bar chart race' hecho a mano en canvas, con transiciones fluidas de posicion y ancho al avanzar los anios. Sin librerias de charting: interpolacion manual con GSAP para reordenar barras y animar valores con contadores. Paleta dashboard limpia: fondo #0f1117, barras en categorical accesible (indigo #6366f1, teal #14b8a6, coral #fb7185, ambar #f59e0b), texto #e2e8f0. Tipografia Inter tabular-nums para cifras alineadas, etiqueta de anio gigante en marca de agua. Slider de tiempo y play. Entregable: HTML+CSS+JS unico, canvas 2D responsive, GSAP por CDN." },
  { sector: "Datos", layout: "dashboard", nombre: "Donut Gauge Suite", descripcion: "Anillos donut animados con conteo", prompt: "Panel de 4 graficos donut dibujados a mano en canvas (arc con lineCap round) que se rellenan con animacion de barrido easing easeOutCubic al cargar y un numero central que cuenta hasta el valor. Paleta soft dark: fondo #111827, anillos en menta #34d399, cielo #38bdf8, lavanda #a78bfa, durazno #fb923c sobre pista #1f2937. Tipografia Satoshi para los porcentajes centrales en peso 600 y Inter para labels. Micro-interaccion: hover engrosa el anillo y muestra tooltip. Grid dashboard de 2x2 con tarjetas de radio 16px y sombra difusa. Entregable: HTML+CSS+JS en un archivo, canvas 2D, requestAnimationFrame." },
  { sector: "Datos", layout: "dashboard", nombre: "Live Line Stream", descripcion: "Grafico de linea en tiempo real", prompt: "Grafico de linea de series temporales en streaming que desplaza datos en vivo con curva suavizada (interpolacion Catmull-Rom) y area rellena con gradiente que se desvanece. Canvas 2D a mano, sin Chart.js. Paleta terminal moderna: fondo #0b0f19, linea neon lima #a3e635 con glow, grid punteado #1e293b, punto lider pulsante. Eje Y con ticks animados y tooltip que sigue el cursor mostrando timestamp. Tipografia JetBrains Mono para valores. Genera datos sinteticos con random walk. Entregable: HTML+CSS+JS unico, canvas responsive, requestAnimationFrame, sin dependencias." },
  { sector: "Datos", layout: "grid", nombre: "Stream Graph Flow", descripcion: "Streamgraph organico multiserie", prompt: "Streamgraph (grafico de flujo apilado con baseline wiggle) que muestra la evolucion de 6 categorias como corrientes organicas superpuestas. Canvas 2D a mano con paths suavizados; al hover se resalta la corriente y se atenuan las demas con transicion opacity via GSAP. Paleta risograph: fondo hueso #faf7f0, corrientes en coral #f4715b, azul #4361ee, mostaza #f9c74f, verde #43aa8b, ciruela #9d4edd con leve textura de grano. Tipografia Fraunces para el titulo y Inter Tight para leyenda. Entregable: HTML+CSS+JS unico, canvas responsive, d3-shape opcional por CDN solo para stack." },
  { sector: "Datos", layout: "grid", nombre: "Calendar Heatmap", descripcion: "Mapa de calor anual estilo contribuciones", prompt: "Mapa de calor de calendario anual (53 semanas x 7 dias) estilo grid de contribuciones, con celdas redondeadas que escalan y suben al hover mostrando tooltip con fecha y valor. Escala secuencial accesible de 5 pasos: de #1e293b vacio a verde #16a34a intenso; version alterna en morado. Animacion de entrada en cascada diagonal con stagger. Tipografia Inter para meses y dias, leyenda 'menos/mas'. Fondo #0d1117. Datos sinteticos con picos estacionales. Entregable: HTML+CSS+JS unico, grid CSS para las celdas, canvas no necesario, transiciones CSS + IntersectionObserver." },
  { sector: "Datos", layout: "grid", nombre: "Matrix Heatmap", descripcion: "Matriz de correlacion interactiva", prompt: "Mapa de calor matricial de correlacion NxN con escala divergente centrada en cero (azul #2563eb negativo, blanco #f1f5f9 neutro, rojo #dc2626 positivo) y valores numericos que aparecen al hover. Canvas 2D o grid CSS; fila y columna se resaltan con crosshair al pasar el cursor. Ordenamiento por clustering al click de un boton con reordenamiento animado GSAP. Tipografia JetBrains Mono para coeficientes, Inter para etiquetas rotadas 45deg. Fondo #0f172a, leyenda de gradiente vertical. Entregable: HTML+CSS+JS unico, responsive, tooltip flotante." },
  { sector: "Datos", layout: "dashboard", nombre: "Timeline Scrollytelling", descripcion: "Linea de tiempo interactiva con scroll", prompt: "Timeline horizontal interactiva de hitos que avanza con scroll-snap y una linea de progreso que se dibuja (stroke-dashoffset) a medida que se navega. Nodos que se activan con pop y revelan una tarjeta con fecha, titulo y descripcion via IntersectionObserver. Paleta editorial dark: fondo #0a0a0f, linea gradiente cian #22d3ee a violeta #8b5cf6, nodos con halo. Tipografia Clash Display para anios grandes y Inter para cuerpo. Parallax leve en las tarjetas. Entregable: HTML+CSS+JS unico, SVG para la linea, GSAP ScrollTrigger por CDN, responsive a vertical en movil." },
  { sector: "Datos", layout: "dashboard", nombre: "Radial Timeline Clock", descripcion: "Cronologia radial en espiral", prompt: "Cronologia radial donde los eventos se distribuyen en una espiral de Arquimedes alrededor de un centro, cada hito como punto sobre el brazo con conector a su etiqueta. Canvas 2D para la espiral animada que se despliega al cargar (draw progresivo) y HTML para las etiquetas posicionadas. Paleta cosmica: fondo #060314, espiral degradada indigo #4338ca a fucsia #db2777, puntos con glow pulsante. Rotacion suave continua y zoom al click en un evento. Tipografia Space Grotesk. Entregable: HTML+CSS+JS unico, canvas + overlay absoluto, requestAnimationFrame." },
  { sector: "Creativo", layout: "dashboard", nombre: "Kanban Drag Fluid", descripcion: "Tablero kanban con arrastre fluido", prompt: "Tablero kanban de 4 columnas (Backlog, En curso, Revision, Hecho) con drag-and-drop nativo HTML5 y animacion de reordenamiento FLIP suave al soltar. Las tarjetas se inclinan y elevan con sombra al arrastrar, la columna destino resalta su borde. Paleta producto dark: fondo #0f1116, columnas #171922, tarjetas #1e2130 con acento por prioridad (rojo #ef4444, ambar #f59e0b, verde #22c55e). Tipografia Inter, chips de etiqueta redondeados, avatar y contador por columna. Persistencia en localStorage. Entregable: HTML+CSS+JS unico, tecnica FLIP para transiciones, responsive con scroll horizontal en movil." },
  { sector: "Creativo", layout: "dashboard", nombre: "Kanban Neumorph", descripcion: "Kanban minimal con drag y confeti", prompt: "Kanban minimalista claro con drag-and-drop y micro-celebracion de confeti canvas al mover una tarjeta a 'Hecho'. Estilo soft-UI: fondo #eef1f6, tarjetas blancas con doble sombra sutil y radio 14px, columnas con encabezado sticky. Acentos pastel por columna: azul #93c5fd, morado #c4b5fd, verde #86efac. Placeholder animado que indica el hueco de insercion durante el drag. Tipografia Satoshi para titulos y Inter para descripciones, contador que anima al cambiar. Entregable: HTML+CSS+JS unico, drag nativo + confeti en canvas propio, sin librerias, localStorage." },
  { sector: "Creativo", layout: "grid", nombre: "Visual Calendar Month", descripcion: "Calendario mensual visual con eventos", prompt: "Calendario mensual visual tipo grid 7x6 con celdas que muestran chips de eventos de colores y un indicador de densidad (barra inferior). Transicion de mes con deslizamiento y fade al navegar (GSAP). Dia actual resaltado con anillo, hover eleva la celda. Paleta calida clara: fondo #fbfaf7, rejilla hairline #e7e2d8, eventos en coral #fb7185, indigo #6366f1, teal #14b8a6. Mini-panel lateral con la agenda del dia seleccionado. Tipografia Fraunces para el nombre del mes y Inter para numeros tabulares. Entregable: HTML+CSS+JS unico, grid CSS, responsive, datos de ejemplo." },
  { sector: "Datos", layout: "dashboard", nombre: "Year Heat Calendar", descripcion: "Calendario anual con intensidad de datos", prompt: "Vista de calendario anual de 12 mini-meses en grid donde cada dia se tinta segun un valor (actividad) con escala secuencial y tooltip al hover. Selector para cambiar la metrica que reanima los colores con transicion. Paleta dark analytics: fondo #0b0f17, escala de #1f2937 a naranja #f97316; leyenda y totales por mes. Animacion de entrada mes a mes con stagger. Tipografia Inter, cifras mono para totales. Resumen superior con KPIs (racha maxima, promedio). Entregable: HTML+CSS+JS unico, grid CSS, sin dependencias, IntersectionObserver para el reveal." },
  { sector: "Datos", layout: "grid", nombre: "Infografia Editorial", descripcion: "Infografia de una pagina con datos", prompt: "Infografia editorial de una sola pagina que combina un gran numero destacado, tres donuts pequenos, una barra comparativa y un icono-array (pictograma) para proporciones. Estetica revista premium: fondo crema #f6f2e9, tinta #1c1917, acentos rojo bermellon #dc2626 y azul klein #1d4ed8. Todos los graficos animan su entrada al hacer scroll (contadores, arcos, barras) con stagger. Tipografia Fraunces display para titulares y Inter para datos con numeros tabulares. Grid editorial de 12 columnas con jerarquia clara. Entregable: HTML+CSS+JS unico, SVG para graficos, IntersectionObserver + GSAP, responsive." },
  { sector: "Datos", layout: "grid", nombre: "Infografia Neon Stats", descripcion: "Infografia tech con stats animadas", prompt: "Infografia de estilo tech/futurista con tarjetas de KPI que brillan, medidores tipo velocimetro en canvas y una barra de progreso segmentada. Paleta neon dark: fondo #050810, glass cards con borde gradiente cian #22d3ee a magenta #d946ef, glow y lineas de escaneo sutiles. Contadores que suben al entrar en viewport, agujas de gauge con easing elastico. Tipografia Space Grotesk para titulos y JetBrains Mono para metricas. Layout grid asimetrico con jerarquia de tamanos. Entregable: HTML+CSS+JS unico, canvas para los gauges, IntersectionObserver, responsive, sin CDNs pesados." },
  { sector: "Creativo", layout: "scene3d", nombre: "Generative Grid Mondrian", descripcion: "Composicion generativa estilo Mondrian", prompt: "Generador de composiciones tipo Mondrian que subdivide recursivamente el lienzo en rectangulos y colorea algunos con animacion de aparicion escalonada. Boton 'regenerar' produce una nueva composicion con transicion morph entre layouts (GSAP). Paleta clasica reinterpretada: fondo blanco roto #faf9f6, lineas negras gruesas #0a0a0a, bloques en rojo #e63946, azul #1d3557, amarillo #ffd60a mas un neutro gris. Tipografia Archivo para una firma esquinera. Entregable: HTML+CSS+JS unico, canvas 2D o divs animados, subdivision recursiva, responsive, requestAnimationFrame." },
  { sector: "Creativo", layout: "scene3d", nombre: "Noise Terrain 3D", descripcion: "Terreno generativo 3D animado", prompt: "Paisaje generativo 3D: una malla de plano deformada por ruido simplex animado que ondula como dunas, renderizada en wireframe con degradado de altura. Three.js por CDN, PlaneGeometry con vertices actualizados por frame, camara en orbita lenta automatica. Paleta atardecer digital: fondo gradiente #1a0b2e a #ff6b6b, malla de violeta #7c3aed a rosa #f472b6, niebla exponencial. Post-proceso bloom sutil. Tipografia Clash Display para un titulo overlay con blend mode. Entregable: HTML+CSS+JS unico, Three.js CDN, simplex-noise CDN, responsive con resize." },
  { sector: "Creativo", layout: "scene3d", nombre: "Cursor Trail Constellation", descripcion: "Constelacion generativa reactiva al cursor", prompt: "Arte generativo de constelacion: nodos flotantes que se conectan con lineas cuando estan cerca y se enlazan al cursor formando una red viva (estilo particles.js hecho a mano). Canvas 2D, fisica ligera con rebote en bordes. Paleta noche estrellada: fondo radial #030712, nodos blanco-azulado #bfdbfe con glow, lineas cuya opacidad decae con la distancia. Al hacer click se emite una onda que empuja los nodos cercanos. Tipografia Space Grotesk para un HUD minimo con contador de conexiones. Entregable: HTML+CSS+JS unico, canvas responsive con devicePixelRatio, requestAnimationFrame, sin librerias." },
  { sector: "Web", layout: "hero", nombre: "Nova Analytics SaaS", descripcion: "Dashboard B2B con hero centrado", prompt: "Landing para SaaS de analítica B2B llamado Nova. Estilo moderno tech, fondo blanco con gradientes sutiles violeta-índigo (#6D5EF6 a #8B7CFF), tipografía sans geométrica (Inter). Hero centrado con titular grande, badge 'Nuevo: IA integrada', doble CTA y captura de dashboard flotante con sombra suave. Entregable: HTML + CSS con hero, logos de clientes, grid de features y footer." },
  { sector: "Web", layout: "split", nombre: "Estudio Kora Creativo", descripcion: "Agencia con split editorial audaz", prompt: "Landing para agencia creativa Kora. Estilo editorial atrevido, fondo negro carbón (#0A0A0A) con acentos coral vibrante (#FF5A3C) y tipografía serif display enorme mezclada con mono. Layout split: mitad izquierda titular gigante rotado, mitad derecha imagen de proyecto a sangre. Entregable: HTML + CSS con split hero, cinta de servicios en marquesina y bloque de contacto." },
  { sector: "Web", layout: "hero", nombre: "Sazón Restaurante", descripcion: "Alta cocina con hero fotográfico", prompt: "Landing para restaurante de alta cocina Sazón. Estilo elegante gastronómico, foto de plato a pantalla completa oscurecida, tipografía serif fina dorada (#C9A227) sobre negro profundo. Hero con reserva integrada, horario y frase del chef. Entregable: HTML + CSS con hero fotográfico, sección de menú degustación en dos columnas y bloque de reservas con formulario." },
  { sector: "Web", layout: "grid", nombre: "Trama Moda Store", descripcion: "Ecommerce moda con grilla de productos", prompt: "Landing ecommerce de moda urbana Trama. Estilo limpio minimal fashion, fondo crema (#F4F1EC), acentos negro y verde oliva, tipografía sans condensada. Grid de productos tipo lookbook con hover que muestra segundo ángulo y precio. Entregable: HTML + CSS con barra superior, grid responsive de 6 productos, banner de colección y newsletter." },
  { sector: "Web", layout: "hero", nombre: "Pulse Fitness Club", descripcion: "Gimnasio con hero energético", prompt: "Landing para gimnasio Pulse. Estilo dinámico y potente, fondo negro con acentos amarillo neón (#D9FF3C) y magenta, tipografía bold itálica. Hero con foto de atleta en movimiento, contador de miembros y CTA 'Primera semana gratis'. Entregable: HTML + CSS con hero energético, tarjetas de planes de membresía, horarios de clases y testimonios." },
  { sector: "Web", layout: "split", nombre: "Altura Inmobiliaria", descripcion: "Bienes raíces de lujo en split", prompt: "Landing inmobiliaria de lujo Altura. Estilo sofisticado y sereno, paleta beige arena, blanco y azul pizarra (#2E3A45), tipografía serif elegante. Split: izquierda datos de la propiedad y CTA de visita, derecha render arquitectónico a sangre con precio superpuesto. Entregable: HTML + CSS con split hero, listado destacado de propiedades y formulario de agenda de visita." },
  { sector: "Web", layout: "hero", nombre: "Vértice Conf Tech", descripcion: "Evento tech con hero countdown", prompt: "Landing para conferencia tecnológica Vértice 2026. Estilo futurista con gradiente cian-morado sobre fondo azul noche (#0B1026), grid de puntos y glow, tipografía sans futurista. Hero con nombre del evento, fecha, cuenta regresiva animada y CTA de entradas. Entregable: HTML + CSS con hero countdown, grid de speakers, agenda por días y bloque de sponsors." },
  { sector: "Web", layout: "split", nombre: "Raíz ONG Ambiental", descripcion: "ONG verde con split de impacto", prompt: "Landing para ONG ambiental Raíz. Estilo cálido y esperanzador, paleta verde bosque (#2F6B3C), tierra y crema, tipografía humanista redondeada. Split: izquierda mensaje de misión con CTA 'Donar', derecha foto de reforestación con contador de árboles plantados. Entregable: HTML + CSS con split hero, métricas de impacto, historias y formulario de donación." },
  { sector: "Web", layout: "hero", nombre: "Flow App Showcase", descripcion: "App móvil con mockup flotante", prompt: "Landing showcase de app móvil de productividad Flow. Estilo Apple-like premium, fondo blanco con degradado gris perla, acentos azul eléctrico (#2D7FF9), tipografía sans limpia. Hero centrado con dos mockups de iPhone flotando en ángulo y badges de App Store. Entregable: HTML + CSS con hero de mockups, features alternadas con capturas y sección de descarga." },
  { sector: "Web", layout: "hero", nombre: "Nexo Neobanco", descripcion: "Fintech con hero de tarjeta 3D", prompt: "Landing para neobanco Nexo. Estilo fintech moderno y confiable, fondo azul profundo (#0E2A47) con gradiente aqua, tipografía sans redondeada. Hero con tarjeta bancaria flotante en 3D con reflejos, titular sobre finanzas sin comisiones y CTA 'Abrir cuenta'. Entregable: HTML + CSS con hero de tarjeta, features de seguridad, comparativa de planes y sellos de confianza." },
  { sector: "Web", layout: "grid", nombre: "Saber Cursos Online", descripcion: "Edtech con grilla de cursos", prompt: "Landing para plataforma de cursos online Saber. Estilo amigable educativo, paleta índigo (#4B44C4), amarillo y blanco, tipografía sans clara con ilustraciones planas. Grid de tarjetas de cursos con categoría, duración, nivel y rating por estrellas. Entregable: HTML + CSS con hero breve, buscador, grid de 6 cursos, barra de categorías y CTA de prueba gratis." },
  { sector: "Web", layout: "split", nombre: "Sonrisa Clínica Dental", descripcion: "Salud dental con split confiable", prompt: "Landing para clínica dental Sonrisa. Estilo salud limpio y cálido, paleta blanco, celeste suave (#5BC5D6) y menta, tipografía sans amable. Split: izquierda titular tranquilizador con CTA 'Agendar turno', derecha foto de paciente sonriendo. Entregable: HTML + CSS con split hero, tarjetas de tratamientos, equipo de dentistas y formulario de turno." },
  { sector: "Web", layout: "grid", nombre: "Rumbo Viajes", descripcion: "Agencia de viajes con grilla de destinos", prompt: "Landing para agencia de viajes Rumbo. Estilo aventurero y vívido, paleta turquesa (#12A9A0), coral y arena, tipografía sans con acentos manuscritos. Grid tipo mosaico de destinos con fotos, precio 'desde' y etiqueta de temporada. Entregable: HTML + CSS con hero de búsqueda de viaje, grid de 6 destinos, ofertas destacadas y newsletter." },
  { sector: "Web", layout: "hero", nombre: "Eco Artista Musical", descripcion: "Músico con hero inmersivo oscuro", prompt: "Landing para artista musical Eco lanzando álbum. Estilo inmersivo y artístico, fondo negro con degradado púrpura-azul y textura de grano, tipografía display condensada. Hero con portada del álbum, botón de reproducir y enlaces a plataformas de streaming. Entregable: HTML + CSS con hero del álbum, reproductor de tracklist, próximas fechas de gira y footer social." },
  { sector: "Web", layout: "hero", nombre: "Nebula Game Studio", descripcion: "Estudio gaming con hero cinemático", prompt: "Landing para estudio de videojuegos Nebula presentando su título. Estilo gamer cinemático, fondo espacial oscuro con neón cian y rojo, glow y partículas, tipografía tech angular. Hero con key art a sangre, logo del juego, tráiler embebido y CTA 'Añadir a lista de deseos'. Entregable: HTML + CSS con hero cinemático, galería de screenshots, features del juego y plataformas." },
  { sector: "Web", layout: "hero", nombre: "Ledger Crypto Exchange", descripcion: "Exchange cripto con hero de datos", prompt: "Landing para exchange de criptomonedas Ledger. Estilo cripto premium oscuro, fondo negro azulado (#0C0F1A) con acentos verde menta (#00E5A0) y glow, tipografía mono-sans. Hero con titular de trading, ticker de precios en vivo simulado y CTA 'Comprar cripto'. Entregable: HTML + CSS con hero de ticker, features de seguridad, tabla de monedas y sellos regulatorios." },
  { sector: "Web", layout: "split", nombre: "DevForge Herramienta", descripcion: "Dev tool con split terminal oscuro", prompt: "Landing para herramienta de desarrolladores DevForge. Estilo developer oscuro, fondo casi negro (#0D1117), acentos verde terminal (#3FB950) y violeta, tipografía monoespaciada. Split: izquierda titular técnico con CTA 'Instalar' y comando copiable, derecha ventana de terminal con código coloreado. Entregable: HTML + CSS con split hero, bloque de features, snippet de código y estrellas de GitHub." },
  { sector: "Web", layout: "grid", nombre: "Blanco Estudio Branding", descripcion: "Agencia branding minimal en grid", prompt: "Landing para estudio de branding minimalista Blanco. Estilo suizo ultra-minimal, fondo blanco puro, negro y un solo acento rojo (#FF3B30), muchísimo espacio en blanco, tipografía grotesque grande. Grid asimétrico de casos de estudio con número, cliente y año. Entregable: HTML + CSS con hero tipográfico, grid de proyectos, lista de servicios y contacto sobrio." },
  { sector: "Web", layout: "hero", nombre: "Ramen Ya Street Food", descripcion: "Ramen bar con hero vibrante", prompt: "Landing para ramen bar Ramen Ya. Estilo street food japonés vibrante, paleta rojo lacado (#D6262C), crema y negro, tipografía display con toques kanji e ilustración de tazón humeante. Hero con foto cenital de ramen, CTA 'Pedir online' y horario. Entregable: HTML + CSS con hero apetitoso, menú de bowls en tarjetas, ubicación con mapa y sección de pedido." },
  { sector: "Web", layout: "split", nombre: "Nórdica Muebles", descripcion: "Ecommerce deco en split cálido", prompt: "Landing ecommerce de muebles y deco Nórdica. Estilo escandinavo cálido, paleta madera clara, blanco roto y verde salvia (#8FA68E), tipografía serif suave. Split: izquierda producto destacado con precio y CTA 'Comprar', derecha foto de ambiente de interior luminoso. Entregable: HTML + CSS con split hero, grid de productos, banner de envío gratis y newsletter." },
  { sector: "Web", layout: "hero", nombre: "Zen Estudio Yoga", descripcion: "Yoga y wellness con hero sereno", prompt: "Landing para estudio de yoga Zen. Estilo calmo y orgánico, paleta terracota (#C77B58), crema y verde oliva, formas curvas y tipografía serif ligera. Hero sereno con foto de práctica al amanecer, frase inspiradora y CTA 'Reservá tu clase'. Entregable: HTML + CSS con hero suave, tipos de clases, horarios semanales y planes de suscripción." },
  { sector: "Web", layout: "grid", nombre: "Hub Coworking", descripcion: "Coworking con grilla de espacios", prompt: "Landing para espacio de coworking Hub. Estilo urbano fresco, paleta naranja cálido (#FF7A29), gris grafito y blanco, tipografía sans moderna. Grid de tipos de espacio (hot desk, oficina privada, sala de reuniones) con foto, precio y capacidad. Entregable: HTML + CSS con hero, grid de espacios, amenidades con íconos y formulario de tour." },
  { sector: "Web", layout: "split", nombre: "Onda Podcast", descripcion: "Podcast con split de episodio", prompt: "Landing para podcast Onda. Estilo retro-moderno cálido, paleta mostaza (#E8A33D), granate y crema, tipografía display redonda con textura. Split: izquierda titular del show con CTA de suscripción y plataformas, derecha portada del último episodio con botón de play. Entregable: HTML + CSS con split hero, lista de episodios recientes, bio de hosts y suscripción." },
  { sector: "Web", layout: "hero", nombre: "Cognita Startup IA", descripcion: "Startup IA con hero de gradiente", prompt: "Landing para startup de IA Cognita. Estilo futurista suave, fondo blanco con gradiente aurora rosa-violeta-cian y mesh blur, tipografía sans moderna. Hero centrado con titular sobre automatización inteligente, campo de email y CTA 'Solicitar acceso'. Entregable: HTML + CSS con hero mesh, bloque de casos de uso, logos de respaldo y sección de waitlist." },
  { sector: "Web", layout: "hero", nombre: "Grano Café de Especialidad", descripcion: "Cafetería con hero artesanal", prompt: "Landing para cafetería de especialidad Grano. Estilo artesanal cálido, paleta marrón café (#4A2E1E), crema y cobre, tipografía serif vintage con detalles manuscritos. Hero con foto de latte art, frase sobre origen del grano y CTA 'Visitanos'. Entregable: HTML + CSS con hero, sección de granos de origen, menú de bebidas y ubicación con horarios." },
  { sector: "Web", layout: "split", nombre: "Filo Barbería", descripcion: "Barbería con split clásico oscuro", prompt: "Landing para barbería Filo. Estilo vintage masculino, paleta negro, cuero marrón (#6B4226) y dorado envejecido, tipografía slab serif con emblema. Split: izquierda titular y CTA 'Reservá tu corte', derecha foto en blanco y negro de corte clásico. Entregable: HTML + CSS con split hero, lista de servicios con precios, galería de estilos y booking." },
  { sector: "Web", layout: "hero", nombre: "Enlace Wedding Planner", descripcion: "Bodas con hero elegante floral", prompt: "Landing para wedding planner Enlace. Estilo romántico elegante, paleta blush rosa (#E8C8C8), verde eucalipto y dorado, tipografía script caligráfica con serif fina. Hero con foto de boda soñada, frase emotiva y CTA 'Planeá tu día'. Entregable: HTML + CSS con hero floral, servicios de planificación, galería de bodas reales y formulario de consulta." },
  { sector: "Web", layout: "grid", nombre: "Luz Fotografía Portfolio", descripcion: "Fotógrafo con grilla de portfolio", prompt: "Landing portfolio de fotógrafo Luz. Estilo minimal galería, fondo blanco casi total, negro y foco absoluto en la imagen, tipografía sans fina espaciada. Grid tipo masonry de fotografías a alta resolución con hover que revela título y categoría. Entregable: HTML + CSS con hero minimal, grid masonry de 8 fotos, bloque sobre mí y contacto." },
  { sector: "Web", layout: "split", nombre: "Capital Robo-Advisor", descripcion: "Inversiones con split de gráfico", prompt: "Landing para plataforma de inversiones automatizadas Capital. Estilo fintech confiable y sobrio, paleta azul marino (#12294D), verde crecimiento (#1DB981) y blanco, tipografía sans precisa. Split: izquierda titular sobre invertir en piloto automático y CTA 'Empezá a invertir', derecha gráfico de rendimiento ascendente. Entregable: HTML + CSS con split hero, pasos de cómo funciona, comparativa de carteras y sellos de seguridad." },
  { sector: "Web", layout: "hero", nombre: "Stream Plataforma Video", descripcion: "Streaming con hero de catálogo", prompt: "Landing para plataforma de streaming Stream. Estilo entretenimiento premium oscuro, fondo negro con degradado rojo intenso (#E50914), tipografía sans bold. Hero con titular sobre contenido ilimitado, CTA 'Probá gratis' y carrusel de portadas al pie con desvanecido. Entregable: HTML + CSS con hero de catálogo, fila de destacados, planes de suscripción y FAQ." },
  { sector: "Web", layout: "split", nombre: "Aura Spa Estético", descripcion: "Spa estético con split lujoso", prompt: "Landing para spa y clínica estética Aura. Estilo lujo relajante, paleta nude rosado (#E3C9BE), champagne y gris cálido, tipografía serif refinada con mucho aire. Split: izquierda titular sobre bienestar con CTA 'Reservá tu sesión', derecha foto de tratamiento facial sereno. Entregable: HTML + CSS con split hero, menú de tratamientos, testimonios y formulario de reserva." },
  { sector: "Web", layout: "hero", nombre: "Brillo Joyería", descripcion: "Joyería con hero minimalista premium", prompt: "Landing ecommerce de joyería Brillo. Estilo lujo minimalista, fondo negro profundo con acentos dorados (#D4AF37) y tipografía serif delgada elegante. Hero centrado con pieza de joyería en primer plano sobre fondo oscuro, titular sobre elegancia atemporal y CTA 'Ver colección'. Entregable: HTML + CSS con hero de producto, grid de piezas destacadas, historia de marca y newsletter." },
  { sector: "Web", layout: "grid", nombre: "Código Bootcamp", descripcion: "Bootcamp de programación en grid", prompt: "Landing para bootcamp de programación Código. Estilo tech juvenil enérgico, paleta violeta eléctrico (#7C3AED), lima y gris oscuro, tipografía sans bold con acentos mono. Grid de programas (Full Stack, Data, UX) con duración, modalidad y tasa de empleabilidad. Entregable: HTML + CSS con hero de conversión, grid de programas, línea de tiempo del curso, testimonios de egresados y CTA de inscripción." },
  { sector: "Web", layout: "hero", nombre: "Talento Marketplace Freelance", descripcion: "Marketplace freelance con hero dual", prompt: "Landing para marketplace de freelancers Talento. Estilo marketplace fresco y confiable, paleta azul brillante (#2563EB), naranja acento y blanco, tipografía sans clara. Hero con titular dual (contratar / trabajar), buscador de servicios con categorías y prueba social de proyectos completados. Entregable: HTML + CSS con hero de buscador, categorías populares en tarjetas, cómo funciona en pasos y CTA doble." },
  { sector: "Web", layout: "dashboard", nombre: "Analítica SaaS Nébula", descripcion: "Panel de métricas para producto SaaS", prompt: "Diseñá un dashboard de analítica web para una plataforma SaaS B2B, estilo moderno minimalista con dark mode profundo (fondo #0B0F1A, superficies #151A28) y acentos violeta eléctrico (#7C5CFF) y cian (#22D3EE). Sidebar vertical colapsable a la izquierda, top bar con selector de rango de fechas. Fila superior de 4 KPIs (MRR, usuarios activos, churn, conversión) con sparklines. Gráfico de área grande de sesiones en el tiempo, barras de fuentes de tráfico y tabla de páginas top. Entregable: HTML + CSS con CSS Grid, tipografía Inter." },
  { sector: "Web", layout: "dashboard", nombre: "CRM Ventas Meridian", descripcion: "Pipeline comercial B2B tipo Kanban", prompt: "Diseñá un dashboard CRM de ventas B2B con estética corporativa clara (fondo #F7F8FB, tarjetas blancas, sombras suaves) y acento azul índigo (#3355FF) con verde éxito (#16A34A). Header con embudo de pipeline horizontal por etapa, KPIs de deals cerrados, valor de cartera y tasa de cierre. Cuerpo dividido: tablero Kanban de oportunidades con avatares y montos a la izquierda, panel de actividad reciente y tareas del día a la derecha. Entregable: HTML + CSS con flexbox y grid, componentes de tarjeta reutilizables." },
  { sector: "Web", layout: "dashboard", nombre: "Finanzas Personales Pluma", descripcion: "Panel de presupuesto y gastos personales", prompt: "Diseñá un dashboard de finanzas personales cálido y amigable, fondo crema (#FBF7F0), acentos coral (#FF6B5E) y verde menta (#2FBF9E), esquinas muy redondeadas. Tarjeta de balance total destacada arriba con degradado suave. Donut de gastos por categoría, barra de progreso de presupuesto mensual, lista de transacciones recientes con íconos por comercio, y gráfico de línea de ahorro proyectado. Entregable: HTML + CSS, layout responsive con grid, tipografía redondeada tipo Nunito." },
  { sector: "Web", layout: "dashboard", nombre: "Salud Hospital Vitalis", descripcion: "Panel clínico de camas y pacientes", prompt: "Diseñá un dashboard de administración hospitalaria, estilo limpio y confiable con fondo blanco clínico, azul médico (#0E7490) y acentos de estado (verde estable, ámbar observación, rojo crítico). Header con ocupación de camas total y turno actual. Grilla de salas con estado por color, gráfico de admisiones/altas del día, lista de pacientes prioritarios con signos vitales, y panel de disponibilidad de personal. Entregable: HTML + CSS con grid, íconos médicos y badges de estado accesibles." },
  { sector: "Web", layout: "dashboard", nombre: "Social Pulse Manager", descripcion: "Analítica multired para community manager", prompt: "Diseñá un dashboard de gestión de redes sociales para un community manager, estilo vibrante con dark UI (#12101C) y degradados de marca por red (rosa Instagram, azul cielo, negro X). KPIs de seguidores, alcance, engagement y menciones. Gráfico de crecimiento comparado por plataforma, heatmap de mejores horas para publicar, cola de posts programados en calendario compacto, y top posts con miniaturas. Entregable: HTML + CSS con grid, chips por red social y micro-visualizaciones." },
  { sector: "Web", layout: "dashboard", nombre: "E-commerce Bazar Admin", descripcion: "Panel de ventas y órdenes de tienda", prompt: "Diseñá un dashboard admin de e-commerce para una tienda de moda, estético y editorial con fondo gris muy claro (#F4F4F5), negro carbón y acento fucsia (#EC4899). Header con ingresos del día, órdenes, ticket promedio y stock bajo. Gráfico de ventas por hora, barras de productos más vendidos con thumbnails, mapa de calor de regiones, y tabla de últimas órdenes con estado de envío. Entregable: HTML + CSS con grid, tabla estilizada y badges de estado." },
  { sector: "Web", layout: "dashboard", nombre: "Logística FlotaViva", descripcion: "Monitor de flota y entregas en tiempo real", prompt: "Diseñá un dashboard de logística y última milla, estilo control-room oscuro (#0A0E14) con acento ámbar (#F59E0B) y cian de rutas. Panel principal con mapa estilizado de rutas activas y pines de vehículos, KPIs de entregas a tiempo, en tránsito y demoradas. Lista lateral de conductores con progreso de ruta, gráfico de rendimiento por zona, y timeline de incidencias. Entregable: HTML + CSS con grid, mapa como SVG placeholder e indicadores de estado en vivo." },
  { sector: "Web", layout: "dashboard", nombre: "Soporte Helpdesk Aria", descripcion: "Cola de tickets y SLA de soporte", prompt: "Diseñá un dashboard de soporte al cliente / helpdesk, estilo sobrio y funcional con fondo claro (#FAFAFA), azul acero (#2563EB) y semáforo de SLA (verde/ámbar/rojo). Header con tickets abiertos, tiempo medio de respuesta, CSAT y SLA en riesgo. Cola de tickets priorizada con avatares y etiquetas, gráfico de volumen por canal, gauge de cumplimiento de SLA, y ranking de agentes. Entregable: HTML + CSS con grid, tabla densa y badges de prioridad." },
  { sector: "Web", layout: "dashboard", nombre: "IoT Casa Domótica", descripcion: "Panel de hogar inteligente conectado", prompt: "Diseñá un dashboard de hogar inteligente (IoT), estilo glassmorphism con fondo degradado nocturno azul-morado y tarjetas translúcidas con blur. Tiles por habitación con temperatura, luces y consumo. Termostato circular central, gráfico de consumo energético del día, estado de dispositivos conectados con toggles, y alertas de seguridad. Entregable: HTML + CSS con grid, efecto glass mediante backdrop-filter y controles tipo switch." },
  { sector: "Web", layout: "dashboard", nombre: "Marketing Growth Cohete", descripcion: "Rendimiento de campañas multicanal", prompt: "Diseñá un dashboard de marketing de performance, estilo energético con fondo oscuro (#111827) y acentos naranja (#FB923C) y verde lima. Header con ROAS, CTR, CPA y presupuesto gastado. Gráfico de conversiones por canal (Meta, Google, TikTok), funnel de adquisición vertical, tabla de campañas activas con métricas y semáforo de rendimiento, y anillo de distribución de presupuesto. Entregable: HTML + CSS con grid, funnel en CSS y chips de canal." },
  { sector: "Web", layout: "dashboard", nombre: "Product Analytics Prisma", descripcion: "Métricas de producto y retención", prompt: "Diseñá un dashboard de analítica de producto tipo Mixpanel/Amplitude, estilo tech limpio con fondo blanco, gris pizarra y acento púrpura (#8B5CF6). KPIs de DAU/MAU, stickiness, retención D7 y eventos clave. Curva de retención por cohorte (matriz de colores), gráfico de embudo de activación, gráfico de eventos en el tiempo y segmentos de usuarios. Entregable: HTML + CSS con grid, matriz de cohortes con celdas coloreadas por intensidad." },
  { sector: "Web", layout: "dashboard", nombre: "CRM Inmobiliario Domus", descripcion: "Gestión de propiedades y leads", prompt: "Diseñá un dashboard CRM inmobiliario, estilo elegante con fondo marfil (#FAF8F5), verde bosque (#166534) y dorado suave. Header con propiedades activas, leads nuevos, visitas agendadas y cierres del mes. Galería de propiedades destacadas con foto placeholder y precio, embudo de leads por etapa, mapa de zonas con demanda, y agenda de visitas del día. Entregable: HTML + CSS con grid, tarjetas de propiedad con imagen y layout editorial." },
  { sector: "Web", layout: "dashboard", nombre: "Fintech Neobanco Cifra", descripcion: "Panel de banca digital y transacciones", prompt: "Diseñá un dashboard de neobanco / fintech, estilo premium con fondo negro azabache (#08090D), tarjetas oscuras y acento verde neón (#00E599) tipo tarjeta digital. Balance de cuenta con degradado, KPIs de ingresos, egresos y ahorro. Gráfico de flujo de caja entrada/salida, tarjeta virtual visual, lista de transacciones con categorías e íconos, y desglose de gastos en donut. Entregable: HTML + CSS con grid, estética glossy y microdetalles de tarjeta." },
  { sector: "Web", layout: "dashboard", nombre: "Salud Wearable Latido", descripcion: "Panel de fitness y biometría", prompt: "Diseñá un dashboard de salud y fitness conectado a wearables, estilo deportivo con dark UI (#0D1117) y anillos de actividad estilo Apple (rojo, verde, azul). Anillos de progreso diario centrales, KPIs de pasos, calorías, frecuencia cardíaca y sueño. Gráfico de ritmo cardíaco del día, barras de actividad semanal, fases de sueño en área apilada, y racha de entrenamientos. Entregable: HTML + CSS con grid, anillos concéntricos en SVG y microtipografía." },
  { sector: "Web", layout: "dashboard", nombre: "Streaming Media Onda", descripcion: "Analítica de audiencia de video", prompt: "Diseñá un dashboard de analítica para una plataforma de streaming de video, estilo cine oscuro (#101014) con acento rojo (#EF4444) y púrpura. Header con horas vistas, suscriptores, retención media y contenido top. Gráfico de reproducciones por hora, curva de retención de un episodio, ranking de títulos con thumbnails, y mapa mundial de audiencia. Entregable: HTML + CSS con grid, tarjetas de contenido con carátula placeholder y gráficos de línea." },
  { sector: "Web", layout: "dashboard", nombre: "Marketplace Multivendedor Ágora", descripcion: "Admin de vendedores y comisiones", prompt: "Diseñá un dashboard admin de marketplace multivendedor, estilo neutro profesional con fondo #F5F6F8, azul marino (#1E3A8A) y acento teal. Header con GMV, comisiones, vendedores activos y órdenes. Ranking de vendedores top con rating, gráfico de GMV por categoría, tabla de payouts pendientes, y gráfico de crecimiento de vendedores. Entregable: HTML + CSS con grid, tabla financiera densa y badges de estado de vendedor." },
  { sector: "Web", layout: "dashboard", nombre: "Almacén Inventario Nexo", descripcion: "Control de stock y warehouse", prompt: "Diseñá un dashboard de gestión de inventario / warehouse, estilo industrial claro con fondo #EEF1F4, gris grafito y acento naranja seguridad (#EA580C). KPIs de SKUs, stock total, en tránsito y bajo mínimo. Mapa de ocupación de estanterías tipo grilla, gráfico de rotación de inventario, alertas de reposición, y tabla de movimientos entrada/salida. Entregable: HTML + CSS con grid, visual de bins/estanterías en CSS y semáforos de stock." },
  { sector: "Web", layout: "dashboard", nombre: "Call Center Voz Eco", descripcion: "Monitor de contact center en vivo", prompt: "Diseñá un dashboard de contact center / call center, estilo control operativo oscuro (#0F1420) con acento verde (#22C55E) y ámbar de espera. Header con llamadas activas, en cola, tiempo medio de atención y nivel de servicio. Gauge grande de nivel de servicio, gráfico de volumen de llamadas por hora, lista de agentes con estado (en llamada, disponible, pausa), y distribución de motivos de contacto. Entregable: HTML + CSS con grid, gauge en SVG e indicadores de agente en tiempo real." },
  { sector: "Web", layout: "dashboard", nombre: "IoT Industrial Forja", descripcion: "Monitor de planta y sensores", prompt: "Diseñá un dashboard de IoT industrial / monitoreo de planta, estilo SCADA moderno oscuro (#0A0F16) con acento cian (#06B6D4) y rojo de alarma. Header con OEE, disponibilidad, rendimiento y calidad. Diagrama esquemático de línea de producción con nodos de máquina, gráficos de telemetría (temperatura, vibración, presión) en tiempo real, lista de alarmas activas, y gauges de sensores. Entregable: HTML + CSS con grid, esquema de planta en SVG y sparklines de sensor." },
  { sector: "Web", layout: "dashboard", nombre: "SEO Ranker Cima", descripcion: "Panel de posicionamiento y tráfico orgánico", prompt: "Diseñá un dashboard de SEO, estilo data-driven claro con fondo blanco, verde esmeralda (#059669) y azul. Header con tráfico orgánico, keywords en top 10, autoridad de dominio y backlinks. Gráfico de evolución de posiciones, tabla de keywords con variación de ranking (flechas arriba/abajo), distribución de tráfico por landing, y barras de salud técnica del sitio. Entregable: HTML + CSS con grid, tabla con indicadores de tendencia y micrográficos." },
  { sector: "Web", layout: "dashboard", nombre: "Trading Desk Bolsa", descripcion: "Panel financiero de mercados y cartera", prompt: "Diseñá un dashboard de trading / mercados financieros, estilo terminal profesional negro (#0B0B0F) con verde alza (#22C55E) y rojo baja (#EF4444), tipografía monoespaciada para cifras. Header con valor de cartera, P&L diario y exposición. Gráfico de velas de un activo, watchlist con precios y variación en vivo, distribución de portafolio en donut, y libro de órdenes compacto. Entregable: HTML + CSS con grid, candlestick en SVG y tabla de cotizaciones densa." },
  { sector: "Web", layout: "dashboard", nombre: "LMS Educativo Saber", descripcion: "Admin de cursos y estudiantes", prompt: "Diseñá un dashboard de administración de una plataforma educativa / LMS, estilo amigable con fondo #F6F5FF, violeta suave (#6D5AE6) y amarillo cálido. Header con estudiantes activos, cursos, tasa de finalización y horas de estudio. Gráfico de progreso por curso, ranking de cursos populares con miniaturas, embudo de inscripción a certificación, y lista de estudiantes en riesgo de abandono. Entregable: HTML + CSS con grid, barras de progreso y tarjetas de curso." },
  { sector: "Web", layout: "dashboard", nombre: "Smart Grid Energía Voltia", descripcion: "Monitor de consumo y generación energética", prompt: "Diseñá un dashboard de gestión energética / smart grid, estilo sostenible oscuro (#0C1512) con verde energía (#34D399) y amarillo solar. Header con generación total, consumo, autoconsumo y CO2 evitado. Gráfico de flujo generación vs consumo del día, medidor circular de mix renovable, distribución por fuente (solar, eólica, red), y tabla de subestaciones con carga. Entregable: HTML + CSS con grid, gráfico de área apilada y gauge de mix energético." },
  { sector: "Web", layout: "dashboard", nombre: "Clínica Bienestar Mente", descripcion: "Panel de gestión de salud mental", prompt: "Diseñá un dashboard para una clínica de salud mental / psicología, estilo sereno y cálido con fondo #F5F3EF, verde salvia (#7C9A82) y terracota suave. Header con pacientes activos, sesiones de la semana, adherencia y bienestar promedio. Agenda de sesiones del día, gráfico de evolución de ánimo de pacientes, distribución por tipo de terapia, y lista de seguimientos pendientes. Entregable: HTML + CSS con grid, tipografía humanista y visuales de baja saturación." },
  { sector: "Web", layout: "dashboard", nombre: "Influencer Insights Brillo", descripcion: "Analítica de creador de contenido", prompt: "Diseñá un dashboard de analítica para un influencer / creador, estilo pop con dark UI (#14101F) y degradado magenta-naranja vibrante. Header con seguidores, tasa de engagement, alcance e ingresos por marca. Gráfico de crecimiento de audiencia, demografía de audiencia (edad y género en barras), reels/posts top con miniaturas y métricas, y calendario de colaboraciones. Entregable: HTML + CSS con grid, tarjetas de contenido con thumbnail y gráficos vibrantes." },
  { sector: "Web", layout: "dashboard", nombre: "Restaurante POS Sabor", descripcion: "Panel de ventas y operación gastronómica", prompt: "Diseñá un dashboard de administración de restaurante / POS, estilo apetitoso con fondo #FFF9F2, rojo tomate (#DC2626) y verde albahaca. Header con ventas del día, tickets, ticket promedio y mesas ocupadas. Mapa de salón con estado de mesas, ranking de platos más vendidos, gráfico de ventas por franja horaria, y estado de pedidos en cocina. Entregable: HTML + CSS con grid, plano de mesas en CSS y tarjetas de platos." },
  { sector: "Web", layout: "dashboard", nombre: "People Analytics RRHH Talento", descripcion: "Panel de recursos humanos y plantilla", prompt: "Diseñá un dashboard de RRHH / people analytics, estilo corporativo humano con fondo #F4F6F9, azul confianza (#2563EB) y acento coral. Header con headcount, rotación, tiempo de contratación y eNPS. Gráfico de plantilla por departamento, embudo de reclutamiento, distribución de diversidad, y ranking de razones de baja. Entregable: HTML + CSS con grid, organigrama compacto y barras horizontales." },
  { sector: "Web", layout: "dashboard", nombre: "Ciberseguridad SOC Escudo", descripcion: "Centro de operaciones de seguridad", prompt: "Diseñá un dashboard de ciberseguridad / SOC, estilo control-room oscuro (#080B12) con verde matriz (#39FF88) y rojo crítico. Header con amenazas activas, incidentes, endpoints protegidos y nivel de riesgo. Mapa mundial de ataques con líneas de origen, feed de eventos de seguridad en vivo, gráfico de amenazas por severidad, y gauge de postura de seguridad. Entregable: HTML + CSS con grid, mapa de ataques en SVG y log de eventos con timestamps." },
  { sector: "App", layout: "mobile", nombre: "Feed Social Aurora", descripcion: "Feed vertical estilo Instagram con historias", prompt: "Diseña una pantalla de feed social para móvil (390x844) tipo Instagram con paleta violeta-magenta degradado y fondo oscuro casi negro (#0D0D14). Barra superior de historias circulares con anillo degradado, tarjetas de post con foto full-width, iconos de like/comentario/compartir en outline, y barra de navegación inferior con 5 iconos. Tipografía sans geométrica. Entregable: HTML+CSS autocontenido, mobile-first." },
  { sector: "App", layout: "chat", nombre: "Chat Mensajería Neo", descripcion: "Conversación 1 a 1 con burbujas", prompt: "Diseña una pantalla de chat 1 a 1 para móvil estilo WhatsApp/Telegram, paleta verde teal (#128C7E) sobre fondo crema con patrón sutil. Burbujas de mensaje diferenciadas (enviado verde a la derecha, recibido blanco a la izquierda), timestamps, ticks de leído azules, header con avatar y estado 'en línea', barra inferior con input, clip y micrófono. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Banca Saldo Zafiro", descripcion: "Dashboard bancario con tarjeta virtual", prompt: "Diseña el home de una app de banca digital para móvil, paleta azul zafiro y blanco con acentos verde lima, estilo fintech limpio (Revolut/N26). Tarjeta de crédito virtual en glassmorphism arriba, saldo grande, botones rápidos de enviar/recibir/recargar en fila, lista de transacciones recientes con iconos por categoría y montos coloreados. Entregable: HTML+CSS autocontenido mobile-first." },
  { sector: "App", layout: "mobile", nombre: "Fitness Ritmo Neón", descripcion: "Resumen de entrenamiento con anillos", prompt: "Diseña la pantalla de resumen diario de una app de fitness para móvil, fondo oscuro grafito con acentos verde neón y coral, estilo Apple Fitness. Anillos de actividad concéntricos animados en el centro, tarjetas de métricas (pasos, calorías, frecuencia cardíaca) con mini-gráficos, botón CTA 'Iniciar entrenamiento'. Tipografía condensada bold. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "list", nombre: "Delivery Menú Mango", descripcion: "Listado de platos de restaurante", prompt: "Diseña una pantalla de listado de platos de una app de delivery de comida para móvil, paleta naranja mango y blanco cálido, estilo Rappi/UberEats. Header con foto del restaurante y rating, chips de categorías scrollables, lista de platos con foto miniatura a la izquierda, nombre, descripción, precio y botón + para agregar. Barra inferior con carrito y total. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "mobile", nombre: "Música Reproductor Vinilo", descripcion: "Pantalla now playing inmersiva", prompt: "Diseña la pantalla 'now playing' de una app de música para móvil, fondo con degradado extraído del arte del álbum (púrpura a durazno), estilo Spotify premium. Carátula grande con sombra, título de canción y artista, barra de progreso con scrubber, controles de reproducción centrados, botones de shuffle/repeat/corazón, y ecualizador visual sutil abajo. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Meditación Calma Salvia", descripcion: "Home de mindfulness sereno", prompt: "Diseña el home de una app de meditación para móvil, paleta salvia verde suave, beige y lavanda con degradados orgánicos, estilo Calm/Headspace. Saludo personalizado, tarjeta destacada 'Meditación del día' con ilustración de montañas, cuadrícula de categorías (Sueño, Ansiedad, Foco) con iconos redondeados, reproductor de sonido ambiente minimizado abajo. Tipografía serif suave. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "list", nombre: "Tareas Foco Índigo", descripcion: "Lista de pendientes por proyecto", prompt: "Diseña una pantalla de lista de tareas para móvil, paleta índigo y blanco con acentos ámbar, estilo Todoist/Things minimalista. Encabezado 'Hoy' con contador, tareas agrupadas por sección con checkbox circular, etiquetas de proyecto en color, indicador de prioridad con banderita, fecha de vencimiento, y botón flotante + para añadir. Swipe hints visibles. Entregable: HTML+CSS autocontenido mobile-first." },
  { sector: "App", layout: "mobile", nombre: "Viajes Destino Coral", descripcion: "Detalle de destino turístico", prompt: "Diseña la pantalla de detalle de un destino de viaje para móvil, paleta turquesa océano y coral cálido, estilo Airbnb/Hopper. Foto hero full-bleed de playa con overlay degradado, título del destino y rating con estrellas, chips de clima y precio, sección de galería horizontal, descripción y botón CTA 'Reservar vuelo'. Barra de navegación translúcida. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "E-commerce Producto Ónix", descripcion: "Ficha de producto de moda", prompt: "Diseña la ficha de producto de una app de e-commerce de moda para móvil, paleta negro ónix, blanco y un acento mostaza, estilo premium tipo Zara/SSENSE. Foto de producto grande con carrusel de puntos, nombre, precio, selector de talla en píldoras, selector de color en círculos, sección de reseñas resumida, y barra inferior fija con 'Añadir al carrito' y corazón de favorito. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "list", nombre: "Citas Descubrir Rubí", descripcion: "Lista de matches y likes", prompt: "Diseña una pantalla de 'Me gusta' de una app de citas para móvil, paleta rubí rosado y púrpura con degradados cálidos, estilo Tinder/Bumble. Cuadrícula de dos columnas con fotos de perfiles, nombre y edad sobre overlay degradado, badge de 'Nuevo match', filtro superior de distancia, y barra inferior con iconos de descubrir/likes/chats/perfil. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "list", nombre: "Noticias Titulares Pizarra", descripcion: "Feed de noticias editorial", prompt: "Diseña un feed de noticias para móvil, paleta pizarra oscuro, blanco y rojo periodístico de acento, estilo NYT/Apple News editorial. Historia destacada con foto grande y titular serif bold, seguida de lista de artículos con miniatura a la derecha, categoría en mayúsculas, tiempo de lectura y hora. Barra superior con secciones scrollables. Tipografía serif para titulares, sans para cuerpo. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "chat", nombre: "Soporte Bot Ártico", descripcion: "Chat con asistente de ayuda", prompt: "Diseña una pantalla de chat de soporte con asistente virtual para móvil, paleta azul ártico y blanco limpio, estilo Intercom. Burbujas del bot con avatar circular y botones de respuesta rápida (quick replies) en píldoras, burbujas del usuario en azul a la derecha, indicador 'escribiendo...' con tres puntos, header con nombre del asistente y estado, input inferior con adjuntar. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Feed Video Vertical Cobalto", descripcion: "Pantalla estilo reels/TikTok", prompt: "Diseña una pantalla de video vertical full-screen estilo TikTok/Reels para móvil, fondo del video con overlay oscuro inferior, acentos blanco y cobalto. Barra lateral derecha de acciones (avatar seguir, corazón con conteo, comentarios, compartir, disco giratorio de música), texto de caption y hashtags abajo a la izquierda, barra superior con pestañas 'Siguiendo/Para ti'. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "mobile", nombre: "Banca Transferencia Menta", descripcion: "Flujo de envío de dinero", prompt: "Diseña una pantalla de transferencia de dinero de una app bancaria para móvil, paleta verde menta y azul marino, estilo fintech confiable. Campo de monto grande centrado con teclado numérico personalizado abajo, avatar y nombre del destinatario arriba, selector de cuenta origen, campo de concepto opcional, y botón CTA 'Enviar' prominente. Micro-copy de comisión cero. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "list", nombre: "Fitness Rutinas Grafito", descripcion: "Biblioteca de entrenamientos", prompt: "Diseña una lista de rutinas de entrenamiento para móvil, paleta grafito oscuro con acento amarillo eléctrico, estilo Nike Training Club. Tarjetas de rutina apiladas con foto de fondo, nombre del entrenamiento, duración, nivel de dificultad con barras, e icono de músculo trabajado. Filtros superiores en chips (Fuerza, Cardio, Yoga), barra de búsqueda. Entregable: HTML+CSS autocontenido mobile-first." },
  { sector: "App", layout: "mobile", nombre: "Delivery Seguimiento Fuego", descripcion: "Tracking de pedido en curso", prompt: "Diseña la pantalla de seguimiento de pedido de una app de delivery para móvil, paleta rojo fuego y blanco con mapa de fondo. Mapa con ruta del repartidor y pin animado en la parte superior (60% de pantalla), tarjeta inferior deslizable con estado 'En camino', tiempo estimado grande, barra de progreso por etapas (Preparando/Recogido/En camino/Entregado), datos del repartidor con foto y botón de llamar. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "list", nombre: "Música Playlist Esmeralda", descripcion: "Detalle de lista de reproducción", prompt: "Diseña la pantalla de detalle de playlist de una app de música para móvil, paleta verde esmeralda profundo con degradado a negro, estilo Spotify. Portada de playlist grande arriba con título, autor y duración total, botones de reproducir (verde grande) y shuffle, lista de canciones con número, título, artista, duración y menú de tres puntos. Header colapsable. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Meditación Sesión Nocturna", descripcion: "Reproductor de sonido para dormir", prompt: "Diseña un reproductor de sesión de sueño de una app de meditación para móvil, paleta azul noche profundo con estrellas sutiles y acento dorado tenue, estilo Calm modo noche. Ilustración de paisaje nocturno con luna, título de la sesión 'Lluvia suave', temporizador circular de progreso, controles de play/pausa y rewind 15s, slider de volumen y selector de tiempo (15/30/60 min). Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "mobile", nombre: "Tareas Calendario Perla", descripcion: "Vista de agenda semanal", prompt: "Diseña una vista de agenda semanal de una app de productividad para móvil, paleta blanco perla, gris suave y acento coral, estilo Fantastical minimalista. Selector de días de la semana horizontal arriba con el día activo resaltado, timeline vertical con horas y bloques de eventos coloreados por categoría, indicador de 'ahora' con línea roja, botón flotante + para nuevo evento. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Viajes Itinerario Arena", descripcion: "Plan de viaje día por día", prompt: "Diseña una pantalla de itinerario de viaje día por día para móvil, paleta arena beige, terracota y verde oliva, estilo Wanderlog/TripIt cálido. Selector de días en pestañas, timeline vertical con paradas (hotel, actividad, restaurante) cada una con icono, hora, nombre y miniatura, líneas conectoras entre paradas, mapa colapsado arriba. Entregable: HTML+CSS autocontenido mobile-first." },
  { sector: "App", layout: "mobile", nombre: "E-commerce Carrito Lino", descripcion: "Resumen de carrito y checkout", prompt: "Diseña la pantalla de carrito de compras de una app de e-commerce para móvil, paleta blanco lino, negro y acento verde salvia, estilo minimalista escandinavo. Lista de productos con miniatura, nombre, variante, control de cantidad +/- y precio, sección de resumen con subtotal/envío/total, campo de código promocional, y botón fijo inferior 'Ir a pagar' con total. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "chat", nombre: "Citas Conversación Durazno", descripcion: "Chat entre match con perfil", prompt: "Diseña una pantalla de chat entre un match de app de citas para móvil, paleta durazno, rosa y crema con degradados suaves, estilo Hinge/Bumble cálido. Header con foto del match circular, nombre y botón de ver perfil, burbujas redondeadas (usuario en rosa, match en gris claro), sugerencias de rompehielos en chips arriba del input, input con emoji y GIF. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "list", nombre: "Noticias Guardados Sepia", descripcion: "Artículos guardados para leer", prompt: "Diseña una pantalla de artículos guardados de una app de noticias para móvil, paleta sepia cálido, crema y marrón café, estilo Pocket/Instapaper para lectura. Lista de artículos guardados con miniatura cuadrada, titular serif, fuente, tiempo de lectura estimado y barra de progreso de lectura, filtro superior (Todos/No leídos/Favoritos), gesto de swipe para archivar. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Banca Presupuesto Turquesa", descripcion: "Análisis de gastos por categoría", prompt: "Diseña una pantalla de análisis de presupuesto de una app bancaria para móvil, paleta turquesa, blanco y acentos multicolor por categoría, estilo Monarch/YNAB. Gráfico de dona con gasto total en el centro, leyenda de categorías con porcentaje y monto, barra de progreso de presupuesto mensual, lista de categorías (Comida, Transporte, Ocio) con icono, barra de progreso y monto restante. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "chat", nombre: "Grupo Chat Coral Vivo", descripcion: "Conversación grupal con reacciones", prompt: "Diseña una pantalla de chat grupal para móvil, paleta coral vivo y blanco con acentos azul, estilo Messenger/Slack móvil. Burbujas con nombre y mini-avatar del remitente para mensajes de otros, reacciones emoji flotantes bajo burbujas, mensaje con imagen adjunta en grid, indicador de varios escribiendo, header con avatares apilados del grupo y nombre. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Fitness Progreso Lima", descripcion: "Gráficos de evolución corporal", prompt: "Diseña una pantalla de progreso de fitness para móvil, paleta oscuro carbón con acento verde lima y magenta, estilo Whoop/Gymshark. Selector de métrica en pestañas (Peso, Fuerza, Medidas), gráfico de líneas grande con área degradada, tarjetas de récords personales, comparativa antes/después con fotos, resumen de racha semanal con llamas. Tipografía numérica bold. Entregable: HTML+CSS autocontenido mobile-first." },
  { sector: "App", layout: "list", nombre: "Delivery Restaurantes Sésamo", descripcion: "Descubrir restaurantes cercanos", prompt: "Diseña la pantalla de descubrimiento de restaurantes de una app de delivery para móvil, paleta blanco, negro sésamo y acento amarillo, estilo DoorDash. Barra de búsqueda con ubicación arriba, carrusel de categorías con iconos circulares (Pizza, Sushi, Burgers), lista de restaurantes con foto de portada, logo, nombre, rating, tiempo de entrega y costo de envío, badge de promoción. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "Viajes Vuelo Boleto Cielo", descripcion: "Boarding pass digital", prompt: "Diseña un boarding pass digital de una app de viajes para móvil, paleta azul cielo y blanco con acento naranja, estilo aerolínea moderna. Tarjeta de boleto con recorte tipo ticket (borde festoneado), origen-destino con icono de avión y línea de ruta, hora de salida/llegada grandes, puerta, asiento y grupo de abordaje, código QR grande abajo, degradado de header con nombre del pasajero. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "list", nombre: "Música Podcasts Ámbar", descripcion: "Lista de episodios de podcast", prompt: "Diseña una pantalla de detalle de podcast con episodios para móvil, paleta ámbar cálido, marrón oscuro y crema, estilo Overcast/Pocket Casts. Portada del podcast con nombre, autor y botón de suscribir, lista de episodios con fecha, título, descripción corta, duración, botón de play circular y progreso de escucha, controles de descarga. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "mobile", nombre: "E-commerce Home Arándano", descripcion: "Portada de tienda con ofertas", prompt: "Diseña el home de una app de e-commerce general para móvil, paleta arándano púrpura y blanco con acentos naranja de oferta, estilo Amazon/Mercado Libre moderno. Barra de búsqueda arriba, banner carrusel de promociones, cuadrícula de categorías con iconos, sección 'Ofertas relámpago' con temporizador y productos horizontales, cuadrícula de productos recomendados con precio tachado y descuento. Entregable: HTML+CSS autocontenido mobile." },
  { sector: "App", layout: "mobile", nombre: "Meditación Estadísticas Jade", descripcion: "Racha y progreso de práctica", prompt: "Diseña una pantalla de estadísticas de meditación para móvil, paleta jade verde suave, blanco y lavanda, estilo Headspace analítica calmada. Número de racha grande con icono de brote, calendario mensual con días meditados resaltados en círculos, tarjetas de minutos totales y sesiones completadas, gráfico de barras semanal de minutos, mensaje motivacional. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "App", layout: "list", nombre: "Tareas Bandeja Grafeno", descripcion: "Inbox de notificaciones y pendientes", prompt: "Diseña una bandeja de entrada de notificaciones y pendientes de una app de productividad para móvil, paleta gris grafeno oscuro con acentos azul eléctrico, estilo Superhuman/Linear móvil. Lista de items con icono de tipo (tarea, mención, recordatorio), título, snippet, tiempo relativo, punto de no leído, agrupados por 'Hoy' y 'Anterior', barra superior con filtros en segmentos. Entregable: HTML+CSS autocontenido mobile-first." },
  { sector: "App", layout: "mobile", nombre: "Noticias Detalle Marfil", descripcion: "Vista de lectura de artículo", prompt: "Diseña la vista de lectura de un artículo de noticias para móvil, paleta marfil crema, negro y acento azul enlace, estilo Medium/NYT lectura enfocada. Imagen de cabecera con crédito, titular serif grande, línea de autor con avatar y fecha, barra de progreso de lectura fija arriba, cuerpo con tipografía serif legible, cita destacada (pull quote), y barra inferior flotante con guardar/compartir/tamaño de fuente. Entregable: HTML+CSS autocontenido responsive." },
  { sector: "Componentes", layout: "cards3", nombre: "Precios SaaS Neón", descripcion: "Tres planes con toggle mensual/anual", prompt: "Diseña un componente de tabla de precios de 3 columnas para una plataforma SaaS de analítica, estilo dark tech con fondo grafito #0D1117 y acentos neón cian #22D3EE y violeta #A78BFA. Plan central destacado con badge 'Más popular', borde glow y elevación. Incluye toggle mensual/anual con ahorro del 20%, lista de features con checks, y CTA por plan. Entregable: HTML + CSS con variables de color y hover states." },
  { sector: "Componentes", layout: "form", nombre: "Login Fintech", descripcion: "Acceso con email y biometría", prompt: "Diseña un formulario de login para una app fintech de banca digital, estética limpia y confiable con blanco #FFFFFF, azul marino #1E3A5F y verde menta #34D399. Campos email y contraseña con validación inline, toggle de mostrar contraseña, botón 'Iniciar sesión con Face ID', recordarme y enlace de recuperación. Entregable: HTML + CSS responsive con estados de foco y error." },
  { sector: "Componentes", layout: "split", nombre: "Registro Split Editorial", descripcion: "Alta con panel visual lateral", prompt: "Diseña un componente de registro con layout dividido para una plataforma de cursos online, estilo editorial cálido con crema #FAF3E0, terracota #E07856 y marrón oscuro #3D2C29. Panel izquierdo con imagen de estudiantes y testimonio, panel derecho con formulario de nombre, email, contraseña y checkbox de términos. Entregable: HTML + CSS con tipografía serif para títulos." },
  { sector: "Componentes", layout: "grid", nombre: "Cards Producto E-commerce", descripcion: "Grilla de tarjetas de producto", prompt: "Diseña una grilla de tarjetas de producto para un e-commerce de sneakers streetwear, estética bold urbana con negro #111111, amarillo eléctrico #FDE047 y gris claro #F3F4F6. Cada card con imagen, badge de descuento, nombre, precio tachado, rating de estrellas y botón 'Agregar al carrito' en hover. Entregable: HTML + CSS grid responsive de 4 columnas con animaciones sutiles." },
  { sector: "Componentes", layout: "split", nombre: "Navbar SaaS Mega", descripcion: "Barra con mega menú desplegable", prompt: "Diseña un componente de navbar con mega menú para una suite de productividad B2B, estilo corporativo moderno con blanco #FFFFFF, índigo #4F46E5 y slate #64748B. Logo a la izquierda, links con dropdown de productos en columnas con iconos y descripciones, buscador y botones 'Ingresar' y 'Prueba gratis'. Entregable: HTML + CSS con mega menú posicionado y sticky on scroll." },
  { sector: "Componentes", layout: "grid", nombre: "Footer Multicolumna Tech", descripcion: "Pie de página con newsletter", prompt: "Diseña un componente de footer de 4 columnas para una startup de infraestructura cloud, estética dark profesional con fondo #0F172A, texto gris #94A3B8 y acento verde lima #84CC16. Columnas de Producto, Empresa, Recursos y Legal, más bloque de suscripción a newsletter con input y botón, íconos sociales y selector de idioma. Entregable: HTML + CSS grid responsive." },
  { sector: "Componentes", layout: "form", nombre: "Modal Confirmación Borrado", descripcion: "Diálogo destructivo con overlay", prompt: "Diseña un componente modal de confirmación de acción destructiva para un panel de administración, estilo minimalista con blanco #FFFFFF, rojo alerta #EF4444 y gris neutro #6B7280. Overlay oscuro semitransparente, ícono de advertencia, título 'Eliminar proyecto', texto explicativo, campo para escribir el nombre a confirmar y botones 'Cancelar' y 'Eliminar'. Entregable: HTML + CSS con backdrop blur y animación de entrada." },
  { sector: "Componentes", layout: "grid", nombre: "Tabla de Datos Admin", descripcion: "Datatable con filtros y paginación", prompt: "Diseña un componente de tabla de datos para un dashboard de gestión de pedidos logísticos, estética funcional clara con blanco #FFFFFF, azul #2563EB y verde/rojo de estado. Encabezados ordenables, filas con checkbox de selección, badges de estado (Entregado, En tránsito, Cancelado), buscador, filtros por columna, acciones por fila y paginación inferior. Entregable: HTML + CSS con sticky header y hover de fila." },
  { sector: "Componentes", layout: "grid", nombre: "Calendario Reservas", descripcion: "Vista mensual con eventos", prompt: "Diseña un componente de calendario de reservas para una app de coworking, estilo suave y moderno con blanco roto #FAFAFA, morado #7C3AED y coral #FB7185. Vista de mes con celdas de día, indicadores de eventos por color, día actual resaltado, navegación entre meses y mini leyenda de tipos de reserva. Entregable: HTML + CSS grid de 7 columnas responsive." },
  { sector: "Componentes", layout: "split", nombre: "Timeline Historia Marca", descripcion: "Línea de tiempo vertical alterna", prompt: "Diseña un componente de timeline vertical alternado para la sección 'Nuestra historia' de una bodega de vino artesanal, estética elegante con fondo borgoña oscuro #4A1420, dorado #D4AF37 y crema #F5EBDD. Cada hito con año, título, descripción e imagen circular, conectados por línea central con nodos. Entregable: HTML + CSS con animación de aparición al hacer scroll." },
  { sector: "Componentes", layout: "cards3", nombre: "Testimonios Trío", descripcion: "Tres reseñas con avatar y rating", prompt: "Diseña un componente de testimonios de 3 tarjetas para una agencia de marketing digital, estilo fresco y confiable con blanco #FFFFFF, azul cielo #0EA5E9 y amarillo suave #FCD34D. Cada card con comillas grandes, texto de reseña, avatar, nombre, cargo, logo de empresa y 5 estrellas. Entregable: HTML + CSS con tarjeta central elevada." },
  { sector: "Componentes", layout: "grid", nombre: "FAQ Acordeón", descripcion: "Preguntas frecuentes expandibles", prompt: "Diseña un componente de FAQ tipo acordeón en dos columnas para una plataforma de seguros de salud, estética limpia y accesible con blanco #FFFFFF, teal #0D9488 y gris carbón #374151. Cada item con pregunta, ícono +/− que rota, y respuesta desplegable con transición de altura. Incluye buscador de preguntas arriba. Entregable: HTML + CSS con estados abierto/cerrado accesibles." },
  { sector: "Componentes", layout: "split", nombre: "Hero Features Producto", descripcion: "Encabezado con demo y beneficios", prompt: "Diseña un componente hero de features con layout dividido para una app de gestión de finanzas personales, estilo vibrante amigable con fondo degradado violeta a fucsia #7C3AED a #EC4899 y blanco. Lado izquierdo con titular potente, subtítulo, dos CTA y prueba social; lado derecho con mockup de la app flotando y tarjetas de features glassmorphism. Entregable: HTML + CSS con degradado y sombras suaves." },
  { sector: "Componentes", layout: "form", nombre: "Checkout Un Paso", descripcion: "Pago con resumen de orden", prompt: "Diseña un componente de checkout de una sola página para una tienda de café de especialidad, estética cálida artesanal con crema #F3E9DC, verde oliva #556B2F y marrón espresso #4B2E2E. Columna izquierda con datos de envío y método de pago con tarjetas de opción; columna derecha con resumen de orden sticky, cupón y total. Entregable: HTML + CSS de dos columnas responsive." },
  { sector: "Componentes", layout: "cards3", nombre: "Precios Agencia", descripcion: "Planes de servicio para agencias", prompt: "Diseña una tabla de precios de 3 columnas para una agencia de diseño web freelance, estilo bold minimalista con negro #0A0A0A, blanco #FFFFFF y naranja #FF6B35 de acento. Planes Básico, Pro y Enterprise con precio grande, descripción de servicios, features diferenciadas y CTA. Plan Pro resaltado con fondo invertido negro. Entregable: HTML + CSS con contraste alto." },
  { sector: "Componentes", layout: "form", nombre: "Formulario Multipaso", descripcion: "Wizard con barra de progreso", prompt: "Diseña un componente de formulario multipaso (wizard) para el onboarding de una plataforma de reclutamiento, estética profesional moderna con blanco #FFFFFF, azul eléctrico #3B82F6 y verde éxito #22C55E. Barra de progreso con 4 pasos numerados, campos del paso actual, y botones 'Atrás' y 'Siguiente'. Entregable: HTML + CSS mostrando el paso 2 activo con validación." },
  { sector: "Componentes", layout: "grid", nombre: "Cards Blog Revista", descripcion: "Grilla de artículos con categoría", prompt: "Diseña una grilla de tarjetas de artículos de blog para una revista de viajes, estilo editorial fotográfico con blanco #FFFFFF, negro #1A1A1A y turquesa #06B6D4 de acento. Cada card con imagen de portada, etiqueta de categoría, título, extracto, autor con avatar y tiempo de lectura. Entregable: HTML + CSS grid de 3 columnas con card destacada ancha arriba." },
  { sector: "Componentes", layout: "split", nombre: "Login Ilustrado Gaming", descripcion: "Acceso con arte 3D lateral", prompt: "Diseña un componente de login con panel ilustrado para una plataforma gamer de torneos, estética neón gaming con fondo negro azulado #0B1026, magenta #F026A3 y cian #16E0FF. Panel izquierdo con arte 3D abstracto y glow; panel derecho con formulario, login social (Discord, Steam, Google) y toggle de idioma. Entregable: HTML + CSS con efectos glow y bordes neón." },
  { sector: "Componentes", layout: "grid", nombre: "Bento Features Grid", descripcion: "Rejilla bento de características", prompt: "Diseña un componente bento grid de features para una herramienta de IA para escritura, estilo moderno tech con fondo casi negro #121212, blanco y acento verde neón #A3E635. Celdas de distinto tamaño combinando texto, íconos, mini gráficos y una celda destacada grande con animación. Entregable: HTML + CSS grid asimétrico responsive con hover en cada celda." },
  { sector: "Componentes", layout: "form", nombre: "Registro Newsletter Inline", descripcion: "Suscripción con incentivo", prompt: "Diseña un componente de registro a newsletter inline para un blog de tecnología, estética limpia y directa con blanco #FFFFFF, azul índigo #6366F1 y gris claro #E5E7EB. Bloque centrado con ícono de sobre, titular, subtítulo con incentivo (ebook gratis), input de email horizontal con botón 'Suscribirme' y nota de privacidad. Entregable: HTML + CSS con estado de éxito tras enviar." },
  { sector: "Componentes", layout: "cards3", nombre: "Equipo Tres Miembros", descripcion: "Tarjetas de perfil del equipo", prompt: "Diseña un componente de tarjetas de equipo (3 personas) para la página 'Nosotros' de un estudio de arquitectura, estilo minimalista sofisticado con blanco #FAFAFA, negro #111111 y arena #C2B280. Cada card con foto en blanco y negro, nombre, rol, bio corta e íconos sociales que aparecen en hover. Entregable: HTML + CSS con transición de color en la foto al pasar el mouse." },
  { sector: "Componentes", layout: "grid", nombre: "Dashboard Stats Cards", descripcion: "KPIs con mini gráficos", prompt: "Diseña un componente de tarjetas de estadísticas (KPI) para un dashboard de e-commerce, estética clean data con blanco #FFFFFF, azul #2563EB, verde #10B981 y rojo #EF4444. Cuatro cards con título de métrica, valor grande, variación porcentual con flecha coloreada y sparkline. Entregable: HTML + CSS grid de 4 columnas responsive con SVG de mini gráfico." },
  { sector: "Componentes", layout: "split", nombre: "Modal Video Onboarding", descripcion: "Popup con video y pasos", prompt: "Diseña un componente modal de bienvenida con video para una app de meditación, estética calma con fondo lavanda #E9E4F0, morado suave #9F7AEA y blanco. Layout dividido: izquierda video/ilustración con botón play, derecha título 'Bienvenido', lista de 3 beneficios y CTA 'Empezar'. Overlay con blur. Entregable: HTML + CSS con animación de escala al abrir." },
  { sector: "Componentes", layout: "grid", nombre: "Tabla Comparativa Planes", descripcion: "Matriz de features por plan", prompt: "Diseña un componente de tabla comparativa de features por plan para un software de gestión de proyectos, estilo corporativo claro con blanco #FFFFFF, azul acero #1E40AF y gris #9CA3AF. Filas de características agrupadas por categoría, columnas por plan con checks/cruces, columna destacada resaltada y CTA en el encabezado de cada plan. Entregable: HTML + CSS con header sticky." },
  { sector: "Componentes", layout: "form", nombre: "Formulario Contacto Mapa", descripcion: "Contacto con datos y mapa", prompt: "Diseña un componente de formulario de contacto para un restaurante de alta cocina, estética elegante oscura con fondo carbón #1C1C1C, dorado #C9A227 y blanco marfil #F8F4E3. Lado izquierdo con formulario (nombre, email, fecha de reserva, mensaje) y lado derecho con datos de contacto, horarios y mapa estilizado. Entregable: HTML + CSS de dos columnas con inputs con borde dorado." },
  { sector: "Componentes", layout: "cards3", nombre: "Pasos Cómo Funciona", descripcion: "Tres pasos numerados con íconos", prompt: "Diseña un componente 'Cómo funciona' de 3 pasos para una app de delivery de supermercado, estilo fresco y alegre con blanco #FFFFFF, verde brócoli #16A34A y naranja mandarina #F97316. Cada card con número grande de fondo, ícono ilustrado, título de paso y descripción, conectadas por flechas punteadas. Entregable: HTML + CSS con conectores entre tarjetas." },
  { sector: "Componentes", layout: "split", nombre: "Hero App Móvil", descripcion: "Encabezado con mockup de teléfono", prompt: "Diseña un componente hero dividido para el landing de una app de fitness, estética energética con fondo negro #0A0A0A, verde lima #BEF264 y gris oscuro. Izquierda con titular grande, subtítulo, botones de App Store y Google Play y badges de rating; derecha con mockup de iPhone mostrando la app y elementos flotantes de métricas. Entregable: HTML + CSS responsive con mockup en CSS." },
  { sector: "Componentes", layout: "grid", nombre: "Galería Portfolio Masonry", descripcion: "Grilla masonry de proyectos", prompt: "Diseña un componente de galería tipo masonry para el portfolio de un fotógrafo profesional, estilo minimal oscuro con fondo negro #0D0D0D, blanco y acento ámbar #F59E0B. Imágenes de distinta altura con overlay al hover mostrando título del proyecto y categoría, más filtros de categoría arriba. Entregable: HTML + CSS con columnas masonry y overlay de hover." },
  { sector: "Componentes", layout: "form", nombre: "Checkout Pago Tarjeta", descripcion: "Formulario de datos de tarjeta", prompt: "Diseña un componente de formulario de pago con tarjeta para una plataforma de streaming de música, estética moderna oscura con fondo #181818, verde #1DB954 y gris. Vista previa de tarjeta que actualiza en vivo con número, nombre y vencimiento; campos con máscaras, íconos de marca de tarjeta y botón 'Pagar $9.99'. Entregable: HTML + CSS con card preview animada y validación." },
  { sector: "Componentes", layout: "cards3", nombre: "Precios Freemium App", descripcion: "Free, Plus y Pro con features", prompt: "Diseña una tabla de precios de 3 planes para una app de notas y productividad, estilo suave pastel con blanco #FFFFFF, azul lavanda #818CF8 y rosa suave #FBCFE8. Planes Free, Plus y Pro con ícono ilustrado por plan, precio, lista de features con checks coloreados y CTA. Plan Plus destacado con degradado sutil. Entregable: HTML + CSS con tarjetas redondeadas y sombras suaves." },
  { sector: "Componentes", layout: "grid", nombre: "Logos Confían en Nosotros", descripcion: "Grilla de logos de clientes", prompt: "Diseña un componente de grilla de logos de clientes para una consultora tecnológica B2B, estética sobria profesional con blanco #FFFFFF, gris antracita #374151 y azul corporativo #2563EB. Titular 'Empresas que confían en nosotros', grilla de 6 a 8 logos en escala de grises que pasan a color en hover y una métrica destacada abajo. Entregable: HTML + CSS grid responsive con transición de opacidad." },
  { sector: "Componentes", layout: "split", nombre: "Timeline Proceso Horizontal", descripcion: "Etapas de proyecto en horizontal", prompt: "Diseña un componente de timeline horizontal de proceso para una agencia de branding, estilo moderno con fondo blanco #FFFFFF, negro #111827 y coral vibrante #FF5A5F. Cuatro etapas (Descubrimiento, Estrategia, Diseño, Lanzamiento) con nodos sobre una línea, número, título y descripción, etapa activa resaltada. Entregable: HTML + CSS con línea de progreso y responsive a vertical en móvil." },
  { sector: "Componentes", layout: "form", nombre: "Búsqueda Filtros Avanzados", descripcion: "Panel de búsqueda con facetas", prompt: "Diseña un componente de barra de búsqueda con panel de filtros avanzados para un marketplace inmobiliario, estética limpia con blanco #FFFFFF, azul océano #0369A1 y verde #059669. Input principal de ubicación, filtros de tipo, rango de precio con slider, dormitorios, checkboxes de amenidades y botón 'Buscar' con contador de resultados. Entregable: HTML + CSS con panel desplegable y chips de filtros activos." },
  { sector: "Componentes", layout: "cards3", nombre: "Casos de Éxito Trío", descripcion: "Tres cards con métrica destacada", prompt: "Diseña un componente de casos de éxito de 3 tarjetas para una plataforma SaaS de ventas B2B, estilo corporativo confiable con blanco #FFFFFF, azul profundo #1D4ED8 y verde métrica #16A34A. Cada card con logo del cliente, métrica grande destacada (+40% ventas), descripción breve del resultado y enlace 'Ver caso'. Entregable: HTML + CSS con número animado y hover de elevación." },
  { sector: "3D", layout: "scene3d", nombre: "Hero Zapatilla Deportiva", descripcion: "Zapatilla flotante que gira ante scroll", prompt: "Construí con Three.js un hero 3D full-screen para una marca de sneakers streetwear: una zapatilla en modelo GLTF flotando sobre un pedestal circular, iluminación de estudio con tres luces (key, fill, rim magenta), rotación automática suave y control por drag del usuario. Paleta negro carbón #0d0d0d con acentos volt #d0ff14 y magenta #ff2d78. Titular gigante 'AIRFLOW 24' con la cámara haciendo dolly al hacer scroll. Entregable: HTML+CSS+JS con Three.js (OrbitControls, GLTFLoader), sombras de contacto y bloom via EffectComposer." },
  { sector: "3D", layout: "scene3d", nombre: "Planeta Habitable", descripcion: "Exoplaneta con atmósfera y nubes", prompt: "Creá con Three.js una escena espacial de un exoplaneta tipo super-Tierra: esfera con shader custom de continentes, capa de nubes en malla separada rotando a distinta velocidad, glow atmosférico con Fresnel y un sol lejano con lens flare. Fondo de campo estelar en Points. Paleta cian glacial #4dd0e1, ocre continental #c98a3b y azul profundo espacial #060a1f. Panel HUD lateral con datos ficticios del planeta (gravedad, temperatura). Entregable: HTML+JS con Three.js, ShaderMaterial para el Fresnel y controles de órbita limitados." },
  { sector: "3D", layout: "scene3d", nombre: "Partículas Interactivas", descripcion: "Nube de partículas que huye del mouse", prompt: "Desarrollá con Three.js un fondo de 50.000 partículas GPU en un BufferGeometry que reaccionan al cursor: las partículas cercanas al puntero se repelen y vuelven a su posición con easing elástico. Estilo tech-startup minimalista, partículas como puntos suaves aditivos. Paleta fondo casi negro #08090c, partículas degradado índigo #6366f1 a cian #22d3ee. Titular centrado 'Inteligencia que fluye'. Entregable: HTML+JS con Three.js, raycasting sobre un plano invisible para el mouse y animación con requestAnimationFrame; blending aditivo." },
  { sector: "3D", layout: "scene3d", nombre: "Configurador de Auto", descripcion: "Visualizador de color y llantas en vivo", prompt: "Armá con Three.js un visualizador de producto para un auto eléctrico de lujo: modelo 3D sobre plataforma reflectante, HDRI de estudio para reflejos realistas, botones para cambiar color de carrocería (paint metalizado con clearcoat) y estilo de llantas en tiempo real. Paleta showroom blanco #f5f5f7, gris grafito #2b2f36 y acento eléctrico #00e0b0. Cámara con auto-rotación pausable y zoom. Entregable: HTML+CSS+JS con Three.js (GLTFLoader, RGBELoader, MeshPhysicalMaterial), panel de UI flotante y sombra de contacto suave." },
  { sector: "3D", layout: "scene3d", nombre: "Terreno Procedural", descripcion: "Montañas generadas con ruido Perlin", prompt: "Generá con Three.js un terreno procedural infinito: plano subdividido deformado por ruido simplex en el vertex shader, con niebla de distancia y sobrevuelo lento de la cámara. Estilo synthwave retro-futurista, grilla wireframe brillante sobre relieve sólido. Paleta noche violeta #1a0b2e, crestas neón rosa #ff3d81 y horizonte naranja #ff9e00 con sol degradado. Entregable: HTML+JS con Three.js, ShaderMaterial con noise GLSL, FogExp2 y un plano de sol con shader de bandas. Bucle sin fin desplazando el offset del ruido." },
  { sector: "3D", layout: "scene3d", nombre: "Galería de Arte 3D", descripcion: "Sala virtual navegable con cuadros", prompt: "Construí con Three.js una galería 3D navegable en primera persona: sala rectangular con piso de madera, paredes claras y cuadros enmarcados con texturas, spotlights individuales por obra e info al acercarse. Estética museo contemporáneo minimalista. Paleta paredes hueso #efece4, piso roble #9c7a4d y acentos de luz cálida #ffd8a8. Movimiento con WASD y mirada con mouse (PointerLockControls). Entregable: HTML+JS con Three.js, PointerLockControls, SpotLight por cuadro y colisión simple contra paredes." },
  { sector: "3D", layout: "scene3d", nombre: "Texto 3D Cinético", descripcion: "Tipografía extruida que se ensambla", prompt: "Creá con Three.js una intro de marca con texto 3D extruido: la palabra 'NOVA' se ensambla desde fragmentos que vuelan y encajan, material cromado con environment map y bevel pronunciado. Estética agencia creativa premium. Paleta fondo grafito #14151a, metal espejo con tintes iridiscentes y acento coral #ff5e57. Reflejos de estudio y bloom en los bordes. Entregable: HTML+JS con Three.js (TextGeometry con FontLoader, MeshStandardMaterial metálico, EffectComposer + UnrealBloomPass), animación de ensamblaje con easing." },
  { sector: "3D", layout: "scene3d", nombre: "Ondas Oceánicas", descripcion: "Malla de olas animadas por shader", prompt: "Armá con Three.js una superficie de olas generada por shader: plano de alta resolución con desplazamiento sinusoidal sumado (Gerstner waves) en el vertex shader, espuma en las crestas y reflejo del cielo. Estética serena tipo marca de bienestar. Paleta agua turquesa #1ca9a0 a azul profundo #0a3d5c, espuma #eafaf7 y cielo pastel #cfe8f0. Cámara en ángulo bajo con leve cabeceo. Entregable: HTML+JS con Three.js, ShaderMaterial con Gerstner GLSL, luz direccional y niebla; sin librerías extra." },
  { sector: "3D", layout: "scene3d", nombre: "Isla Low-Poly", descripcion: "Isla flotante estilizada con agua", prompt: "Generá con Three.js una isla flotante low-poly: terreno facetado con flat shading, árboles y rocas geométricas, cascada de partículas cayendo al vacío y agua de plano semitransparente animado. Estética juego móvil cozy. Paleta pasto #7cc576, arena #e8d5a2, agua #4fb0c6 y cielo lavanda #cdb4f0. Rotación orbital lenta automática. Entregable: HTML+JS con Three.js, geometrías con flatShading, instancing para vegetación, sombras y OrbitControls con auto-rotate." },
  { sector: "3D", layout: "scene3d", nombre: "Hero Frasco de Perfume", descripcion: "Vidrio refractivo sobre pedestal", prompt: "Construí con Three.js un hero 3D para perfume de lujo: frasco de vidrio con material de transmisión (refracción, roughness baja, IOR alto) sobre un pedestal de mármol, HDRI cálido para reflejos y partículas doradas flotando. Estética alta perfumería elegante. Paleta champán #e6c78a, ámbar #b5651d, negro terciopelo #100d0a. Rotación suave y titular serif 'NUIT D'OR'. Entregable: HTML+CSS+JS con Three.js, MeshPhysicalMaterial con transmission, RGBELoader, bloom sutil y Points dorados." },
  { sector: "3D", layout: "scene3d", nombre: "Agujero Negro", descripcion: "Disco de acreción con distorsión", prompt: "Creá con Three.js una escena de agujero negro: esfera negra central rodeada por un disco de acreción de partículas en espiral con blending aditivo naranja-blanco, halo de lente y campo estelar de fondo. Estética ciencia ficción cinematográfica. Paleta vacío #000000, disco incandescente #ff7b00 a #fff4d6 y estrellas frías #9fb8ff. Cámara orbitando lento. Entregable: HTML+JS con Three.js, Points animados en espiral, AdditiveBlending, UnrealBloomPass y OrbitControls; sin modelos externos." },
  { sector: "3D", layout: "scene3d", nombre: "Partículas forman Logo", descripcion: "Nube que converge en un símbolo", prompt: "Desarrollá con Three.js una animación donde miles de partículas dispersas convergen para formar el logotipo de una marca fintech y luego se disuelven en loop. Las posiciones objetivo se muestrean del contorno de un texto/SVG. Estética tech confiable y limpia. Paleta fondo #0b1020, partículas degradado verde menta #2ee6a6 a azul #3b82f6. Entregable: HTML+JS con Three.js, muestreo de puntos desde un canvas de texto, interpolación posición-inicial a posición-objetivo con easing y AdditiveBlending." },
  { sector: "3D", layout: "scene3d", nombre: "Configurador de Reloj", descripcion: "Reloj de lujo con materiales cambiables", prompt: "Armá con Three.js un visualizador de reloj de lujo: modelo con manecillas animadas en hora real, opciones para cambiar material de caja (oro, acero, titanio) y color de correa, iluminación de joyería con reflejos nítidos. Estética relojería suiza premium. Paleta fondo antracita #1c1e22, oro #d4af37, acero #c8ccd0 y esfera azul medianoche #0f2a4a. Zoom y rotación controlados. Entregable: HTML+CSS+JS con Three.js (GLTFLoader o geometría propia, MeshPhysicalMaterial, HDRI), panel de opciones y tween de cámara a detalles." },
  { sector: "3D", layout: "scene3d", nombre: "Cordillera Wireframe", descripcion: "Relieve topográfico en líneas neón", prompt: "Generá con Three.js una cordillera topográfica en wireframe: malla montañosa por heightmap con ruido, renderizada solo en líneas brillantes con líneas de contorno de altura resaltadas y niebla profunda. Estética data-art / dashboard geoespacial. Paleta fondo azul noche #050d1a, líneas cian #17e0d0 y contornos ámbar #ffb02e en cotas altas. Cámara con órbita lenta cenital-oblicua. Entregable: HTML+JS con Three.js, WireframeGeometry o LineSegments, shader que colorea por altura, FogExp2 y OrbitControls." },
  { sector: "3D", layout: "scene3d", nombre: "Museo NFT Virtual", descripcion: "Pabellón oscuro con obras iluminadas", prompt: "Construí con Three.js un pabellón virtual para una colección NFT: sala oscura futurista con pedestales que exhiben obras 3D rotatorias sobre bases emisivas, reflejos en piso pulido y luces de neón perimetrales. Estética cripto-galería nocturna. Paleta negro #060608, piso espejo, neones violeta #8b5cf6 y cian #06d6f5. Navegación orbital entre pedestales. Entregable: HTML+JS con Three.js, MeshReflectorMaterial o plano reflectante, emisivos con bloom, PositionalAudio opcional y OrbitControls." },
  { sector: "3D", layout: "scene3d", nombre: "Tipografía Líquida", descripcion: "Letras que se derriten y rehacen", prompt: "Creá con Three.js un titular 3D con efecto líquido: la palabra 'FLOW' construida en metaballs / marching cubes que se derriten y vuelven a formarse en loop, material iridiscente tipo aceite. Estética editorial experimental de diseño. Paleta fondo crema #f3efe7, superficie tornasolada rosa-cian-violeta y sombra suave. Entregable: HTML+JS con Three.js usando MarchingCubes de examples/jsm, MeshPhysicalMaterial con iridescence, environment map y animación de campos metaball; rotación sutil." },
  { sector: "3D", layout: "scene3d", nombre: "Gigante Gaseoso", descripcion: "Planeta con anillos y lunas", prompt: "Desarrollá con Three.js un gigante gaseoso con anillos: esfera con shader de bandas atmosféricas en movimiento turbulento, sistema de anillos con transparencia y sombra proyectada sobre el planeta, dos lunas orbitando. Estética astronómica cinematográfica. Paleta bandas crema #e8d3a1 y siena #a5622f, anillos gris perla #cfc9bd, espacio #04060f. Cámara orbital lenta. Entregable: HTML+JS con Three.js, ShaderMaterial de bandas con noise, anillo con RingGeometry y textura alfa, Points estelares y OrbitControls." },
  { sector: "3D", layout: "scene3d", nombre: "Océano Realista", descripcion: "Agua PBR con cielo y reflejos", prompt: "Armá con Three.js un océano realista al atardecer usando el ejemplo Water + Sky: superficie con normal map animado, reflejos del cielo procedural con Sun controlable y horizonte infinito. Estética cinematográfica contemplativa. Paleta agua verde-azulada #2e6b6f, cielo durazno #ffb27a a lavanda #7b6ca8, sol dorado #ffd47e. Cámara con leve deriva. Entregable: HTML+JS con Three.js usando Water.js y Sky.js de examples/jsm, PMREMGenerator para el environment y animación del tiempo de las olas." },
  { sector: "3D", layout: "scene3d", nombre: "Ciudad Low-Poly", descripcion: "Metrópolis isométrica con tráfico", prompt: "Generá con Three.js una ciudad low-poly isométrica: bloques de edificios de alturas variadas con ventanas emisivas, autos como cajas moviéndose por avenidas en loop y ciclo día-noche que enciende luces. Estética diorama tech acogedor. Paleta día cielo #bfe3ff con edificios pastel, noche #10162e con ventanas ámbar #ffcf6b. Cámara orbital isométrica. Entregable: HTML+JS con Three.js, instancing para edificios y autos, luz direccional animada para el ciclo día-noche, emisivos con bloom y OrbitControls." },
  { sector: "3D", layout: "scene3d", nombre: "Hero Auriculares", descripcion: "Headphones con despiece animado", prompt: "Construí con Three.js un hero 3D para auriculares premium: el modelo se muestra armado y al hacer scroll hace un despiece (exploded view) separando cojines, driver y arco, con etiquetas de features apareciendo. Estética audio pro minimalista. Paleta fondo #0f1113, producto negro mate con acento cobre #c8794a y texto blanco. Iluminación de estudio suave. Entregable: HTML+CSS+JS con Three.js (GLTFLoader), animación de posiciones ligada al scroll, líneas guía a etiquetas HTML y sombra de contacto." },
  { sector: "3D", layout: "scene3d", nombre: "Salto al Hiperespacio", descripcion: "Warp de estrellas hacia la cámara", prompt: "Creá con Three.js un efecto de warp / hiperespacio: campo de estrellas como líneas estiradas que aceleran hacia el espectador con motion blur, culminando en un destello y un túnel de luz. Estética sci-fi intro de producto. Paleta espacio #02030a, estrellas blanco-azul #dbe7ff y núcleo del túnel cian eléctrico #22e0ff. Bucle con aceleración y desaceleración. Entregable: HTML+JS con Three.js, LineSegments o Points con estiramiento por velocidad, AfterimagePass para el motion blur y bloom; controles de velocidad." },
  { sector: "3D", layout: "scene3d", nombre: "Morphing GPGPU", descripcion: "Partículas que mutan entre formas", prompt: "Desarrollá con Three.js una escena de un millón de partículas que transicionan suavemente entre formas 3D (esfera, toro, cara, texto) usando simulación GPGPU en texturas de posición. Estética generativa de portafolio creativo. Paleta fondo #060608, partículas degradado según velocidad de rosa #ff4d9d a azul #4d7dff. Entregable: HTML+JS con Three.js usando GPUComputationRenderer, shaders de posición/velocidad, muestreo de vértices de geometrías objetivo y AdditiveBlending; botones para cambiar de forma." },
  { sector: "3D", layout: "scene3d", nombre: "Sneaker 360 E-commerce", descripcion: "Rotador de producto con hotspots", prompt: "Armá con Three.js un visor de producto 360 para ficha de e-commerce: zapatilla que el usuario rota con drag, hotspots clicables que abren tooltips de materiales, y botones de vista (superior, lateral, suela) que animan la cámara. Estética retail limpia y brillante. Paleta fondo blanco #ffffff con sombras suaves, producto en colorway azul cobalto #2b4de0 y detalles naranja #ff6a3d. Entregable: HTML+CSS+JS con Three.js (GLTFLoader), OrbitControls con límites, hotspots proyectados a 2D y tween de cámara a vistas predefinidas." },
  { sector: "3D", layout: "scene3d", nombre: "Metaballs Fluidas", descripcion: "Blobs orgánicos que se fusionan", prompt: "Generá con Three.js una escena de metaballs fluidas: esferas orgánicas que se atraen, fusionan y separan con superficie brillante tipo mercurio, flotando en un espacio con reflejos de environment. Estética marca de belleza / skincare futurista. Paleta fondo rosa nude #f6e7e1, superficie perlada con reflejos y acento coral #ff7f6b. Movimiento lento hipnótico. Entregable: HTML+JS con Three.js usando MarchingCubes de examples/jsm, MeshPhysicalMaterial con clearcoat, PMREM environment y física simple de atracción entre blobs." },
  { sector: "3D", layout: "scene3d", nombre: "Globo de Datos", descripcion: "Tierra con arcos de conexión animados", prompt: "Construí con Three.js un globo terráqueo de datos: esfera de la Tierra con textura de puntos (dot-matrix) y arcos luminosos animándose entre ciudades como flujos de datos globales, con puntos pulsantes en los nodos. Estética dashboard corporativo tech. Paleta fondo #070b18, globo azul acero #1e3a5f, arcos cian #33e1ff y nodos ámbar #ffc24d. Rotación automática pausable. Entregable: HTML+JS con Three.js, puntos sobre esfera vía muestreo, arcos como QuadraticBezierCurve3 animados con TubeGeometry o líneas, y OrbitControls con auto-rotate." },
  { sector: "Email", layout: "hero", nombre: "Newsletter Producto SaaS", descripcion: "Novedades mensuales de plataforma B2B", prompt: "Diseña un email HTML+CSS (tabla, ancho 600px, compatible con clientes de correo) para el newsletter mensual de un SaaS de gestión de proyectos. Hero superior con fondo azul índigo (#3730A3) degradado a violeta (#6D28D9), titular blanco 'Novedades de Julio' y captura de pantalla del producto con esquinas redondeadas. Debajo, tres bloques de features con icono lineal, título y un párrafo, cada uno con botón fantasma. Tipografía Inter, acentos en verde menta (#10B981), pie con enlaces de redes y baja. Entregable: un solo archivo .html inline-styled listo para enviar." },
  { sector: "Email", layout: "split", nombre: "Promo Moda Rebajas", descripcion: "Campaña de descuentos e-commerce", prompt: "Crea un email promocional HTML+CSS (600px, inline styles) para una tienda de moda femenina minimalista tipo Scandi. Layout split: mitad izquierda foto editorial de modelo, mitad derecha bloque crema (#F5F0E8) con titular serif 'Hasta -40%' en negro carbón, código VERANO40 en caja punteada y botón negro 'Comprar ahora'. Debajo, grilla de 3 productos con precio tachado. Paleta beige, negro y terracota (#C77B54). Tipografía Playfair Display + Helvetica. Entregable: .html responsive con media query para móvil apilando columnas." },
  { sector: "Email", layout: "hero", nombre: "Bienvenida App Fitness", descripcion: "Onboarding de nueva usuaria", prompt: "Diseña un email de bienvenida HTML+CSS (600px) para una app de entrenamiento en casa, tono enérgico y juvenil. Hero con fondo negro y foto atlética a sangre, titular condensado en amarillo neón (#D4FF00) '¡Empecemos!'. Bloque de 3 pasos numerados en círculos para configurar el perfil, cada uno con microcopy. CTA grande 'Abrir mi plan' en amarillo con texto negro. Barra de progreso decorativa 'Paso 1 de 3'. Tipografía Archivo. Entregable: archivo .html inline-styled con botones bulletproof VML para Outlook." },
  { sector: "Email", layout: "grid", nombre: "Digest Editorial Gastro", descripcion: "Recopilación semanal de recetas", prompt: "Crea un email newsletter HTML+CSS (600px) tipo revista para un blog de cocina de temporada, estético cálido y artesanal. Cabecera con logotipo servido y fecha. Grilla de 4 recetas en 2x2, cada tarjeta con foto cuadrada, categoría en versalitas, título serif y tiempo de preparación. Paleta crema (#FBF7F0), verde oliva (#5C6B3C) y mostaza (#D9A441). Sección lateral 'Ingrediente del mes'. Tipografía Fraunces + Karla. Entregable: .html responsive con grid que colapsa a una columna en móvil." },
  { sector: "Email", layout: "hero", nombre: "Promo Black Friday Tech", descripcion: "Oferta flash de electrónica", prompt: "Diseña un email de campaña Black Friday HTML+CSS (600px) para un e-commerce de gadgets tecnológicos, estilo dark y de alto impacto. Hero negro absoluto (#0A0A0A) con titular gigante glitch 'BLACK FRIDAY' en degradado cian-magenta y contador regresivo estático 'Termina en 48h'. Grilla de 4 productos destacados con badge de -50% rojo. CTA neón 'Ver ofertas'. Franja de urgencia 'Envío gratis hoy'. Tipografía Space Grotesk. Entregable: archivo .html inline con fallbacks para modo oscuro de clientes de correo." },
  { sector: "Email", layout: "split", nombre: "Bienvenida Membresía Premium", descripcion: "Alta en club de suscripción", prompt: "Crea un email de bienvenida HTML+CSS (600px) para una membresía premium de club de vinos, tono elegante y confidencial. Layout split: izquierda fondo burdeos profundo (#5B1A2B) con monograma dorado y 'Bienvenido al Club'; derecha fondo marfil con lista de 4 beneficios exclusivos marcados con serif dorada y botón 'Activar membresía' en dorado (#C9A24B). Sello circular 'Miembro fundador'. Tipografía Cormorant Garamond + Lato. Entregable: .html responsive que apila las mitades en móvil." },
  { sector: "Email", layout: "grid", nombre: "Newsletter Semanal Diseño", descripcion: "Curaduría de enlaces para creativos", prompt: "Diseña un email newsletter HTML+CSS (600px) editorial y tipográfico para una curaduría semanal de diseño y UX. Sin imágenes grandes: predomina texto. Cabecera con número de edición '#42' en display gigante. Lista de 6 enlaces curados, cada uno con número, título en negro, fuente en gris y descripción de una línea. Fondo blanco puro, acento único naranja quemado (#E8622C), separadores finos. Tipografía monoespaciada IBM Plex Mono para metadatos + Georgia para cuerpos. Entregable: archivo .html inline-styled, ligero y muy legible." },
  { sector: "Email", layout: "hero", nombre: "Lanzamiento Curso Online", descripcion: "Promo de inscripción a formación", prompt: "Crea un email promocional HTML+CSS (600px) para el lanzamiento de un curso online de ilustración digital, tono inspirador y colorido. Hero con fondo lavanda (#EDE7FB) e ilustración plana de escritorio creativo, titular 'Aprende a ilustrar en 6 semanas'. Bloque con foto de la instructora y bio breve. Lista de módulos con checks morados. CTA 'Reservar mi plaza' en morado (#7C3AED) con precio early-bird tachado. Prueba social con 2 testimonios. Tipografía Poppins. Entregable: .html responsive inline-styled." },
  { sector: "Email", layout: "split", nombre: "Confirmación de Pedido", descripcion: "Email transaccional de compra", prompt: "Diseña un email transaccional HTML+CSS (600px) de confirmación de pedido para una tienda de café de especialidad, limpio y funcional. Cabecera con check verde y '¡Gracias por tu pedido!'. Layout split del resumen: izquierda miniatura del producto, derecha detalles (cantidad, precio, número de orden #). Bloque de dirección de envío y estimado de entrega. Barra de estado del pedido en 4 etapas. Paleta blanco, marrón espresso (#3E2A20) y verde bosque. Tipografía DM Sans. Entregable: archivo .html inline-styled sin promociones intrusivas." },
  { sector: "Email", layout: "grid", nombre: "Newsletter Viajes Boutique", descripcion: "Destinos seleccionados del mes", prompt: "Crea un email newsletter HTML+CSS (600px) para una agencia de viajes boutique, estético aspiracional y cálido. Hero panorámico de paisaje con overlay y titular serif 'Escápate este otoño'. Grilla de 3 destinos, cada tarjeta con foto vertical, nombre del lugar, precio desde y botón 'Ver viaje'. Sección 'Consejo del viajero' en caja arena. Paleta arena (#E4D5C3), azul océano (#1E5F74) y coral (#E76F51). Tipografía Libre Baskerville + Nunito Sans. Entregable: .html responsive con grid que colapsa en móvil." },
  { sector: "Email", layout: "hero", nombre: "Digest Producto B2B", descripcion: "Resumen de métricas para clientes", prompt: "Diseña un email HTML+CSS (600px) de digest mensual para clientes de una plataforma de analítica de datos, tono profesional y sobrio. Hero claro con saludo personalizado y titular 'Tu resumen de julio'. Fila de 3 KPIs en tarjetas con número grande, etiqueta y flecha de tendencia verde/roja. Mini gráfico de barras dibujado con divs/tablas. Bloque 'Recomendación de la semana' con CTA 'Ver panel completo'. Paleta blanco, azul acero (#1D4ED8) y grises. Tipografía Inter. Entregable: archivo .html inline-styled sin dependencias de imágenes externas para las gráficas." },
  { sector: "Email", layout: "split", nombre: "Reactivación Carrito", descripcion: "Recordatorio de compra abandonada", prompt: "Crea un email de carrito abandonado HTML+CSS (600px) para una tienda de cosmética natural, tono amable y persuasivo. Layout split: izquierda foto del producto olvidado sobre fondo salvia, derecha texto '¿Se te olvidó algo?' con nombre y precio del artículo y botón 'Completar compra' en verde salvia (#87A96B). Franja de incentivo '-10% con código VUELVE10'. Bloque de 3 productos relacionados en miniatura. Paleta salvia, crema y rosa palo. Tipografía Marcellus + Mulish. Entregable: .html responsive inline-styled." },
  { sector: "Web", layout: "grid", nombre: "Portfolio Diseñador Gráfico", descripcion: "Vitrina de proyectos visuales", prompt: "Construye una página portfolio en HTML+CSS para un diseñador gráfico y de branding, estética editorial suiza. Cabecera fija minimal con nombre y menú. Grilla masonry de proyectos con imágenes que revelan título y categoría al hover con overlay. Paleta blanco roto (#FAFAF7), negro tinta y un acento rojo bermellón (#E63946). Tipografía Neue Haas / Helvetica en tamaños grandes, mucho espacio en blanco. Sección 'Sobre mí' de dos columnas y footer con email de contacto grande. Entregable: index.html + styles.css responsive con grid CSS y transiciones suaves." },
  { sector: "Web", layout: "split", nombre: "Portfolio Dev Full-Stack", descripcion: "Landing técnica de programador", prompt: "Construye una página portfolio en HTML+CSS para un desarrollador full-stack, estética dark de terminal moderna. Layout split en el hero: izquierda presentación 'Hola, soy Diego' con rol y stack, derecha bloque de código con sintaxis coloreada estático. Fondo gris carbón (#12141A), acentos verde terminal (#3FB950) y azul. Sección de proyectos en tarjetas con tags de tecnología, enlaces a GitHub y demo. Timeline de experiencia vertical. Tipografía JetBrains Mono para acentos + Inter para cuerpo. Entregable: index.html + styles.css responsive con modo oscuro por defecto." },
  { sector: "Web", layout: "hero", nombre: "Portfolio Fotógrafo", descripcion: "Galería inmersiva a pantalla completa", prompt: "Construye una página portfolio en HTML+CSS para un fotógrafo de retrato y paisaje, estética inmersiva y minimalista. Hero a pantalla completa con una fotografía a sangre, nombre del fotógrafo en tipografía fina superpuesta abajo y flecha de scroll. Al bajar, secciones full-bleed alternando foto grande y series con títulos sobrios. Paleta casi monocroma: negro, blanco y gris cálido, dejando que las fotos manden. Tipografía Cormorant en display ligero. Menú lateral discreto y contacto minimal. Entregable: index.html + styles.css responsive con scroll suave y lazy-load de imágenes." },
  { sector: "Web", layout: "split", nombre: "Currículum Web Interactivo", descripcion: "CV online de profesional", prompt: "Construye un currículum web en HTML+CSS para una profesional de marketing, estético limpio y confiable. Layout split de dos columnas fijas: barra lateral izquierda azul marino (#1B2A4A) con foto circular, datos de contacto, idiomas y barras de habilidades; columna derecha blanca con experiencia, formación y logros en formato timeline. Botón 'Descargar PDF' fijo. Acento dorado suave (#C9A24B). Tipografía Source Sans Pro. Impresión optimizada. Entregable: index.html + styles.css responsive que apila columnas en móvil y con estilos @media print." },
  { sector: "Web", layout: "hero", nombre: "Link-in-Bio Creador", descripcion: "Página de enlaces para redes", prompt: "Construye una página link-in-bio en HTML+CSS para un creador de contenido lifestyle, estética vibrante y mobile-first. Vista centrada tipo móvil: avatar circular, nombre con verificado, bio corta y una pila de botones-enlace grandes redondeados a sus plataformas, cada uno con icono. Fondo con degradado animado sutil coral a fucsia (#FF6B6B → #C44FE0). Botones glassmorphism semitransparentes. Iconos de redes al pie. Tipografía Poppins. Entregable: index.html + styles.css optimizado para pantalla vertical con hover y micro-animaciones." },
  { sector: "Web", layout: "grid", nombre: "Blog Personal Escritor", descripcion: "Revista personal de artículos", prompt: "Construye un blog personal en HTML+CSS para un escritor y ensayista, estética editorial cálida y lectora. Cabecera con nombre en serif grande y navegación por temas. Grilla de artículos: uno destacado ancho arriba y luego tres columnas con fecha, categoría, título y extracto. Paleta papel (#F4EFE6), tinta marrón oscuro y acento verde salvia. Tipografía Lora para titulares + Source Serif para cuerpo, con generoso interlineado. Sidebar con 'Sobre el autor' y suscripción al boletín. Entregable: index.html + styles.css responsive centrado en la legibilidad." },
  { sector: "Web", layout: "grid", nombre: "Portfolio Arquitecto", descripcion: "Catálogo de obras construidas", prompt: "Construye una página portfolio en HTML+CSS para un estudio de arquitectura, estética brutalista refinada. Cabecera con nombre del estudio en mayúsculas y línea divisoria. Grilla asimétrica de proyectos con fotografías arquitectónicas en blanco y negro, número de proyecto, nombre y año; al hover se revela la foto a color. Paleta hormigón: blanco, negro y gris cemento (#8C8C88), un único acento naranja constructivo (#F25C05). Tipografía Helvetica Neue condensada. Sección de filosofía y datos de contacto tabulados. Entregable: index.html + styles.css responsive con grid CSS asimétrico." },
  { sector: "Web", layout: "hero", nombre: "Portfolio Ilustrador", descripcion: "Muestrario colorido de ilustración", prompt: "Construye una página portfolio en HTML+CSS para un ilustrador editorial, estética juguetona y saturada. Hero con ilustración protagonista grande, nombre en tipografía redondeada custom y burbuja '¡Hola!'. Debajo, grilla irregular de ilustraciones con marcos que rotan levemente al hover. Fondo crema (#FFF8E7) con manchas de color de acento amarillo, cian y rosa. Sección de clientes con logos y bloque de contacto tipo nota adhesiva. Tipografía Fredoka + Nunito. Entregable: index.html + styles.css responsive con micro-animaciones lúdicas." },
  { sector: "Web", layout: "split", nombre: "Portfolio UX/UI", descripcion: "Casos de estudio de producto", prompt: "Construye una página portfolio en HTML+CSS para una diseñadora de producto UX/UI, estética clean SaaS. Hero split: izquierda titular 'Diseño experiencias que resuelven' con subrol y CTA 'Ver casos', derecha mockup de app flotante con sombra suave. Sección de casos de estudio en tarjetas grandes con imagen, problema, rol y métrica de impacto. Paleta blanco, azul eléctrico (#2563EB) y lila suave de fondo (#F1F0FB). Tipografía Inter con jerarquía marcada. Bloque de proceso en 4 pasos. Entregable: index.html + styles.css responsive con hover states y grid de casos." },
  { sector: "Web", layout: "hero", nombre: "Link-in-Bio Músico", descripcion: "Hub de lanzamientos y conciertos", prompt: "Construye una página link-in-bio en HTML+CSS para un músico independiente, estética nocturna y sonora. Hero vertical con foto del artista en duotono, nombre en display y último single destacado con botón 'Escuchar ahora'. Pila de enlaces a Spotify, YouTube, entradas y merch, cada uno con su icono de marca. Fondo negro azulado (#0D1B2A) con acentos púrpura neón (#9D4EDD) y ondas de audio decorativas. Lista de próximas fechas de gira. Tipografía Anton para titulares + Barlow. Entregable: index.html + styles.css mobile-first con efectos de brillo." },
  { sector: "Web", layout: "grid", nombre: "Blog Personal Tech", descripcion: "Bitácora de notas técnicas", prompt: "Construye un blog personal en HTML+CSS para un ingeniero de software, estética developer minimalista con soporte de modo claro/oscuro. Cabecera con handle, toggle de tema y navegación. Grilla de posts en lista con fecha monoespaciada, tiempo de lectura, título y tags de tecnología clicables. Bloques de código con resaltado estático. Paleta modo claro blanco/gris y acento verde azulado (#0D9488); modo oscuro fondo #0F172A. Tipografía Inter + Fira Code para código. Sección 'now' y links a proyectos. Entregable: index.html + styles.css responsive con variables CSS para ambos temas." },
  { sector: "Web", layout: "split", nombre: "Currículum Web Consultor", descripcion: "Perfil ejecutivo de alto nivel", prompt: "Construye un currículum web en HTML+CSS para un consultor estratégico senior, estética corporativa premium y sobria. Layout split: panel izquierdo fijo blanco con foto profesional, nombre, titular ejecutivo, contacto y sectores de especialidad; panel derecho con secciones de experiencia en firmas, logros cuantificados en cifras destacadas, formación y publicaciones. Paleta blanco, gris grafito (#2E2E2E) y acento verde botella (#14532D). Tipografía Libre Franklin con detalles serif. Botón 'Solicitar reunión' fijo. Entregable: index.html + styles.css responsive con estilos @media print para exportar a PDF." },
  { sector: "Juegos", layout: "grid", nombre: "Snake Neón Retro", descripcion: "Serpiente neón sobre grilla oscura", prompt: "Construí Snake en HTML5 canvas + JS puro sobre una grilla de 20x20 celdas. Estilo synthwave: fondo #0d0221, grilla con líneas #2d1b4e, serpiente con gradiente neón cian #05d9e8 a magenta #ff2a6d y estela con glow (shadowBlur). Manzana pixelada amarilla pulsante. HUD superior con puntaje y récord en fuente monospace. Controles WASD/flechas, velocidad creciente, game-over con overlay glitch. Entregable: index.html autocontenido con canvas y game loop en requestAnimationFrame." },
  { sector: "Juegos", layout: "grid", nombre: "Pong Arcade CRT", descripcion: "Pong con efecto tubo CRT", prompt: "Programá Pong clásico 2 jugadores en canvas + JS. Estética CRT ámbar sobre negro #000, paletas y pelota monocromas #ffb000 con scanlines y viñeta simulada por overlay CSS. Línea central punteada, marcador gigante tipo dígitos de siete segmentos dibujados a mano. Física de rebote con ángulo según punto de impacto, aceleración progresiva, IA opcional para P2. Sonido beep con WebAudio oscillator. Entregable: HTML+CSS+JS en un archivo, loop a 60fps." },
  { sector: "Juegos", layout: "grid", nombre: "Breakout Cristal", descripcion: "Rompe-ladrillos con ladrillos de vidrio", prompt: "Creá Breakout en canvas + JS con estética glassmorphism: fondo degradado azul #1e3a8a a violeta #6d28d9, ladrillos semitransparentes con blur y bordes brillantes en 6 filas de colores pastel. Bola con rastro de partículas, paleta con reflejo. Power-ups que caen (paleta ancha, multibola), contador de vidas con iconos corazón. Efecto de shake al romper filas. Entregable: index.html único con canvas, colisiones AABB y sistema de partículas." },
  { sector: "Juegos", layout: "grid", nombre: "Memoria Tropical", descripcion: "Cartas de frutas para emparejar", prompt: "Desarrollá un juego de Memoria en grilla 4x4 con HTML/CSS/JS (cartas como divs con flip 3D en CSS transform). Tema tropical: fondo verde selva #14532d, cartas con dorso patrón de hojas y frente con emojis de frutas grandes. Animación de volteo suave 0.5s, resaltado dorado al acertar par, contador de movimientos y cronómetro. Pantalla de victoria con confeti CSS. Entregable: archivo HTML autocontenido, lógica de matching y barajado Fisher-Yates." },
  { sector: "Juegos", layout: "grid", nombre: "Buscaminas Blueprint", descripcion: "Minesweeper estilo plano técnico", prompt: "Implementá Buscaminas 10x10 con HTML/CSS/JS renderizado en grilla de celdas. Estética blueprint: fondo azul cianotipo #0b3d91, líneas y números en blanco tipo plano de ingeniería, banderas como iconos de compás. Números de proximidad con paleta clásica (1 azul, 2 verde, 3 rojo) adaptada a alto contraste. Click izquierdo revela con flood-fill, click derecho bandera, timer y contador de minas. Entregable: index.html único, generación aleatoria de minas y reveal recursivo." },
  { sector: "Juegos", layout: "grid", nombre: "2048 Pastel", descripcion: "Fusión de números tonos pastel", prompt: "Construí 2048 en grilla 4x4 con HTML/CSS/JS. Paleta pastel suave: fondo #faf8ef, celdas vacías #cdc1b4, fichas desde #eee4da (2) escalando a naranjas y dorados con tipografía redondeada bold. Animaciones de deslizamiento y aparición con scale-pop via CSS transform. Marcador y mejor puntaje persistido en localStorage. Controles flechas y swipe táctil. Overlay 'Ganaste' al llegar a 2048 y 'Game Over'. Entregable: archivo HTML autocontenido con lógica de merge y spawn." },
  { sector: "Juegos", layout: "grid", nombre: "Tres en Raya Minimal", descripcion: "Tic-tac-toe monocromo elegante", prompt: "Creá Tic-tac-toe en grilla 3x3 con HTML/CSS/JS minimalista escandinavo: fondo #f5f5f4, líneas finas gris carbón #292524, X en coral #f87171 y O en teal #2dd4bf dibujadas con SVG stroke animado (draw-in). Modo 2 jugadores y modo IA con minimax imbatible seleccionable. Línea ganadora resaltada con trazo animado, marcador de partidas. Entregable: index.html único, minimax en JS y animaciones SVG." },
  { sector: "Juegos", layout: "grid", nombre: "Quiz Relámpago", descripcion: "Trivia con temporizador y streak", prompt: "Programá un Quiz de opción múltiple en HTML/CSS/JS con layout de tarjeta central y 4 respuestas en grilla 2x2. Estética vibrante estilo Kahoot: fondo degradado púrpura #7c3aed a rosa #ec4899, cada opción con color propio (rojo, azul, amarillo, verde) y forma geométrica. Barra de tiempo de 15s que se agota, feedback verde/rojo instantáneo, contador de racha y puntaje ponderado por rapidez. Banco de 10 preguntas en array JSON. Pantalla final con resultado. Entregable: archivo HTML autocontenido." },
  { sector: "Juegos", layout: "scene3d", nombre: "Ruleta de Premios 3D", descripcion: "Rueda giratoria con perspectiva", prompt: "Construí una Ruleta de la fortuna en canvas 2D con ilusión 3D (sombras y gradientes radiales). Estética casino dorado: fondo terciopelo #4a0e0e, aro dorado #d4af37 con luces LED que parpadean, 8 sectores de colores alternos con etiquetas de premio. Giro con física de fricción y desaceleración ease-out, puntero superior con rebote al cruzar topes. Efecto de brillo metálico y sonido tick por sector con WebAudio. Botón GIRAR pulsante. Entregable: index.html único con animación por requestAnimationFrame." },
  { sector: "Juegos", layout: "grid", nombre: "Tetris Vaporwave", descripcion: "Tetris simple estética vaporwave", prompt: "Desarrollá Tetris en canvas + JS sobre tablero 10x20. Estética vaporwave: fondo grid rosa/cian con sol retro, piezas tetromino con gradientes pastel #ff71ce, #01cdfe, #05ffa1 y bordes brillantes. Panel lateral con próxima pieza, puntaje, líneas y nivel. Rotación SRS básica, hard drop, aceleración por nivel, flash al completar líneas. Fuente pixel. Entregable: archivo HTML autocontenido con matriz de colisión y game loop temporizado." },
  { sector: "Juegos", layout: "scene3d", nombre: "Flappy Parallax", descripcion: "Ave con fondo de capas en profundidad", prompt: "Creá un clon de Flappy Bird en canvas + JS con parallax de múltiples capas dando sensación de profundidad. Estética atardecer: cielo degradado naranja #fb923c a púrpura #7c3aed, montañas y nubes en 3 capas a distinta velocidad, tuberías estilizadas verde menta. Ave con animación de aleteo y rotación según velocidad vertical. Física de gravedad y salto, puntaje por tubería, mejor marca en localStorage, pantalla de choque. Entregable: index.html único, generación procedural de obstáculos." },
  { sector: "Juegos", layout: "scene3d", nombre: "Reloj Orbital Creativo", descripcion: "Hora como órbitas planetarias 3D", prompt: "Construí un reloj creativo con Three.js donde horas, minutos y segundos son esferas orbitando un núcleo central en tres anillos concéntricos inclinados en el espacio 3D. Estética cósmica: fondo negro con estrellas, núcleo emisivo dorado, órbitas con líneas tenues, esferas con material metálico y bloom. La posición angular refleja la hora real actualizada cada frame; etiqueta digital flotante opcional. Cámara con leve auto-rotación. Entregable: index.html con Three.js por CDN, escena, luces y render loop." },
  { sector: "Juegos", layout: "scene3d", nombre: "Visualizador de Audio 3D", descripcion: "Barras reactivas al micrófono en 3D", prompt: "Programá un visualizador de audio con Three.js + Web Audio API AnalyserNode que reacciona al micrófono o a un archivo cargado. Estética neón: anillo circular de barras 3D que crecen con las frecuencias, color mapeado por banda (bajos rojo #ff2a6d, medios violeta, altos cian) con bloom y fondo oscuro reflectante. Rotación lenta de cámara, partículas que pulsan con el volumen. Botón para activar micrófono o subir MP3. Entregable: index.html con Three.js por CDN y FFT en tiempo real." },
  { sector: "Juegos", layout: "grid", nombre: "Simón Dice Luces", descripcion: "Memoria de secuencia con sonido", prompt: "Creá Simón (memoria de secuencia) con HTML/CSS/JS: cuatro cuadrantes de colores (verde, rojo, amarillo, azul) formando un círculo dividido, cada uno se ilumina y suena una nota WebAudio distinta. Estética retro-arcade con carcasa oscura #1a1a2e y botones con brillo al activarse. La secuencia crece un paso por ronda, el jugador la repite; error termina la partida mostrando la ronda alcanzada. Nivel de récord persistido. Entregable: archivo HTML autocontenido con temporización de reproducción." },
  { sector: "Juegos", layout: "grid", nombre: "Cuatro en Línea Fichas", descripcion: "Connect Four con caída animada", prompt: "Desarrollá Cuatro en Línea en grilla 7x6 con HTML/CSS/canvas. Estética tablero de madera azul #1d4ed8 con celdas circulares caladas, fichas rojas y amarillas que caen con animación de gravedad y rebote (easing bounce). Detección de victoria horizontal, vertical y diagonal con resaltado de las 4 fichas ganadoras. Modo 2 jugadores y IA por evaluación de tablero. Indicador de turno. Entregable: index.html único con animación de caída por requestAnimationFrame." },
  { sector: "Juegos", layout: "scene3d", nombre: "Asteroides Vectoriales", descripcion: "Nave espacial en campo de asteroides", prompt: "Construí Asteroids en canvas + JS con gráficos vectoriales estilo arcade Atari: fondo negro profundo, nave, asteroides y disparos como polígonos de trazo blanco con glow sutil, sensación de espacio abierto. Física inercial con wrap en los bordes, rotación y empuje de la nave, asteroides que se fragmentan al recibir impacto, sistema de puntaje y vidas. Explosiones de partículas vectoriales. Entregable: archivo HTML autocontenido, colisiones por distancia y game loop." },
  { sector: "Juegos", layout: "scene3d", nombre: "Corredor Infinito 3D", descripcion: "Endless runner con obstáculos en pista", prompt: "Programá un endless runner en Three.js: un cubo/personaje corre por una pista con tres carriles esquivando obstáculos que se acercan en profundidad. Estética low-poly vibrante: pista degradada, cielo pastel #a5b4fc, obstáculos y monedas geométricos con sombras. Cambio de carril con flechas, salto con espacio, velocidad creciente, puntaje por distancia y monedas recolectadas. Niebla al fondo para fade de spawn. Entregable: index.html con Three.js por CDN, generación procedural y detección de colisiones." },
  { sector: "Juegos", layout: "grid", nombre: "Topos al Ataque", descripcion: "Whack-a-mole con reflejos", prompt: "Creá Whack-a-mole en grilla 3x3 de agujeros con HTML/CSS/JS. Estética jardín cartoon: fondo verde césped, agujeros marrones, topos que asoman con animación pop-up y gorros graciosos. Aparecen aleatoriamente con ventana de tiempo decreciente; click o tap suma puntos y muestra golpe con partículas. Cuenta regresiva de 30s, combo por golpes seguidos, ranking en localStorage. Sonido de golpe WebAudio. Entregable: archivo HTML autocontenido con temporizadores y spawn aleatorio." },
  { sector: "Juegos", layout: "grid", nombre: "Sopa de Palabras", descripcion: "Wordle en español con teclado", prompt: "Desarrollá un clon de Wordle en español con HTML/CSS/JS: grilla 6x5 de casillas y teclado en pantalla en grilla QWERTY. Estética limpia clara: fondo #ffffff, casillas con borde gris que revelan verde #6aaa64 (correcta), amarillo #c9b458 (posición) y gris (ausente) con animación flip escalonada. Diccionario de palabras de 5 letras en array, validación de intento, shake si no existe, teclas coloreadas según feedback. Estadísticas de racha. Entregable: index.html único autocontenido." },
  { sector: "Juegos", layout: "grid", nombre: "Sudoku Diario", descripcion: "Sudoku 9x9 con notas y pistas", prompt: "Construí un Sudoku 9x9 con HTML/CSS/JS: grilla con subcuadros 3x3 de bordes gruesos, celdas fijas en negro y editables en azul #2563eb. Estética papel periódico crema #fdf6e3, resaltado de fila, columna y subcuadro de la celda activa, conflictos marcados en rojo. Teclado numérico, modo notas (candidatos pequeños), botón de pista y verificación. Generador con solución única por backtracking y niveles de dificultad. Timer. Entregable: archivo HTML autocontenido con solver." },
  { sector: "Juegos", layout: "grid", nombre: "Sokoban Almacén", descripcion: "Empuja cajas a sus destinos", prompt: "Programá Sokoban en grilla basada en tiles con HTML/CSS/canvas. Estética almacén industrial: fondo hormigón gris #3f3f46, cajas de madera con textura, destinos marcados con círculos amarillos que brillan al llenarse, personaje operario pixelado. El jugador empuja (no tira) cajas; una caja no se mueve si hay pared o caja detrás. 8 niveles definidos en mapas de texto ASCII, contador de movimientos, undo, detección de nivel resuelto. Entregable: index.html único con parser de niveles." },
  { sector: "Juegos", layout: "scene3d", nombre: "Cubo Rubik Interactivo", descripcion: "Rubik 3D girable y mezclable", prompt: "Creá un cubo de Rubik 3x3 interactivo con Three.js: 27 cubies con las seis caras de colores clásicos (blanco, amarillo, rojo, naranja, azul, verde) y bordes negros. Estética estudio limpio con fondo gris claro, iluminación suave y sombra de contacto. Rotación de la vista con arrastre (OrbitControls) y giro de caras por click-drag sobre una fila con animación suave de 90 grados. Botones mezclar y reset, contador de movimientos. Entregable: index.html con Three.js por CDN, lógica de rotación de capas y detección de resuelto." },
]
